		);
	}

	readonly props = $derived.by(
		() =>
			({
				id: this.opts.id.current,
				role: "heading",
				"aria-level": this.opts.level.current,
				[this.root.getBitsAttr("title")]: "",
				...this.root.sharedProps,
				...this.attachment,
			}) as const
	);
}

