import {
	type DateValue,
	getLocalTimeZone,
	isSameDay,
	isSameMonth,
	today,
} from "@internationalized/date";
import {
	attachRef,
	DOMContext,
	type ReadableBoxedValues,
	type WritableBoxedValues,
} from "svelte-toolbelt";
import { Context, watch } from "runed";
import { CalendarRootContext } from "../calendar/calendar.svelte.js";
import type { DateRange, Month } from "$lib/shared/index.js";
import type {
	BitsFocusEvent,
	BitsKeyboardEvent,
	BitsMouseEvent,
	RefAttachment,
	WithRefOpts,
} from "$lib/internal/types.js";
import { useId } from "$lib/internal/use-id.js";
import { boolToStr, boolToEmptyStrOrUndef } from "$lib/internal/attrs.js";
import { type Announcer, getAnnouncer } from "$lib/internal/date-time/announcer.js";
import { type Formatter, createFormatter } from "$lib/internal/date-time/formatter.js";
import {
	calendarAttrs,
	createMonths,
	getCalendarElementProps,
	getCalendarHeadingValue,
	getDefaultYears,
	getIsNextButtonDisabled,
	getIsPrevButtonDisabled,
	getWeekdays,
	handleCalendarKeydown,
	handleCalendarNextPage,
	handleCalendarPrevPage,
	shiftCalendarFocus,
	useEnsureNonDisabledPlaceholder,
	useMonthViewOptionsSync,
	useMonthViewPlaceholderSync,
} from "$lib/internal/date-time/calendar-helpers.svelte.js";
import {
	areAllDaysBetweenValid,
	getDateValueType,
	isAfter,
	isBefore,
	isBetweenInclusive,
	toDate,
} from "$lib/internal/date-time/utils.js";
import type { WeekStartsOn } from "$lib/shared/date/types.js";
import { onMount, untrack } from "svelte";

const RangeCalendarCellContext = new Context<RangeCalendarCellState>("RangeCalendar.Cell");

interface RangeCalendarRootStateOpts
	extends WithRefOpts,
		WritableBoxedValues<{
			value: DateRange;
			placeholder: DateValue;
			startValue: DateValue | undefined;
			endValue: DateValue | undefined;
		}>,
		ReadableBoxedValues<{
			preventDeselect: boolean;
			minValue: DateValue | undefined;
			maxValue: DateValue | undefined;
			disabled: boolean;
			pagedNavigation: boolean;
			weekStartsOn: WeekStartsOn | undefined;
			weekdayFormat: Intl.DateTimeFormatOptions["weekday"];
			isDateDisabled: (date: DateValue) => boolean;
			isDateUnavailable: (date: DateValue) => boolean;
			fixedWeeks: boolean;
			numberOfMonths: number;
			locale: string;
			calendarLabel: string;
			readonly: boolean;
			disableDaysOutsideMonth: boolean;
			excludeDisabled: boolean;
			minDays: number | undefined;
			maxDays: number | undefined;
			/**
			 * This is strictly used by the `DateRangePicker` component to close the popover when a date range
			 * is selected. It is not intended to be used by the user.
			 */
			onRangeSelect?: () => void;
			monthFormat: Intl.DateTimeFormatOptions["month"] | ((month: number) => string);
			yearFormat: Intl.DateTimeFormatOptions["year"] | ((year: number) => string);
		}> {
	defaultPlaceholder: DateValue;
}

export class RangeCalendarRootState {
	static create(opts: RangeCalendarRootStateOpts) {
		return CalendarRootContext.set(new RangeCalendarRootState(opts));
	}

	readonly opts: RangeCalendarRootStateOpts;
	readonly attachment: RefAttachment;
	readonly visibleMonths = $derived.by(() => this.months.map((month) => month.value));
	/**
	 * `today()` resolves the local timezone via `Intl.DateTimeFormat#formatToParts`, which is
	 * far too expensive to run once per rendered cell. We read `months` so this refreshes on
	 * the same cadence the per-cell computation used to (whenever the visible dates change).
	 */
	readonly todayDate = $derived.by(() => {
		this.months;
		return today(getLocalTimeZone());
	});
	months: Month<DateValue>[] = $state([]);
	announcer: Announcer;
	formatter: Formatter;
	accessibleHeadingId = useId();
	focusedValue = $state<DateValue | undefined>(undefined);
	lastPressedDateValue: DateValue | undefined = undefined;
	domContext: DOMContext;

	/**
	 * This derived state holds an array of localized day names for the current
	 * locale and calendar view. It dynamically syncs with the 'weekStartsOn' option,
	 * updating its content when the option changes. Using this state to render the
	 * calendar's days of the week is strongly recommended, as it guarantees that
	 * the days are correctly formatted for the current locale and calendar view.
	 */
	readonly weekdays = $derived.by(() => {
		return getWeekdays({
			months: this.months,
			formatter: this.formatter,
			weekdayFormat: this.opts.weekdayFormat.current,
		});
	});

	readonly isStartInvalid = $derived.by(() => {
		if (!this.opts.startValue.current) return false;
		return (
			this.isDateUnavailable(this.opts.startValue.current) ||
			this.isDateDisabled(this.opts.startValue.current)
		);
	});

	readonly isEndInvalid = $derived.by(() => {
		if (!this.opts.endValue.current) return false;
		return (
			this.isDateUnavailable(this.opts.endValue.current) ||
			this.isDateDisabled(this.opts.endValue.current)
		);
	});

	readonly isInvalid = $derived.by(() => {
		if (this.isStartInvalid || this.isEndInvalid) return true;

		if (
			this.opts.endValue.current &&
			this.opts.startValue.current &&
			isBefore(this.opts.endValue.current, this.opts.startValue.current)
		)
			return true;

		return false;
	});

	readonly isNextButtonDisabled = $derived.by(() => {
		return getIsNextButtonDisabled({
			maxValue: this.opts.maxValue.current,
			months: this.months,
			disabled: this.opts.disabled.current,
		});
	});

	readonly isPrevButtonDisabled = $derived.by(() => {
		return getIsPrevButtonDisabled({
			minValue: this.opts.minValue.current,
			months: this.months,
			disabled: this.opts.disabled.current,
		});
	});

	readonly headingValue = $derived.by(() => {
		this.opts.monthFormat.current;
		this.opts.yearFormat.current;
		return getCalendarHeadingValue({
			months: this.months,
			formatter: this.formatter,
			locale: this.opts.locale.current,
		});
	});

	readonly fullCalendarLabel = $derived.by(
		() => `${this.opts.calendarLabel.current} ${this.headingValue}`
	);

	readonly highlightedRange = $derived.by(() => {
		if (this.opts.startValue.current && this.opts.endValue.current) return null;
		if (!this.opts.startValue.current || !this.focusedValue) return null;

		const isStartBeforeFocused = isBefore(this.opts.startValue.current, this.focusedValue);
		const start = isStartBeforeFocused ? this.opts.startValue.current : this.focusedValue;
		const end = isStartBeforeFocused ? this.focusedValue : this.opts.startValue.current;
		const range = { start, end };

		if (isSameDay(start.add({ days: 1 }), end) || isSameDay(start, end)) {
			return range;
		}

		const isValid = areAllDaysBetweenValid(
			start,
			end,
			this.isDateUnavailable,
			this.isDateDisabled
		);

		if (isValid) return range;
		return null;
	});

	readonly initialPlaceholderYear = $derived.by(() =>
		untrack(() => this.opts.placeholder.current.year)
	);

	readonly defaultYears = $derived.by(() => {
		return getDefaultYears({
			minValue: this.opts.minValue.current,
			maxValue: this.opts.maxValue.current,
			placeholderYear: this.initialPlaceholderYear,
		});
	});

	constructor(opts: RangeCalendarRootStateOpts) {
		this.opts = opts;
		this.attachment = attachRef(opts.ref);
		this.domContext = new DOMContext(opts.ref);
		this.announcer = getAnnouncer(null);
		this.formatter = createFormatter({
			initialLocale: this.opts.locale.current,
			monthFormat: this.opts.monthFormat,
			yearFormat: this.opts.yearFormat,
		});

		this.months = createMonths({
			dateObj: this.opts.placeholder.current,
			weekStartsOn: this.opts.weekStartsOn.current,
			locale: this.opts.locale.current,
			fixedWeeks: this.opts.fixedWeeks.current,
			numberOfMonths: this.opts.numberOfMonths.current,
		});

		$effect.pre(() => {
			if (this.formatter.getLocale() === this.opts.locale.current) return;
			this.formatter.setLocale(this.opts.locale.current);
		});

		onMount(() => {
			this.announcer = getAnnouncer(this.domContext.getDocument());
		});

		/**
		 * Updates the displayed months based on changes in the placeholder values,
		 * which determines the month to show in the calendar.
		 */
		useMonthViewPlaceholderSync({
			placeholder: this.opts.placeholder,
			getVisibleMonths: () => this.visibleMonths,
			weekStartsOn: this.opts.weekStartsOn,
			locale: this.opts.locale,
			fixedWeeks: this.opts.fixedWeeks,
			numberOfMonths: this.opts.numberOfMonths,
			setMonths: this.setMonths,
		});

		/**
		 * Updates the displayed months based on changes in the options values,
		 * which determines the month to show in the calendar.
		 */
		useMonthViewOptionsSync({
			fixedWeeks: this.opts.fixedWeeks,
			locale: this.opts.locale,
			numberOfMonths: this.opts.numberOfMonths,
			placeholder: this.opts.placeholder,
			setMonths: this.setMonths,
			weekStartsOn: this.opts.weekStartsOn,
		});

		/**
		 * Update the accessible heading's text content when the `fullCalendarLabel`
		 * changes.
		 */
		$effect(() => {
			const node = this.domContext.getElementById(this.accessibleHeadingId);
			if (!node) return;
			node.textContent = this.fullCalendarLabel;
		});

		/**
		 * Synchronize the start and end values with the `value` in case
		 * it is updated externally.
		 */
		watch(
			() => this.opts.value.current,
			(value) => {
				if (value.start && value.end) {
					this.opts.startValue.current = value.start;
					this.opts.endValue.current = value.end;
				} else if (value.start) {
					this.opts.startValue.current = value.start;
					this.opts.endValue.current = undefined;
				} else if (value.start === undefined && value.end === undefined) {
					this.opts.startValue.current = undefined;
					this.opts.endValue.current = undefined;
				}
			}
		);

		/**
		 * Synchronize the placeholder value with the current start value
		 */
		watch(
			() => this.opts.value.current,
			(value) => {
				const startValue = value.start;
				if (startValue && this.opts.placeholder.current !== startValue) {
					this.opts.placeholder.current = startValue;
				}
			}
		);

		/**
		 * Check for disabled dates in the selected range when excludeDisabled is enabled
		 */
		watch(
			[
				() => this.opts.startValue.current,
				() => this.opts.endValue.current,
				() => this.opts.excludeDisabled.current,
			],
			([startValue, endValue, excludeDisabled]) => {
				if (!excludeDisabled || !startValue || !endValue) return;

				if (this.#hasDisabledDatesInRange(startValue, endValue)) {
					this.#setStartValue(undefined);
					this.#setEndValue(undefined);
					this.#announceEmpty();
				}
			}
		);

		watch(
			[() => this.opts.startValue.current, () => this.opts.endValue.current],
			([startValue, endValue]) => {
				if (
					this.opts.value.current &&
					this.opts.value.current.start === startValue &&
					this.opts.value.current.end === endValue
				) {
					return;
				}

				if (startValue && endValue) {
					this.#updateValue((prev) => {
						if (prev.start === startValue && prev.end === endValue) {
							return prev;
						}
						if (isBefore(endValue, startValue)) {
							const start = startValue;
							const end = endValue;
							this.#setStartValue(end);
							this.#setEndValue(start);
							if (!this.#isRangeValid(endValue, startValue)) {
								this.#setStartValue(startValue);
								this.#setEndValue(undefined);
								return { start: startValue, end: undefined };
							}
							return { start: endValue, end: startValue };
						} else {
							if (!this.#isRangeValid(startValue, endValue)) {
								this.#setStartValue(endValue);
								this.#setEndValue(undefined);
								return { start: endValue, end: undefined };
							}
							return {
								start: startValue,
								end: endValue,
							};
						}
					});
				} else if (
					this.opts.value.current &&
					this.opts.value.current.start &&
					this.opts.value.current.end
				) {
					this.opts.value.current.start = undefined;
					this.opts.value.current.end = undefined;
				}
			}
		);

		this.shiftFocus = this.shiftFocus.bind(this);
		this.handleCellClick = this.handleCellClick.bind(this);
		this.onkeydown = this.onkeydown.bind(this);
		this.nextPage = this.nextPage.bind(this);
		this.prevPage = this.prevPage.bind(this);
		this.nextYear = this.nextYear.bind(this);
		this.prevYear = this.prevYear.bind(this);
		this.setYear = this.setYear.bind(this);
		this.setMonth = this.setMonth.bind(this);
		this.isDateDisabled = this.isDateDisabled.bind(this);
		this.isDateUnavailable = this.isDateUnavailable.bind(this);
		this.isOutsideVisibleMonths = this.isOutsideVisibleMonths.bind(this);
		this.isSelected = this.isSelected.bind(this);

		useEnsureNonDisabledPlaceholder({
			placeholder: opts.placeholder,
			defaultPlaceholder: opts.defaultPlaceholder,
			isDateDisabled: opts.isDateDisabled,
			maxValue: opts.maxValue,
			minValue: opts.minValue,
			ref: opts.ref,
		});
	}

	#updateValue(cb: (value: DateRange) => DateRange) {
		const value = this.opts.value.current;
		const newValue = cb(value);
		this.opts.value.current = newValue;
		if (newValue.start && newValue.end) {
			this.opts.onRangeSelect?.current?.();
		}
	}

	#setStartValue(value: DateValue | undefined) {
		this.opts.startValue.current = value;
		// update the main value prop immediately for external consumers
		this.#updateValue((prev) => ({
			...prev,
			start: value,
		}));
	}

	#setEndValue(value: DateValue | undefined) {
		this.opts.endValue.current = value;
		// update the main value prop immediately for external consumers
		this.#updateValue((prev) => ({
			...prev,
			end: value,
		}));
	}

	setMonths = (months: Month<DateValue>[]) => {
		this.months = months;
	};

	isOutsideVisibleMonths(date: DateValue) {
		return !this.visibleMonths.some((month) => isSameMonth(date, month));
	}

	isDateDisabled(date: DateValue) {
		if (this.opts.isDateDisabled.current(date) || this.opts.disabled.current) return true;
		const minValue = this.opts.minValue.current;
		const maxValue = this.opts.maxValue.current;
		if (minValue && isBefore(date, minValue)) return true;
		if (maxValue && isAfter(date, maxValue)) return true;
		return false;
	}

	isDateUnavailable(date: DateValue) {
		if (this.opts.isDateUnavailable.current(date)) return true;
		return false;
	}

	isSelectionStart(date: DateValue) {
		if (!this.opts.startValue.current) return false;
		return isSameDay(date, this.opts.startValue.current);
	}

	isSelectionEnd(date: DateValue) {
		if (!this.opts.endValue.current) return false;
		return isSameDay(date, this.opts.endValue.current);
	}

	isSelected(date: DateValue) {
		if (this.opts.startValue.current && isSameDay(this.opts.startValue.current, date))
			return true;
		if (this.opts.endValue.current && isSameDay(this.opts.endValue.current, date)) return true;
		if (this.opts.startValue.current && this.opts.endValue.current) {
			return isBetweenInclusive(
				date,
				this.opts.startValue.current,
				this.opts.endValue.current
			);
		}
		return false;
	}

	#isRangeValid(start: DateValue, end: DateValue): boolean {
		// ensure we always use the correct order for calculation
		const orderedStart = isBefore(end, start) ? end : start;
		const orderedEnd = isBefore(end, start) ? start : end;

		const startDate = orderedStart.toDate(getLocalTimeZone());
		const endDate = orderedEnd.toDate(getLocalTimeZone());

		const timeDifference = endDate.getTime() - startDate.getTime();
		const daysDifference = Math.floor(timeDifference / (1000 * 60 * 60 * 24));
		const daysInRange = daysDifference + 1; // +1 to include both start and end days

		if (this.opts.minDays.current && daysInRange < this.opts.minDays.current) return false;
		if (this.opts.maxDays.current && daysInRange > this.opts.maxDays.current) return false;

		// check for disabled dates in range if excludeDisabled is enabled
		if (
			this.opts.excludeDisabled.current &&
			this.#hasDisabledDatesInRange(orderedStart, orderedEnd)
		) {
			return false;
		}

		return true;
	}

	shiftFocus(node: HTMLElement, add: number) {
		return shiftCalendarFocus({
			node,
			add,
			placeholder: this.opts.placeholder,
			calendarNode: this.opts.ref.current,
			isPrevButtonDisabled: this.isPrevButtonDisabled,
			isNextButtonDisabled: this.isNextButtonDisabled,
			months: this.months,
			numberOfMonths: this.opts.numberOfMonths.current,
		});
	}

	#announceEmpty() {
		this.announcer.announce("Selected date is now empty.", "polite");
	}

	#announceSelectedDate(date: DateValue) {
		this.announcer.announce(
			`Selected Date: ${this.formatter.selectedDate(date, false)}`,
			"polite"
		);
	}

	#announceSelectedRange(start: DateValue, end: DateValue) {
		this.announcer.announce(
			`Selected Dates: ${this.formatter.selectedDate(start, false)} to ${this.formatter.selectedDate(end, false)}`,
			"polite"
		);
	}

	handleCellClick(e: Event, date: DateValue) {
		if (this.isDateDisabled(date) || this.isDateUnavailable(date)) return;
		const prevLastPressedDate = this.lastPressedDateValue;
		this.lastPressedDateValue = date;

		if (this.opts.startValue.current && this.highlightedRange === null) {
			if (
				isSameDay(this.opts.startValue.current, date) &&
				!this.opts.preventDeselect.current &&
				!this.opts.endValue.current
			) {
				this.#setStartValue(undefined);
				this.opts.placeholder.current = date;
				this.#announceEmpty();
				return;
			} else if (!this.opts.endValue.current) {
				e.preventDefault();
				if (prevLastPressedDate && isSameDay(prevLastPressedDate, date)) {
					this.#setStartValue(date);
					this.#announceSelectedDate(date);
				}
			}
		}

		if (
			this.opts.startValue.current &&
			this.opts.endValue.current &&
			isSameDay(this.opts.endValue.current, date) &&
			!this.opts.preventDeselect.current
		) {
			this.#setStartValue(undefined);
			this.#setEndValue(undefined);
			this.opts.placeholder.current = date;
			this.#announceEmpty();
			return;
		}

		if (!this.opts.startValue.current) {
			this.#announceSelectedDate(date);
			this.#setStartValue(date);
		} else if (!this.opts.endValue.current) {
			// determine the start and end dates for validation
			const startDate = this.opts.startValue.current;
			const endDate = date;
			const orderedStart = isBefore(endDate, startDate) ? endDate : startDate;
			const orderedEnd = isBefore(endDate, startDate) ? startDate : endDate;

			// check if the range violates constraints
			if (!this.#isRangeValid(orderedStart, orderedEnd)) {
				// reset to just the clicked date
				this.#setStartValue(date);
				this.#setEndValue(undefined);
				this.#announceSelectedDate(date);
			} else {
				// ensure start and end are properly ordered
				if (isBefore(endDate, startDate)) {
					// backward selection - reorder the values
					this.#setStartValue(endDate);
					this.#setEndValue(startDate);
					this.#announceSelectedRange(endDate, startDate);
				} else {
					// forward selection - keep original order
					this.#setEndValue(date);
					this.#announceSelectedRange(this.opts.startValue.current, date);
				}
			}
		} else if (this.opts.endValue.current && this.opts.startValue.current) {
			this.#setEndValue(undefined);
			this.#announceSelectedDate(date);
			this.#setStartValue(date);
		}
	}

	onkeydown(event: BitsKeyboardEvent) {
		return handleCalendarKeydown({
			event,
			handleCellClick: this.handleCellClick,
			placeholderValue: this.opts.placeholder.current,
			shiftFocus: this.shiftFocus,
		});
	}

	/**
	 * Navigates to the next page of the calendar.
	 */
	nextPage() {
		handleCalendarNextPage({
			fixedWeeks: this.opts.fixedWeeks.current,
			locale: this.opts.locale.current,
			numberOfMonths: this.opts.numberOfMonths.current,
			pagedNavigation: this.opts.pagedNavigation.current,
			setMonths: this.setMonths,
			setPlaceholder: (date: DateValue) => (this.opts.placeholder.current = date),
			weekStartsOn: this.opts.weekStartsOn.current,
			months: this.months,
		});
	}

	/**
	 * Navigates to the previous page of the calendar.
	 */
	prevPage() {
		handleCalendarPrevPage({
			fixedWeeks: this.opts.fixedWeeks.current,
			locale: this.opts.locale.current,
			numberOfMonths: this.opts.numberOfMonths.current,
			pagedNavigation: this.opts.pagedNavigation.current,
			setMonths: this.setMonths,
			setPlaceholder: (date: DateValue) => (this.opts.placeholder.current = date),
			weekStartsOn: this.opts.weekStartsOn.current,
			months: this.months,
		});
	}

	nextYear() {
		this.opts.placeholder.current = this.opts.placeholder.current.add({ years: 1 });
	}

	prevYear() {
		this.opts.placeholder.current = this.opts.placeholder.current.subtract({ years: 1 });
	}

	setYear(year: number) {
		this.opts.placeholder.current = this.opts.placeholder.current.set({ year });
	}

	setMonth(month: number) {
		this.opts.placeholder.current = this.opts.placeholder.current.set({ month });
	}

	getBitsAttr: (typeof calendarAttrs)["getAttr"] = (part) => {
		return calendarAttrs.getAttr(part, "range-calendar");
	};

	readonly snippetProps = $derived.by(() => ({
		months: this.months,
		weekdays: this.weekdays,
	}));

	readonly props = $derived.by(
		() =>
			({
				...getCalendarElementProps({
					fullCalendarLabel: this.fullCalendarLabel,
					id: this.opts.id.current,
					isInvalid: this.isInvalid,
					disabled: this.opts.disabled.current,
					readonly: this.opts.readonly.current,
				}),
				[this.getBitsAttr("root")]: "",
				//
				onkeydown: this.onkeydown,
				...this.attachment,
			}) as const
	);

	#hasDisabledDatesInRange(start: DateValue, end: DateValue): boolean {
		for (
			let date = start;
			isBefore(date, end) || isSameDay(date, end);
			date = date.add({ days: 1 })
		) {
			if (this.isDateDisabled(date)) return true;
		}
		return false;
	}
}

interface RangeCalendarCellStateOpts
	extends WithRefOpts,
		ReadableBoxedValues<{
			date: DateValue;
			month: DateValue;
		}> {}

export class RangeCalendarCellState {
	static create(opts: RangeCalendarCellStateOpts) {
		return RangeCalendarCellContext.set(
			new RangeCalendarCellState(opts, CalendarRootContext.get() as RangeCalendarRootState)
		);
	}
	readonly opts: RangeCalendarCellStateOpts;
	readonly root: RangeCalendarRootState;
	readonly attachment: RefAttachment;
	readonly cellDate = $derived.by(() => toDate(this.opts.date.current));
	readonly isOutsideMonth = $derived.by(
		() => !isSameMonth(this.opts.date.current, this.opts.month.current)
	);
	readonly isDisabled = $derived.by(
		() =>
			this.root.isDateDisabled(this.opts.date.current) ||
			(this.isOutsideMonth && this.root.opts.disableDaysOutsideMonth.current)
	);
	readonly isUnavailable = $derived.by(() =>
		this.root.opts.isDateUnavailable.current(this.opts.date.current)
	);
	readonly isDateToday = $derived.by(() =>
		isSameDay(this.opts.date.current, this.root.todayDate)
	);

	readonly isOutsideVisibleMonths = $derived.by(() =>
		this.root.isOutsideVisibleMonths(this.opts.date.current)
	);
	readonly isFocusedDate = $derived.by(() =>
		isSameDay(this.opts.date.current, this.root.opts.placeholder.current)
	);
	readonly isSelectedDate = $derived.by(() => this.root.isSelected(this.opts.date.current));
	readonly isSelectionStart = $derived.by(() =>
		this.root.isSelectionStart(this.opts.date.current)
	);

	readonly isRangeStart = $derived.by(() => this.root.isSelectionStart(this.opts.date.current));

	readonly isRangeEnd = $derived.by(() => {
		if (!this.root.opts.endValue.current)
			return this.root.isSelectionStart(this.opts.date.current);
		return this.root.isSelectionEnd(this.opts.date.current);
	});

	readonly isRangeMiddle = $derived.by(() => this.isSelectionMiddle);

	readonly isSelectionMiddle = $derived.by(() => {
		return this.isSelectedDate && !this.isSelectionStart && !this.isSelectionEnd;
	});

	readonly isSelectionEnd = $derived.by(() => this.root.isSelectionEnd(this.opts.date.current));
	readonly isHighlighted = $derived.by(() =>
		this.root.highlightedRange
			? isBetweenInclusive(
					this.opts.date.current,
					this.root.highlightedRange.start,
					this.root.highlightedRange.end
				)
			: false
	);

	readonly labelText = $derived.by(() =>
		this.root.formatter.custom(this.cellDate, {
			weekday: "long",
			month: "long",
			day: "numeric",
			year: "numeric",
		})
	);

	constructor(opts: RangeCalendarCellStateOpts, root: RangeCalendarRootState) {
		this.opts = opts;
		this.root = root;
		this.attachment = attachRef(opts.ref);
	}

	readonly snippetProps = $derived.by(() => ({
		disabled: this.isDisabled,
		unavailable: this.isUnavailable,
		selected: this.isSelectedDate,
	}));

	readonly ariaDisabled = $derived.by(() => {
		return (
			this.isDisabled ||
			(this.isOutsideMonth && this.root.opts.disableDaysOutsideMonth.current) ||
			this.isUnavailable
		);
	});

	readonly sharedDataAttrs = $derived.by(
		() =>
			({
				"data-unavailable": boolToEmptyStrOrUndef(this.isUnavailable),
				"data-today": this.isDateToday ? "" : undefined,
				"data-outside-month": this.isOutsideMonth ? "" : undefined,
				"data-outside-visible-months": this.isOutsideVisibleMonths ? "" : undefined,
				"data-focused": this.isFocusedDate ? "" : undefined,
				"data-selection-start": this.isSelectionStart ? "" : undefined,
				"data-selection-end": this.isSelectionEnd ? "" : undefined,
				"data-range-start": this.isRangeStart ? "" : undefined,
				"data-range-end": this.isRangeEnd ? "" : undefined,
				"data-range-middle": this.isRangeMiddle ? "" : undefined,
				"data-highlighted": this.isHighlighted ? "" : undefined,
				"data-selected": boolToEmptyStrOrUndef(this.isSelectedDate),
				"data-value": this.opts.date.current.toString(),
				"data-type": getDateValueType(this.opts.date.current),
				"data-disabled": boolToEmptyStrOrUndef(
					this.isDisabled ||
						(this.isOutsideMonth && this.root.opts.disableDaysOutsideMonth.current)
				),
			}) as const
	);

	readonly props = $derived.by(
		() =>
			({
				id: this.opts.id.current,
				role: "gridcell",
				"aria-selected": boolToStr(this.isSelectedDate),
				"aria-disabled": boolToStr(this.ariaDisabled),
				...this.sharedDataAttrs,
				[this.root.getBitsAttr("cell")]: "",
				...this.attachment,
			}) as const
	);
}

interface RangeCalendarDayStateOpts extends WithRefOpts {}

export class RangeCalendarDayState {
	static create(opts: RangeCalendarDayStateOpts) {
		return new RangeCalendarDayState(opts, RangeCalendarCellContext.get());
	}

	readonly opts: RangeCalendarDayStateOpts;
	readonly cell: RangeCalendarCellState;
	readonly attachment: RefAttachment;

	constructor(opts: RangeCalendarDayStateOpts, cell: RangeCalendarCellState) {
		this.opts = opts;
		this.cell = cell;
		this.attachment = attachRef(opts.ref);

		this.onclick = this.onclick.bind(this);
		this.onmouseenter = this.onmouseenter.bind(this);
		this.onfocusin = this.onfocusin.bind(this);
	}

	readonly #tabindex = $derived.by(() =>
		(this.cell.isOutsideMonth && this.cell.root.opts.disableDaysOutsideMonth.current) ||
		this.cell.isDisabled
			? undefined
			: this.cell.isFocusedDate
				? 0
				: -1
	);

	onclick(e: BitsMouseEvent) {
		if (this.cell.isDisabled) return;
		this.cell.root.handleCellClick(e, this.cell.opts.date.current);
	}

	onmouseenter(_: BitsMouseEvent) {
		if (this.cell.isDisabled) return;
		this.cell.root.focusedValue = this.cell.opts.date.current;
	}

	onfocusin(_: BitsFocusEvent) {
		if (this.cell.isDisabled) return;
		this.cell.root.focusedValue = this.cell.opts.date.current;
	}

	readonly snippetProps = $derived.by(() => ({
		disabled: this.cell.isDisabled,
		unavailable: this.cell.isUnavailable,
		selected: this.cell.isSelectedDate,
		day: `${this.cell.opts.date.current.day}`,
	}));

	readonly props = $derived.by(
		() =>
			({
				id: this.opts.id.current,
				role: "button",
				"aria-label": this.cell.labelText,
				"aria-disabled": boolToStr(this.cell.ariaDisabled),
				...this.cell.sharedDataAttrs,
				tabindex: this.#tabindex,
				[this.cell.root.getBitsAttr("day")]: "",
				// Shared logic for range calendar and calendar
				"data-bits-day": "",
				//
				onclick: this.onclick,
				onmouseenter: this.onmouseenter,
				onfocusin: this.onfocusin,
				...this.attachment,
			}) as const
	);
}

export { default as Root } from "./components/rating-group.svelte";
export { default as Item } from "./components/rating-group-item.svelte";

export type {
	RatingGroupRootProps as RootProps,
	RatingGroupItemProps as ItemProps,
} from "./types.js";

import {
	attachRef,
	DOMContext,
	type ReadableBoxedValues,
	type WritableBoxedValues,
} from "svelte-toolbelt";
import { Context } from "runed";
import type {
	BitsKeyboardEvent,
	BitsMouseEvent,
	BitsPointerEvent,
	RefAttachment,
	WithRefOpts,
} from "$lib/internal/types.js";
import { createBitsAttrs, boolToStr, boolToEmptyStrOrUndef } from "$lib/internal/attrs.js";
import type {
	RatingGroupAriaValuetext,
	RatingGroupItemState as RatingGroupItemStateType,
} from "./types.js";
import type { Orientation } from "$lib/shared/index.js";
import { kbd } from "$lib/internal/kbd.js";

const ratingGroupAttrs = createBitsAttrs({
	component: "rating-group",
	parts: ["root", "item"],
});

const RatingGroupRootContext = new Context<RatingGroupRootState>("RatingGroup.Root");

interface RatingGroupRootStateOpts
	extends WithRefOpts,
		ReadableBoxedValues<{
			disabled: boolean;
			required: boolean;
			orientation: Orientation;
			name: string | undefined;
			min: number;
			max: number;
			allowHalf: boolean;
			readonly: boolean;
			hoverPreview: boolean;
			ariaValuetext: NonNullable<RatingGroupAriaValuetext>;
		}>,
		WritableBoxedValues<{ value: number }> {}

export class RatingGroupRootState {
	static create(opts: RatingGroupRootStateOpts) {
		return RatingGroupRootContext.set(new RatingGroupRootState(opts));
	}

	readonly opts: RatingGroupRootStateOpts;
	readonly attachment: RefAttachment;

	#hoverValue = $state<number | null>(null);
	#keySequence = $state<string>("");
	#keySequenceTimeout: number | null = null;
	domContext: DOMContext;

	readonly hasValue = $derived.by(() => this.opts.value.current > 0);
	readonly valueToUse = $derived.by(() => this.#hoverValue ?? this.opts.value.current);
	readonly isRTL = $derived.by(() => {
		const element = this.opts.ref.current;
		if (!element) return false;
		const style = getComputedStyle(element);
		return style.direction === "rtl";
	});

	readonly ariaValuetext = $derived.by(() => {
		return typeof this.opts.ariaValuetext.current === "function"
			? this.opts.ariaValuetext.current(this.opts.value.current, this.opts.max.current)
			: this.opts.ariaValuetext.current;
	});

	readonly items = $derived.by(() => {
		const value = this.valueToUse;

		return Array.from({ length: this.opts.max.current }, (_, i) => {
			const itemValue = i + 1;
			const halfValue = itemValue - 0.5;

			const state: RatingGroupItemStateType =
				value >= itemValue
					? "active"
					: this.opts.allowHalf.current && value >= halfValue
						? "partial"
						: "inactive";

			return { index: i, state };
		});
	});

	constructor(opts: RatingGroupRootStateOpts) {
		this.opts = opts;
		this.attachment = attachRef(opts.ref);
		this.onkeydown = this.onkeydown.bind(this);
		this.onpointerleave = this.onpointerleave.bind(this);
		this.domContext = new DOMContext(this.opts.ref);
	}

	isActive(itemIndex: number): boolean {
		return this.valueToUse >= itemIndex + 1;
	}

	isPartial(itemIndex: number): boolean {
		if (!this.opts.allowHalf.current) return false;
		const itemValue = itemIndex + 1;
		return this.valueToUse >= itemValue - 0.5 && this.valueToUse < itemValue;
	}

	setHoverValue(value: number | null): void {
		if (
			this.opts.readonly.current ||
			this.opts.disabled.current ||
			!this.opts.hoverPreview.current
		)
			return;

		this.#hoverValue =
			value === null
				? null
				: Math.max(this.opts.min.current, Math.min(this.opts.max.current, value));
	}

	setValue(value: number): void {
		if (this.opts.readonly.current || this.opts.disabled.current) return;
		this.opts.value.current = Math.max(
			this.opts.min.current,
			Math.min(this.opts.max.current, value)
		);
	}

	calculateRatingFromPointer(
		itemIndex: number,
		event: { clientX: number; clientY: number; currentTarget: HTMLElement }
	): number {
		const ratingValue = itemIndex + 1;
		if (!this.opts.allowHalf.current) return ratingValue;

		const rect = event.currentTarget.getBoundingClientRect();
		const style = getComputedStyle(event.currentTarget);
		const isHorizontal = this.opts.orientation.current === "horizontal";

		const position = isHorizontal
			? (event.clientX - rect.left) / rect.width
			: (event.clientY - rect.top) / rect.height;

		const normalizedPosition = style.direction === "rtl" ? 1 - position : position;

		return normalizedPosition < 0.5 ? ratingValue - 0.5 : ratingValue;
	}

	onpointerleave(): void {
		this.setHoverValue(null);
	}

	readonly handlers: Record<string, () => void> = {
		[kbd.ARROW_UP]: () => {
			this.setHoverValue(null);
			this.#adjustValue(this.opts.allowHalf.current ? 0.5 : 1);
		},
		[kbd.ARROW_RIGHT]: () => {
			this.setHoverValue(null);
			const increment = this.opts.allowHalf.current ? 0.5 : 1;
			// in RTL mode, right arrow should decrement
			this.#adjustValue(this.isRTL ? -increment : increment);
		},
		[kbd.ARROW_DOWN]: () => {
			this.setHoverValue(null);
			this.#adjustValue(this.opts.allowHalf.current ? -0.5 : -1);
		},
		[kbd.ARROW_LEFT]: () => {
			this.setHoverValue(null);
			const increment = this.opts.allowHalf.current ? 0.5 : 1;
			// in RTL mode, left arrow should increment
			this.#adjustValue(this.isRTL ? increment : -increment);
		},
		[kbd.HOME]: () => {
			this.setHoverValue(null);
			this.setValue(this.opts.min.current);
		},
		[kbd.END]: () => {
			this.setHoverValue(null);
			this.setValue(this.opts.max.current);
		},
		[kbd.PAGE_UP]: () => {
			this.setHoverValue(null);
			this.#adjustValue(1);
		},
		[kbd.PAGE_DOWN]: () => {
			this.setHoverValue(null);
			this.#adjustValue(-1);
		},
	};

	onkeydown(e: BitsKeyboardEvent): void {
		if (this.opts.disabled.current || this.opts.readonly.current) return;

		if (this.handlers[e.key]) {
			e.preventDefault();
			this.#clearKeySequence();
			this.handlers[e.key]?.();
			return;
		}

		if (this.opts.allowHalf.current && this.#handleDecimalInput(e)) return;

		// handle direct number input
		const num = parseInt(e.key || "");
		if (!isNaN(num) && e.key) {
			e.preventDefault();
			if (num >= this.opts.min.current && num <= this.opts.max.current) {
				this.setValue(num);
				if (this.opts.allowHalf.current) {
					this.#startDecimalListening(num);
				}
			}
			return;
		}

		this.#clearKeySequence();
	}

	#adjustValue(delta: number): void {
		this.setValue(this.opts.value.current + delta);
	}

	#handleDecimalInput(e: BitsKeyboardEvent): boolean {
		if (!e.key) return false;

		if (e.key === ".") {
			e.preventDefault();
			this.#keySequence += e.key;
			return true;
		}

		if (e.key === "5" && this.#keySequence.match(/^\d+\.$/)) {
			e.preventDefault();
			this.#keySequence += e.key;

			const match = this.#keySequence.match(/^(\d+)\.5$/);
			if (match?.[1]) {
				const value = parseFloat(this.#keySequence);
				if (value >= this.opts.min.current && value <= this.opts.max.current) {
					this.setValue(value);
					this.#clearKeySequence();
				}
			}
			return true;
		}

		return false;
	}

	#startDecimalListening(baseValue: number): void {
		this.#keySequence = baseValue.toString();

		if (this.#keySequenceTimeout) {
			this.domContext.clearTimeout(this.#keySequenceTimeout);
		}

		this.#keySequenceTimeout = this.domContext.setTimeout(() => this.#clearKeySequence(), 1000);
	}

	#clearKeySequence(): void {
		this.#keySequence = "";
		if (this.#keySequenceTimeout) {
			this.domContext.clearTimeout(this.#keySequenceTimeout);
			this.#keySequenceTimeout = null;
		}
	}

	readonly snippetProps = $derived.by(() => ({
		items: this.items,
		value: this.opts.value.current,
		max: this.opts.max.current,
	}));

	readonly props = $derived.by(() => {
		return {
			id: this.opts.id.current,
			role: "slider",
			"aria-valuenow": this.opts.value.current,
			"aria-valuemin": this.opts.min.current,
			"aria-valuemax": this.opts.max.current,
			"aria-valuetext": this.ariaValuetext,
			"aria-orientation": this.opts.orientation.current,
			"aria-required": boolToStr(this.opts.required.current),
			"aria-disabled": this.opts.disabled.current ? "true" : undefined,
			"aria-label": "Rating",
			"data-disabled": boolToEmptyStrOrUndef(this.opts.disabled.current),
			"data-readonly": this.opts.readonly.current ? "" : undefined,
			"data-orientation": this.opts.orientation.current,
			tabindex: this.opts.disabled.current ? -1 : 0,
			[ratingGroupAttrs.root]: "",
			onkeydown: this.onkeydown,
			onpointerleave: this.onpointerleave,
			...this.attachment,
		} as const;
	});
}

interface RatingGroupItemStateOpts
	extends WithRefOpts,
		ReadableBoxedValues<{
			disabled: boolean;
			index: number;
		}> {}

export class RatingGroupItemState {
	static create(opts: RatingGroupItemStateOpts) {
		return new RatingGroupItemState(opts, RatingGroupRootContext.get());
	}

	readonly opts: RatingGroupItemStateOpts;
	readonly root: RatingGroupRootState;
	readonly attachment: RefAttachment;
	readonly #isDisabled = $derived.by(
		() => this.opts.disabled.current || this.root.opts.disabled.current
	);
	readonly #isActive = $derived.by(() => this.root.isActive(this.opts.index.current));
	readonly #isPartial = $derived.by(() => this.root.isPartial(this.opts.index.current));
	readonly #state: RatingGroupItemStateType = $derived.by(() => {
		if (this.#isActive) return "active";
		if (this.#isPartial) return "partial";
		return "inactive";
	});

	constructor(opts: RatingGroupItemStateOpts, root: RatingGroupRootState) {
		this.opts = opts;
		this.root = root;
		this.attachment = attachRef(opts.ref);

		this.onclick = this.onclick.bind(this);
		this.onpointermove = this.onpointermove.bind(this);
	}

	onclick(e: BitsMouseEvent) {
		if (this.#isDisabled || this.root.opts.readonly.current) return;

		// handle clearing when clicking on first item (index 0) that's already
		// active and min is 0
		if (
			this.opts.index.current === 0 &&
			this.root.opts.min.current === 0 &&
			this.root.opts.value.current > 0
		) {
			const newValue = this.root.calculateRatingFromPointer(this.opts.index.current, e);
			const currentValue = this.root.opts.value.current;

			// only clear if the calculated rating exactly matches current value
			if (newValue === currentValue) {
				this.root.setValue(0);
				if (this.root.opts.ref.current) {
					this.root.opts.ref.current.focus();
				}
				return;
			}
		}

		const newValue = this.root.calculateRatingFromPointer(this.opts.index.current, e);
		this.root.setValue(newValue);

		if (this.root.opts.ref.current) {
			this.root.opts.ref.current.focus();
		}
	}

	onpointermove(e: BitsPointerEvent) {
		if (
			this.#isDisabled ||
			this.root.opts.readonly.current ||
			!this.root.opts.hoverPreview.current
		)
			return;

		// skip hover preview for touch devices
		if (e.pointerType === "touch") return;

		const hoverValue = this.root.calculateRatingFromPointer(this.opts.index.current, e);
		this.root.setHoverValue(hoverValue);
	}

	readonly snippetProps = $derived.by(() => {
		return {
			state: this.#state,
		} as const;
	});

	readonly props = $derived.by(
		() =>
			({
				id: this.opts.id.current,
				role: "presentation",
				"data-value": this.opts.index.current + 1,
				"data-orientation": this.root.opts.orientation.current,
				"data-disabled": boolToEmptyStrOrUndef(this.#isDisabled),
				"data-readonly": this.root.opts.readonly.current ? "" : undefined,
				"data-state": this.#state,
				[ratingGroupAttrs.item]: "",
				//
				onclick: this.onclick,
				onpointermove: this.onpointermove,
				...this.attachment,
			}) as const
	);
}

export class RatingGroupHiddenInputState {
	static create() {
		return new RatingGroupHiddenInputState(RatingGroupRootContext.get());
	}
	readonly root: RatingGroupRootState;
	readonly shouldRender = $derived.by(() => this.root.opts.name.current !== undefined);
	readonly props = $derived.by(
		() =>
			({
				name: this.root.opts.name.current,
				value: this.root.opts.value.current,
				required: this.root.opts.required.current,
				disabled: this.root.opts.disabled.current,
			}) as const
	);

	constructor(root: RatingGroupRootState) {
		this.root = root;
	}
}

import type { OnChangeFn, WithChild, Without } from "$lib/internal/types.js";
import type { Orientation } from "$lib/index.js";
import type { BitsPrimitiveDivAttributes } from "$lib/shared/attributes.js";

export type RatingGroupItemState = "active" | "partial" | "inactive";

export type RatingGroupItemData = {
	index: number;
	state: RatingGroupItemState;
};

export type RatingGroupRootSnippetProps = {
	items: RatingGroupItemData[];
	value: number;
	max: number;
};

export type RatingGroupAriaValuetext =
	| BitsPrimitiveDivAttributes["aria-valuetext"]
	| ((value: number, max: number) => string);

export type RatingGroupRootPropsWithoutHTML = WithChild<
	{
		/**
		 * The orientation of the rating group. Used to determine
		 * how keyboard interactions work.
		 *
		 * @default "horizontal"
		 */
		orientation?: Orientation;

		/**
		 * The current rating value.
		 *
		 * @default 0
		 */
		value?: number;

		/**
		 * The callback to call when the rating value changes.
		 */
		onValueChange?: OnChangeFn<number>;

		/**
		 * The name to apply to the rating group's input element for
		 * form submission. If not provided, a hidden input will not
		 * be rendered and the rating group will not be part of a form.
		 *
		 * @default undefined
		 */
		name?: string;

		/**
		 * Whether the rating group is disabled.
		 *
		 * @default false
		 */
		disabled?: boolean;

		/**
		 * Whether the rating group is required for form submission.
		 * If `true`, ensure you provide a `name` prop so the hidden
		 * input is rendered.
		 *
		 * @default false
		 */
		required?: boolean;

		/**
		 * The minimum rating value.
		 *
		 * @default 0
		 */
		min?: number;

		/**
		 * The maximum rating value (number of items).
		 *
		 * @default 5
		 */
		max?: number;

		/**
		 * Whether to allow half-star ratings.
		 *
		 * @default false
		 */
		allowHalf?: boolean;

		/**
		 * Whether the rating group is readonly.
		 *
		 * @default false
		 */
		readonly?: boolean;

		/**
		 * Whether to show a preview when hovering over rating items.
		 * Touch events are ignored to prevent accidental previews.
		 *
		 * @default true
		 */
		hoverPreview?: boolean;

		/**
		 * An extended `aria-valuetext` property to use for the rating group.
		 * Can either be a string, or a function that receives the current value
		 * and max value and returns a string.
		 *
		 * @default ((value: number, max: number) => `${value} out of ${max}`)
		 */
		"aria-valuetext"?: RatingGroupAriaValuetext;
	},
	RatingGroupRootSnippetProps
>;

export type RatingGroupRootProps = RatingGroupRootPropsWithoutHTML &
	Without<BitsPrimitiveDivAttributes, RatingGroupRootPropsWithoutHTML>;

export type RatingGroupItemSnippetProps = {
	state: RatingGroupItemState;
};

export type RatingGroupItemPropsWithoutHTML = WithChild<
	{
		/**
		 * The index of the rating item (0-based index).
		 */
		index: number;

		/**
		 * Whether the rating item is disabled.
		 *
		 * @default false
		 */
		disabled?: boolean | null | undefined;
	},
	RatingGroupItemSnippetProps
>;

export type RatingGroupItemProps = RatingGroupItemPropsWithoutHTML &
	Without<BitsPrimitiveDivAttributes, RatingGroupItemPropsWithoutHTML>;

export { default as Root } from "./components/scroll-area.svelte";
export { default as Viewport } from "./components/scroll-area-viewport.svelte";
export { default as Scrollbar } from "./components/scroll-area-scrollbar.svelte";
export { default as Thumb } from "./components/scroll-area-thumb.svelte";
export { default as Corner } from "./components/scroll-area-corner.svelte";

export type {
	ScrollAreaRootProps as RootProps,
	ScrollAreaViewportProps as ViewportProps,
	ScrollAreaScrollbarProps as ScrollbarProps,
	ScrollAreaThumbProps as ThumbProps,
	ScrollAreaCornerProps as CornerProps,
} from "./types.js";

/**
 * This logic is adapted from Radix UI ScrollArea component.
 * https://github.com/radix-ui/primitives/blob/main/packages/react/scroll-area/src/ScrollArea.tsx
 * Credit to Jenna Smith (@jjenzz) for the original implementation.
 * Incredible thought must have went into solving all the intricacies of this component.
 */

import { Context, useDebounce, watch } from "runed";
import { untrack } from "svelte";
import {
	simpleBox,
	executeCallbacks,
	attachRef,
	DOMContext,
	getWindow,
	type ReadableBoxedValues,
} from "svelte-toolbelt";
import type { ScrollAreaType } from "./types.js";
import type { BitsPointerEvent, RefAttachment, WithRefOpts } from "$lib/internal/types.js";
import { type Direction, type Orientation, mergeProps, useId } from "$lib/shared/index.js";
import { clamp } from "$lib/internal/clamp.js";
import { on } from "svelte/events";
import { createBitsAttrs } from "$lib/internal/attrs.js";
import { StateMachine } from "$lib/internal/state-machine.js";
import { SvelteResizeObserver } from "$lib/internal/svelte-resize-observer.svelte.js";

const scrollAreaAttrs = createBitsAttrs({
	component: "scroll-area",
	parts: ["root", "viewport", "corner", "thumb", "scrollbar"],
});

export const ScrollAreaRootContext = new Context<ScrollAreaRootState>("ScrollArea.Root");
export const ScrollAreaScrollbarContext = new Context<ScrollAreaScrollbarState>(
	"ScrollArea.Scrollbar"
);
export const ScrollAreaScrollbarVisibleContext = new Context<ScrollAreaScrollbarVisibleState>(
	"ScrollArea.ScrollbarVisible"
);
export const ScrollAreaScrollbarAxisContext = new Context<ScrollbarAxis>(
	"ScrollArea.ScrollbarAxis"
);
export const ScrollAreaScrollbarSharedContext = new Context<ScrollAreaScrollbarSharedState>(
	"ScrollArea.ScrollbarShared"
);

interface Sizes {
	content: number;
	viewport: number;
	scrollbar: {
		size: number;
		paddingStart: number;
		paddingEnd: number;
	};
}

interface ScrollAreaRootStateOpts
	extends WithRefOpts,
		ReadableBoxedValues<{
			dir: Direction;
			type: ScrollAreaType;
			scrollHideDelay: number;
		}> {}

export class ScrollAreaRootState {
	static create(opts: ScrollAreaRootStateOpts) {
		return ScrollAreaRootContext.set(new ScrollAreaRootState(opts));
	}

	readonly opts: ScrollAreaRootStateOpts;
	readonly attachment: RefAttachment;
	scrollAreaNode = $state<HTMLElement | null>(null);
	viewportNode = $state<HTMLElement | null>(null);
	contentNode = $state<HTMLElement | null>(null);
	scrollbarXNode = $state<HTMLElement | null>(null);
	scrollbarYNode = $state<HTMLElement | null>(null);
	cornerWidth = $state<number>(0);
	cornerHeight = $state<number>(0);
	scrollbarXEnabled = $state(false);
	scrollbarYEnabled = $state(false);
	domContext: DOMContext;

	constructor(opts: ScrollAreaRootStateOpts) {
		this.opts = opts;
		this.attachment = attachRef(opts.ref, (v) => (this.scrollAreaNode = v));
		this.domContext = new DOMContext(opts.ref);
	}

	readonly props = $derived.by(
		() =>
			({
				id: this.opts.id.current,
				dir: this.opts.dir.current,
				style: {
					position: "relative",
					"--bits-scroll-area-corner-height": `${this.cornerHeight}px`,
					"--bits-scroll-area-corner-width": `${this.cornerWidth}px`,
				},
				[scrollAreaAttrs.root]: "",
				...this.attachment,
			}) as const
	);
}

interface ScrollAreaViewportStateOpts extends WithRefOpts {}

export class ScrollAreaViewportState {
	static create(opts: ScrollAreaViewportStateOpts) {
		return new ScrollAreaViewportState(opts, ScrollAreaRootContext.get());
	}

	readonly opts: ScrollAreaViewportStateOpts;
	readonly root: ScrollAreaRootState;
	readonly attachment: RefAttachment;
	#contentId = simpleBox(useId());
	#contentRef = simpleBox<HTMLElement | null>(null);
	readonly contentAttachment: RefAttachment = attachRef(
		this.#contentRef,
		(v) => (this.root.contentNode = v)
	);

	constructor(opts: ScrollAreaViewportStateOpts, root: ScrollAreaRootState) {
		this.opts = opts;
		this.root = root;
		this.attachment = attachRef(opts.ref, (v) => (this.root.viewportNode = v));
	}

	readonly props = $derived.by(
		() =>
			({
				id: this.opts.id.current,
				style: {
					overflowX: this.root.scrollbarXEnabled ? "scroll" : "hidden",
					overflowY: this.root.scrollbarYEnabled ? "scroll" : "hidden",
				},
				[scrollAreaAttrs.viewport]: "",
				...this.attachment,
			}) as const
	);

	readonly contentProps = $derived.by(
		() =>
			({
				id: this.#contentId.current,
				"data-scroll-area-content": "",
				/**
				 * When horizontal scrollbar is visible: this element should be at least
				 * as wide as its children for size calculations to work correctly.
				 *
				 * When horizontal scrollbar is NOT visible: this element's width should
				 * be constrained by the parent container to enable `text-overflow: ellipsis`
				 */
				style: { minWidth: this.root.scrollbarXEnabled ? "fit-content" : undefined },
				...this.contentAttachment,
			}) as const
	);
}

interface ScrollAreaScrollbarStateOpts
	extends WithRefOpts,
		ReadableBoxedValues<{
			orientation: Orientation;
		}> {}

export class ScrollAreaScrollbarState {
	static create(opts: ScrollAreaScrollbarStateOpts) {
		return ScrollAreaScrollbarContext.set(
			new ScrollAreaScrollbarState(opts, ScrollAreaRootContext.get())
		);
	}
	readonly opts: ScrollAreaScrollbarStateOpts;
	readonly root: ScrollAreaRootState;
	readonly isHorizontal = $derived.by(() => this.opts.orientation.current === "horizontal");
	hasThumb = $state(false);

	constructor(opts: ScrollAreaScrollbarStateOpts, root: ScrollAreaRootState) {
		this.opts = opts;
		this.root = root;

		watch(
			() => this.isHorizontal,
			(isHorizontal) => {
				if (isHorizontal) {
					this.root.scrollbarXEnabled = true;
					return () => {
						this.root.scrollbarXEnabled = false;
					};
				} else {
					this.root.scrollbarYEnabled = true;
					return () => {
						this.root.scrollbarYEnabled = false;
					};
				}
			}
		);
	}
}

export class ScrollAreaScrollbarHoverState {
	static create() {
		return new ScrollAreaScrollbarHoverState(ScrollAreaScrollbarContext.get());
	}
	readonly scrollbar: ScrollAreaScrollbarState;
	root: ScrollAreaRootState;
	isVisible = $state(false);

	constructor(scrollbar: ScrollAreaScrollbarState) {
		this.scrollbar = scrollbar;
		this.root = scrollbar.root;

		$effect(() => {
			const scrollAreaNode = this.root.scrollAreaNode;
			const hideDelay = this.root.opts.scrollHideDelay.current;
			let hideTimer = 0;
			if (!scrollAreaNode) return;
			const handlePointerEnter = () => {
				this.root.domContext.clearTimeout(hideTimer);
				untrack(() => (this.isVisible = true));
			};

			const handlePointerLeave = () => {
				if (hideTimer) this.root.domContext.clearTimeout(hideTimer);
				hideTimer = this.root.domContext.setTimeout(() => {
					untrack(() => {
						this.scrollbar.hasThumb = false;
						this.isVisible = false;
					});
				}, hideDelay);
			};

			const unsubListeners = executeCallbacks(
				on(scrollAreaNode, "pointerenter", handlePointerEnter),
				on(scrollAreaNode, "pointerleave", handlePointerLeave)
			);

			return () => {
				this.root.domContext.getWindow().clearTimeout(hideTimer);
				unsubListeners();
			};
		});
	}

	readonly props = $derived.by(
		() =>
			({
				"data-state": this.isVisible ? "visible" : "hidden",
			}) as const
	);
}

export class ScrollAreaScrollbarScrollState {
	static create() {
		return new ScrollAreaScrollbarScrollState(ScrollAreaScrollbarContext.get());
	}
	readonly scrollbar: ScrollAreaScrollbarState;
	readonly root: ScrollAreaRootState;
	readonly machine = new StateMachine("hidden", {
		hidden: {
			SCROLL: "scrolling",
		},
		scrolling: {
			SCROLL_END: "idle",
			POINTER_ENTER: "interacting",
		},
		interacting: {
			SCROLL: "interacting",
			POINTER_LEAVE: "idle",
		},
		idle: {
			HIDE: "hidden",
			SCROLL: "scrolling",
			POINTER_ENTER: "interacting",
		},
	});
	readonly isHidden = $derived.by(() => this.machine.state.current === "hidden");

	constructor(scrollbar: ScrollAreaScrollbarState) {
		this.scrollbar = scrollbar;
		this.root = scrollbar.root;

		const debounceScrollend = useDebounce(() => this.machine.dispatch("SCROLL_END"), 100);

		$effect(() => {
			const _state = this.machine.state.current;
			const scrollHideDelay = this.root.opts.scrollHideDelay.current;
			if (_state === "idle") {
				const hideTimer = this.root.domContext.setTimeout(
					() => this.machine.dispatch("HIDE"),
					scrollHideDelay
				);
				return () => this.root.domContext.clearTimeout(hideTimer);
			}
		});

		$effect(() => {
			const viewportNode = this.root.viewportNode;
			if (!viewportNode) return;
			const scrollDirection = this.scrollbar.isHorizontal ? "scrollLeft" : "scrollTop";

			let prevScrollPos = viewportNode[scrollDirection];
			const handleScroll = () => {
				const scrollPos = viewportNode[scrollDirection];
				const hasScrollInDirectionChanged = prevScrollPos !== scrollPos;
				if (hasScrollInDirectionChanged) {
					this.machine.dispatch("SCROLL");
					debounceScrollend();
				}
				prevScrollPos = scrollPos;
			};

			const unsubListener = on(viewportNode, "scroll", handleScroll);
			return unsubListener;
		});

		this.onpointerenter = this.onpointerenter.bind(this);
		this.onpointerleave = this.onpointerleave.bind(this);
	}

	onpointerenter(_: BitsPointerEvent) {
		this.machine.dispatch("POINTER_ENTER");
	}

	onpointerleave(_: BitsPointerEvent) {
		this.machine.dispatch("POINTER_LEAVE");
	}

	readonly props = $derived.by(
		() =>
			({
				"data-state": this.machine.state.current === "hidden" ? "hidden" : "visible",
				onpointerenter: this.onpointerenter,
				onpointerleave: this.onpointerleave,
			}) as const
	);
}

export class ScrollAreaScrollbarAutoState {
	static create() {
		return new ScrollAreaScrollbarAutoState(ScrollAreaScrollbarContext.get());
	}
	readonly scrollbar: ScrollAreaScrollbarState;
	readonly root: ScrollAreaRootState;
	isVisible = $state(false);

	constructor(scrollbar: ScrollAreaScrollbarState) {
		this.scrollbar = scrollbar;
		this.root = scrollbar.root;

		const handleResize = () => {
			const viewportNode = this.root.viewportNode;
			if (!viewportNode) return;
			const isOverflowX = viewportNode.offsetWidth < viewportNode.scrollWidth;
			const isOverflowY = viewportNode.offsetHeight < viewportNode.scrollHeight;
			this.isVisible = this.scrollbar.isHorizontal ? isOverflowX : isOverflowY;
		};

		new SvelteResizeObserver(() => this.root.viewportNode, handleResize);
		new SvelteResizeObserver(() => this.root.contentNode, handleResize);
	}

	readonly props = $derived.by(
		() =>
			({
				"data-state": this.isVisible ? "visible" : "hidden",
			}) as const
	);
}

export class ScrollAreaScrollbarVisibleState {
	static create() {
		return ScrollAreaScrollbarVisibleContext.set(
			new ScrollAreaScrollbarVisibleState(ScrollAreaScrollbarContext.get())
		);
	}
	readonly scrollbar: ScrollAreaScrollbarState;
	readonly root: ScrollAreaRootState;
	thumbNode = $state<HTMLElement | null>(null);
	pointerOffset = $state(0);
	sizes = $state.raw<Sizes>({
		content: 0,
		viewport: 0,
		scrollbar: { size: 0, paddingStart: 0, paddingEnd: 0 },
	});
	readonly thumbRatio = $derived.by(() => getThumbRatio(this.sizes.viewport, this.sizes.content));
	readonly hasThumb = $derived.by(() => Boolean(this.thumbRatio > 0 && this.thumbRatio < 1));
	// this needs to be a $state to properly restore the transform style when the scrollbar
	// goes from a hidden to visible state, otherwise it will start at the beginning of the
	// scrollbar and flicker to the correct position after
	prevTransformStyle = $state("");

	constructor(scrollbar: ScrollAreaScrollbarState) {
		this.scrollbar = scrollbar;
		this.root = scrollbar.root;

		$effect(() => {
			this.scrollbar.hasThumb = this.hasThumb;
		});

		$effect(() => {
			if (!this.scrollbar.hasThumb && this.thumbNode) {
				this.prevTransformStyle = this.thumbNode.style.transform;
			}
		});
	}

	setSizes(sizes: Sizes) {
		this.sizes = sizes;
	}

	getScrollPosition(pointerPos: number, dir?: Direction) {
		return getScrollPositionFromPointer({
			pointerPos,
			pointerOffset: this.pointerOffset,
			sizes: this.sizes,
			dir,
		});
	}

	onThumbPointerUp() {
		this.pointerOffset = 0;
	}

	onThumbPointerDown(pointerPos: number) {
		this.pointerOffset = pointerPos;
	}

	xOnThumbPositionChange() {
		if (!(this.root.viewportNode && this.thumbNode)) return;
		const scrollPos = this.root.viewportNode.scrollLeft;
		const offset = getThumbOffsetFromScroll({
			scrollPos,
			sizes: this.sizes,
			dir: this.root.opts.dir.current,
		});
		const transformStyle = `translate3d(${offset}px, 0, 0)`;
		this.thumbNode.style.transform = transformStyle;
		this.prevTransformStyle = transformStyle;
	}

	xOnWheelScroll(scrollPos: number) {
		if (!this.root.viewportNode) return;
		this.root.viewportNode.scrollLeft = scrollPos;
	}

	xOnDragScroll(pointerPos: number) {
		if (!this.root.viewportNode) return;
		this.root.viewportNode.scrollLeft = this.getScrollPosition(
			pointerPos,
			this.root.opts.dir.current
		);
	}

	yOnThumbPositionChange() {
		if (!(this.root.viewportNode && this.thumbNode)) return;
		const scrollPos = this.root.viewportNode.scrollTop;
		const offset = getThumbOffsetFromScroll({ scrollPos, sizes: this.sizes });
		const transformStyle = `translate3d(0, ${offset}px, 0)`;
		this.thumbNode.style.transform = transformStyle;
		this.prevTransformStyle = transformStyle;
	}

	yOnWheelScroll(scrollPos: number) {
		if (!this.root.viewportNode) return;
		this.root.viewportNode.scrollTop = scrollPos;
	}

	yOnDragScroll(pointerPos: number) {
		if (!this.root.viewportNode) return;
		this.root.viewportNode.scrollTop = this.getScrollPosition(
			pointerPos,
			this.root.opts.dir.current
		);
	}
}

interface ScrollbarAxisStateOpts extends ReadableBoxedValues<{ mounted: boolean }> {}

interface ScrollbarAxisState {
	onThumbPointerDown: (pointerPos: { x: number; y: number }) => void;
	onDragScroll: (pointerPos: { x: number; y: number }) => void;
	onWheelScroll: (e: WheelEvent, maxScrollPos: number) => void;
	onResize: () => void;
	onThumbPositionChange: () => void;
	onThumbPointerUp: () => void;
	props: {
		id: string;
		"data-orientation": "horizontal" | "vertical";
		style: Record<string, string | number | undefined>;
	};
}

export class ScrollAreaScrollbarXState implements ScrollbarAxisState {
	static create(opts: ScrollbarAxisStateOpts) {
		return ScrollAreaScrollbarAxisContext.set(
			new ScrollAreaScrollbarXState(opts, ScrollAreaScrollbarVisibleContext.get())
		);
	}
	readonly opts: ScrollbarAxisStateOpts;
	readonly scrollbarVis: ScrollAreaScrollbarVisibleState;
	readonly root: ScrollAreaRootState;
	readonly scrollbar: ScrollAreaScrollbarState;
	readonly attachment: RefAttachment;
	computedStyle = $state<CSSStyleDeclaration>();

	constructor(opts: ScrollbarAxisStateOpts, scrollbarVis: ScrollAreaScrollbarVisibleState) {
		this.opts = opts;
		this.scrollbarVis = scrollbarVis;
		this.root = scrollbarVis.root;
		this.scrollbar = scrollbarVis.scrollbar;
		this.attachment = attachRef(this.scrollbar.opts.ref, (v) => (this.root.scrollbarXNode = v));

		$effect(() => {
			if (!this.scrollbar.opts.ref.current) return;
			if (this.opts.mounted.current) {
				this.computedStyle = getComputedStyle(this.scrollbar.opts.ref.current!);
			}
		});

		$effect(() => {
			// Ensure when a user scrolls down and then the scrollbar is hidden
			// that when it shows again it will be positioned correctly.
			this.onResize();
		});
	}

	onThumbPointerDown = (pointerPos: { x: number; y: number }) => {
		this.scrollbarVis.onThumbPointerDown(pointerPos.x);
	};

	onDragScroll = (pointerPos: { x: number; y: number }) => {
		this.scrollbarVis.xOnDragScroll(pointerPos.x);
	};

	onThumbPointerUp = () => {
		this.scrollbarVis.onThumbPointerUp();
	};

	onThumbPositionChange = () => {
		this.scrollbarVis.xOnThumbPositionChange();
	};

	onWheelScroll = (e: WheelEvent, maxScrollPos: number) => {
		if (!this.root.viewportNode) return;
		const scrollPos = this.root.viewportNode.scrollLeft + e.deltaX;
		this.scrollbarVis.xOnWheelScroll(scrollPos);
		// prevent window scroll when wheeling scrollbar
		if (isScrollingWithinScrollbarBounds(scrollPos, maxScrollPos)) {
			e.preventDefault();
		}
	};

	onResize = () => {
		if (!(this.scrollbar.opts.ref.current && this.root.viewportNode && this.computedStyle))
			return;
		this.scrollbarVis.setSizes({
			content: this.root.viewportNode.scrollWidth,
			viewport: this.root.viewportNode.offsetWidth,
			scrollbar: {
				size: this.scrollbar.opts.ref.current.clientWidth,
				paddingStart: toInt(this.computedStyle.paddingLeft),
				paddingEnd: toInt(this.computedStyle.paddingRight),
			},
		});
	};

	readonly thumbSize = $derived.by(() => {
		return getThumbSize(this.scrollbarVis.sizes);
	});

	readonly props = $derived.by(
		() =>
			({
				id: this.scrollbar.opts.id.current,
				"data-orientation": "horizontal",
				style: {
					bottom: 0,
					left:
						this.root.opts.dir.current === "rtl"
							? "var(--bits-scroll-area-corner-width)"
							: 0,
					right:
						this.root.opts.dir.current === "ltr"
							? "var(--bits-scroll-area-corner-width)"
							: 0,
					"--bits-scroll-area-thumb-width": `${this.thumbSize}px`,
				},
				...this.attachment,
			}) as const
	);
}

export class ScrollAreaScrollbarYState implements ScrollbarAxisState {
	static create(opts: ScrollbarAxisStateOpts) {
		return ScrollAreaScrollbarAxisContext.set(
			new ScrollAreaScrollbarYState(opts, ScrollAreaScrollbarVisibleContext.get())
		);
	}
	readonly opts: ScrollbarAxisStateOpts;
	readonly scrollbarVis: ScrollAreaScrollbarVisibleState;
	readonly root: ScrollAreaRootState;
	readonly scrollbar: ScrollAreaScrollbarState;
	readonly attachment: RefAttachment;
	computedStyle = $state<CSSStyleDeclaration>();

	constructor(opts: ScrollbarAxisStateOpts, scrollbarVis: ScrollAreaScrollbarVisibleState) {
		this.opts = opts;
		this.scrollbarVis = scrollbarVis;
		this.root = scrollbarVis.root;
		this.scrollbar = scrollbarVis.scrollbar;
		this.attachment = attachRef(this.scrollbar.opts.ref, (v) => (this.root.scrollbarYNode = v));

		$effect(() => {
			if (!this.scrollbar.opts.ref.current) return;
			if (this.opts.mounted.current) {
				this.computedStyle = getComputedStyle(this.scrollbar.opts.ref.current!);
			}
		});

		$effect(() => {
			// Ensure when a user scrolls down and then the scrollbar is hidden
			// that when it shows again it will be positioned correctly.
			this.onResize();
		});

		this.onThumbPointerDown = this.onThumbPointerDown.bind(this);
		this.onDragScroll = this.onDragScroll.bind(this);
		this.onThumbPointerUp = this.onThumbPointerUp.bind(this);
		this.onThumbPositionChange = this.onThumbPositionChange.bind(this);
		this.onWheelScroll = this.onWheelScroll.bind(this);
		this.onResize = this.onResize.bind(this);
	}

	onThumbPointerDown(pointerPos: { x: number; y: number }) {
		this.scrollbarVis.onThumbPointerDown(pointerPos.y);
	}

	onDragScroll(pointerPos: { x: number; y: number }) {
		this.scrollbarVis.yOnDragScroll(pointerPos.y);
	}

	onThumbPointerUp() {
		this.scrollbarVis.onThumbPointerUp();
	}

	onThumbPositionChange() {
		this.scrollbarVis.yOnThumbPositionChange();
	}

	onWheelScroll(e: WheelEvent, maxScrollPos: number) {
		if (!this.root.viewportNode) return;
		const scrollPos = this.root.viewportNode.scrollTop + e.deltaY;
		this.scrollbarVis.yOnWheelScroll(scrollPos);
		// prevent window scroll when wheeling scrollbar
		if (isScrollingWithinScrollbarBounds(scrollPos, maxScrollPos)) {
			e.preventDefault();
		}
	}

	onResize() {
		if (!(this.scrollbar.opts.ref.current && this.root.viewportNode && this.computedStyle))
			return;
		this.scrollbarVis.setSizes({
			content: this.root.viewportNode.scrollHeight,
			viewport: this.root.viewportNode.offsetHeight,
			scrollbar: {
				size: this.scrollbar.opts.ref.current.clientHeight,
				paddingStart: toInt(this.computedStyle.paddingTop),
				paddingEnd: toInt(this.computedStyle.paddingBottom),
			},
		});
	}

	readonly thumbSize = $derived.by(() => {
		return getThumbSize(this.scrollbarVis.sizes);
	});

	readonly props = $derived.by(
		() =>
			({
				id: this.scrollbar.opts.id.current,
				"data-orientation": "vertical",
				style: {
					top: 0,
					right: this.root.opts.dir.current === "ltr" ? 0 : undefined,
					left: this.root.opts.dir.current === "rtl" ? 0 : undefined,
					bottom: "var(--bits-scroll-area-corner-height)",
					"--bits-scroll-area-thumb-height": `${this.thumbSize}px`,
				},
				...this.attachment,
			}) as const
	);
}

type ScrollbarAxis = ScrollAreaScrollbarXState | ScrollAreaScrollbarYState;

export class ScrollAreaScrollbarSharedState {
	static create() {
		return ScrollAreaScrollbarSharedContext.set(
			new ScrollAreaScrollbarSharedState(ScrollAreaScrollbarAxisContext.get())
		);
	}
	readonly scrollbarState: ScrollbarAxis;
	readonly root: ScrollAreaRootState;
	readonly scrollbarVis: ScrollAreaScrollbarVisibleState;
	readonly scrollbar: ScrollAreaScrollbarState;
	rect = $state.raw<DOMRect | null>(null);
	prevWebkitUserSelect = $state<string>("");
	handleResize: () => void;
	handleThumbPositionChange: () => void;
	handleWheelScroll: (e: WheelEvent, maxScrollPos: number) => void;
	handleThumbPointerDown: (pointerPos: { x: number; y: number }) => void;
	handleThumbPointerUp: () => void;
	readonly maxScrollPos = $derived.by(
		() => this.scrollbarVis.sizes.content - this.scrollbarVis.sizes.viewport
	);

	constructor(scrollbarState: ScrollbarAxis) {
		this.scrollbarState = scrollbarState;
		this.root = scrollbarState.root;
		this.scrollbarVis = scrollbarState.scrollbarVis;
		this.scrollbar = scrollbarState.scrollbarVis.scrollbar;
		this.handleResize = () => this.scrollbarState.onResize();
		this.handleThumbPositionChange = this.scrollbarState.onThumbPositionChange;
		this.handleWheelScroll = this.scrollbarState.onWheelScroll;
		this.handleThumbPointerDown = this.scrollbarState.onThumbPointerDown;
		this.handleThumbPointerUp = this.scrollbarState.onThumbPointerUp;

		$effect(() => {
			const maxScrollPos = this.maxScrollPos;
			const scrollbarNode = this.scrollbar.opts.ref.current;
			// we want to react to the viewport node changing so we leave this here
			this.root.viewportNode;
			const handleWheel = (e: WheelEvent) => {
				const node = e.target as HTMLElement;
				const isScrollbarWheel = scrollbarNode?.contains(node);
				if (isScrollbarWheel) this.handleWheelScroll(e, maxScrollPos);
			};

			const unsubListener = on(this.root.domContext.getDocument(), "wheel", handleWheel, {
				passive: false,
			});

			return unsubListener;
		});

		$effect.pre(() => {
			// react to changes to this:
			this.scrollbarVis.sizes;
			untrack(() => this.handleThumbPositionChange());
		});

		// $effect.pre(() => {
		// 	this.handleThumbPositionChange();
		// });

		new SvelteResizeObserver(() => this.scrollbar.opts.ref.current, this.handleResize);
		new SvelteResizeObserver(() => this.root.contentNode, this.handleResize);

		this.onpointerdown = this.onpointerdown.bind(this);
		this.onpointermove = this.onpointermove.bind(this);
		this.onpointerup = this.onpointerup.bind(this);
		this.onlostpointercapture = this.onlostpointercapture.bind(this);
	}

	handleDragScroll(e: PointerEvent) {
		if (!this.rect) return;
		const x = e.clientX - this.rect.left;
		const y = e.clientY - this.rect.top;
		this.scrollbarState.onDragScroll({ x, y });
	}

	#cleanupPointerState(): void {
		if (this.rect === null) return;
		this.root.domContext.getDocument().body.style.webkitUserSelect = this.prevWebkitUserSelect;
		if (this.root.viewportNode) this.root.viewportNode.style.scrollBehavior = "";
		this.rect = null;
	}

	onpointerdown(e: BitsPointerEvent) {
		if (e.button !== 0) return;
		const target = e.target as HTMLElement;
		target.setPointerCapture(e.pointerId);
		this.rect = this.scrollbar.opts.ref.current?.getBoundingClientRect() ?? null;
		// pointer capture doesn't prevent text selection in Safari
		// so we remove text selection manually when scrolling
		this.prevWebkitUserSelect = this.root.domContext.getDocument().body.style.webkitUserSelect;
		this.root.domContext.getDocument().body.style.webkitUserSelect = "none";
		if (this.root.viewportNode) this.root.viewportNode.style.scrollBehavior = "auto";
		this.handleDragScroll(e);
	}

	onpointermove(e: BitsPointerEvent) {
		this.handleDragScroll(e);
	}

	onpointerup(e: BitsPointerEvent) {
		const target = e.target as HTMLElement;
		if (target.hasPointerCapture(e.pointerId)) {
			target.releasePointerCapture(e.pointerId);
		}
		this.#cleanupPointerState();
	}

	onlostpointercapture(_: BitsPointerEvent) {
		this.#cleanupPointerState();
	}

	readonly props = $derived.by(() =>
		mergeProps({
			...this.scrollbarState.props,
			style: {
				position: "absolute",
				...this.scrollbarState.props.style,
			},
			[scrollAreaAttrs.scrollbar]: "",
			onpointerdown: this.onpointerdown,
			onpointermove: this.onpointermove,
			onpointerup: this.onpointerup,
			onlostpointercapture: this.onlostpointercapture,
		})
	);
}

interface ScrollAreaThumbImplStateOpts
	extends WithRefOpts,
		ReadableBoxedValues<{
			mounted: boolean;
		}> {}

export class ScrollAreaThumbImplState {
	static create(opts: ScrollAreaThumbImplStateOpts) {
		return new ScrollAreaThumbImplState(opts, ScrollAreaScrollbarSharedContext.get());
	}
	readonly opts: ScrollAreaThumbImplStateOpts;
	readonly scrollbarState: ScrollAreaScrollbarSharedState;
	readonly attachment: RefAttachment;
	readonly #root: ScrollAreaRootState;
	#removeUnlinkedScrollListener = $state<() => void>();
	readonly #debounceScrollEnd = useDebounce(() => {
		if (this.#removeUnlinkedScrollListener) {
			this.#removeUnlinkedScrollListener();
			this.#removeUnlinkedScrollListener = undefined;
		}
	}, 100);

	constructor(
		opts: ScrollAreaThumbImplStateOpts,
		scrollbarState: ScrollAreaScrollbarSharedState
	) {
		this.opts = opts;
		this.scrollbarState = scrollbarState;
		this.#root = scrollbarState.root;
		this.attachment = attachRef(
			this.opts.ref,
			(v) => (this.scrollbarState.scrollbarVis.thumbNode = v)
		);

		$effect(() => {
			const viewportNode = this.#root.viewportNode;
			if (!viewportNode) return;
			const handleScroll = () => {
				this.#debounceScrollEnd();
				if (!this.#removeUnlinkedScrollListener) {
					const listener = addUnlinkedScrollListener(
						viewportNode,
						this.scrollbarState.handleThumbPositionChange
					);
					this.#removeUnlinkedScrollListener = listener;
					this.scrollbarState.handleThumbPositionChange();
				}
			};
			untrack(() => this.scrollbarState.handleThumbPositionChange());
			const unsubListener = on(viewportNode, "scroll", handleScroll);
			return unsubListener;
		});

		this.onpointerdowncapture = this.onpointerdowncapture.bind(this);
		this.onpointerup = this.onpointerup.bind(this);
	}

	onpointerdowncapture(e: BitsPointerEvent) {
		const thumb = e.target as HTMLElement;
		if (!thumb) return;
		const thumbRect = thumb.getBoundingClientRect();
		const x = e.clientX - thumbRect.left;
		const y = e.clientY - thumbRect.top;
		this.scrollbarState.handleThumbPointerDown({ x, y });
	}

	onpointerup(_: BitsPointerEvent) {
		this.scrollbarState.handleThumbPointerUp();
	}

	readonly props = $derived.by(
		() =>
			({
				id: this.opts.id.current,
				"data-state": this.scrollbarState.scrollbarVis.hasThumb ? "visible" : "hidden",
				style: {
					width: "var(--bits-scroll-area-thumb-width)",
					height: "var(--bits-scroll-area-thumb-height)",
					transform: this.scrollbarState.scrollbarVis.prevTransformStyle,
				},
				onpointerdowncapture: this.onpointerdowncapture,
				onpointerup: this.onpointerup,
				[scrollAreaAttrs.thumb]: "",
				...this.attachment,
			}) as const
	);
}

interface ScrollAreaCornerImplStateOpts extends WithRefOpts {}

export class ScrollAreaCornerImplState {
	static create(opts: ScrollAreaCornerImplStateOpts) {
		return new ScrollAreaCornerImplState(opts, ScrollAreaRootContext.get());
	}

	readonly opts: ScrollAreaCornerImplStateOpts;
	readonly root: ScrollAreaRootState;
	readonly attachment: RefAttachment;
	#width = $state(0);
	#height = $state(0);
	readonly hasSize = $derived(Boolean(this.#width && this.#height));

	constructor(opts: ScrollAreaCornerImplStateOpts, root: ScrollAreaRootState) {
		this.opts = opts;
		this.root = root;
		this.attachment = attachRef(this.opts.ref);

		new SvelteResizeObserver(
			() => this.root.scrollbarXNode,
			() => {
				const height = this.root.scrollbarXNode?.offsetHeight || 0;
				this.root.cornerHeight = height;
				this.#height = height;
			}
		);

		new SvelteResizeObserver(
			() => this.root.scrollbarYNode,
			() => {
				const width = this.root.scrollbarYNode?.offsetWidth || 0;
				this.root.cornerWidth = width;
				this.#width = width;
			}
		);
	}

	readonly props = $derived.by(() => ({
		id: this.opts.id.current,
		style: {
			width: this.#width,
			height: this.#height,
			position: "absolute",
			right: this.root.opts.dir.current === "ltr" ? 0 : undefined,
			left: this.root.opts.dir.current === "rtl" ? 0 : undefined,
			bottom: 0,
		},
		[scrollAreaAttrs.corner]: "",
		...this.attachment,
	}));
}

function toInt(value?: string) {
	return value ? Number.parseInt(value, 10) : 0;
}

function getThumbRatio(viewportSize: number, contentSize: number) {
	const ratio = viewportSize / contentSize;
	return Number.isNaN(ratio) ? 0 : ratio;
}

function getThumbSize(sizes: Sizes) {
	const ratio = getThumbRatio(sizes.viewport, sizes.content);
	const scrollbarPadding = sizes.scrollbar.paddingStart + sizes.scrollbar.paddingEnd;
	const thumbSize = (sizes.scrollbar.size - scrollbarPadding) * ratio;
	return Math.max(thumbSize, 18);
}

type GetScrollPositionFromPointerProps = {
	pointerPos: number;
	pointerOffset: number;
	sizes: Sizes;
	dir?: Direction;
};

function getScrollPositionFromPointer({
	pointerPos,
	pointerOffset,
	sizes,
	dir = "ltr",
}: GetScrollPositionFromPointerProps) {
	const thumbSizePx = getThumbSize(sizes);
	const thumbCenter = thumbSizePx / 2;
	const offset = pointerOffset || thumbCenter;
	const thumbOffsetFromEnd = thumbSizePx - offset;
	const minPointerPos = sizes.scrollbar.paddingStart + offset;
	const maxPointerPos = sizes.scrollbar.size - sizes.scrollbar.paddingEnd - thumbOffsetFromEnd;
	const maxScrollPos = sizes.content - sizes.viewport;
	const scrollRange = dir === "ltr" ? [0, maxScrollPos] : [maxScrollPos * -1, 0];
	const interpolate = linearScale(
		[minPointerPos, maxPointerPos],
		scrollRange as [number, number]
	);
	return interpolate(pointerPos);
}

type GetThumbOffsetFromScrollProps = {
	scrollPos: number;
	sizes: Sizes;
	dir?: Direction;
};

function getThumbOffsetFromScroll({
	scrollPos,
	sizes,
	dir = "ltr",
}: GetThumbOffsetFromScrollProps) {
	const thumbSizePx = getThumbSize(sizes);
	const scrollbarPadding = sizes.scrollbar.paddingStart + sizes.scrollbar.paddingEnd;
	const scrollbar = sizes.scrollbar.size - scrollbarPadding;
	const maxScrollPos = sizes.content - sizes.viewport;
	const maxThumbPos = scrollbar - thumbSizePx;
	const scrollClampRange = dir === "ltr" ? [0, maxScrollPos] : [maxScrollPos * -1, 0];
	const scrollWithoutMomentum = clamp(scrollPos, scrollClampRange[0]!, scrollClampRange[1]!);
	const interpolate = linearScale([0, maxScrollPos], [0, maxThumbPos]);
	return interpolate(scrollWithoutMomentum);
}

// https://github.com/tmcw-up-for-adoption/simple-linear-scale/blob/master/index.js
function linearScale(input: readonly [number, number], output: readonly [number, number]) {
	return (value: number) => {
		if (input[0] === input[1] || output[0] === output[1]) return output[0];
		const ratio = (output[1] - output[0]) / (input[1] - input[0]);
		return output[0] + ratio * (value - input[0]);
	};
}

function isScrollingWithinScrollbarBounds(scrollPos: number, maxScrollPos: number) {
	return scrollPos > 0 && scrollPos < maxScrollPos;
}

function addUnlinkedScrollListener(node: HTMLElement, handler: () => void) {
	let prevPosition = { left: node.scrollLeft, top: node.scrollTop };
	let rAF = 0;
	const win = getWindow(node);

	(function loop() {
		const position = { left: node.scrollLeft, top: node.scrollTop };
		const isHorizontalScroll = prevPosition.left !== position.left;
		const isVerticalScroll = prevPosition.top !== position.top;
		if (isHorizontalScroll || isVerticalScroll) handler();
		prevPosition = position;
		rAF = win.requestAnimationFrame(loop);
	})();

	return () => win.cancelAnimationFrame(rAF);
}

