interface TimeRangeFieldRootStateOpts<T extends TimeValue = Time>
	extends WithRefOpts,
		WritableBoxedValues<{
			value: TimeRange<T>;
			placeholder: TimeValue;
			startValue: T | undefined;
			endValue: T | undefined;
		}>,
