export type BitsConfigProps = WithChildren<BitsConfigPropsWithoutChildren>;

import type { Snippet } from "svelte";
import type { WritableBox } from "svelte-toolbelt";

export type InteractOutsideEvent = PointerEvent;
export type InteractOutsideEventHandler = (e: PointerEvent) => void;

export type InteractOutsideBehaviorType =
	| "close"
	| "defer-otherwise-close"
	| "defer-otherwise-ignore"
	| "ignore";

export type DismissibleLayerProps = {
	/**
	 * Callback fired when an outside interaction event completes,
	 * which is either a `pointerup`, `mouseup`, or `touchend`
	 * event, depending on the user's input device.
	 */
	onInteractOutside?: InteractOutsideEventHandler;

	/**
	 * Interact outside behavior type.
	 * `close`: Closes the element immediately.
	 * `defer-otherwise-close`: Delegates the action to the parent element. If no parent is found, it closes the element.
	 * `defer-otherwise-ignore`: Delegates the action to the parent element. If no parent is found, nothing is done.
	 * `ignore`: Prevents the element from closing and also blocks the parent element from closing in response to an outside interaction.
	 *
	 * @defaultValue `close`
	 */
	interactOutsideBehavior?: InteractOutsideBehaviorType;

	/**
	 * Callback fired when focus leaves the dismissible layer.
	 */
	onFocusOutside?: (event: FocusEvent) => void;
};

export type DismissibleLayerImplProps = {
	/**
	 * Whether the layer is enabled.
	 */
	enabled: boolean;

	/**
	 * ID of the layer.
	 */
	id: string;

	/**
	 * Provide a custom event validator function to determine if the event should be
	 * considered a dismissal event. This was added to handle the case where a user
	 * has one context menu open and right clicks on another context menu. We normally ignore
	 * right clicks for "close" events, but in this case we want to close the context menu when
	 * another is open.
	 */
	isValidEvent?: (e: PointerEvent, node: HTMLElement) => boolean;

	children?: Snippet<[{ props: Record<string, unknown> }]>;

	ref: WritableBox<HTMLElement | null>;
} & DismissibleLayerProps;

import {
	type ReadableBox,
	type WritableBox,
	afterTick,
	executeCallbacks,
	onDestroyEffect,
	type ReadableBoxedValues,
} from "svelte-toolbelt";
import { watch } from "runed";
import { untrack } from "svelte";
import { on } from "svelte/events";
import type { DismissibleLayerImplProps, InteractOutsideBehaviorType } from "./types.js";
import { type EventCallback } from "$lib/internal/events.js";
import { debounce } from "$lib/internal/debounce.js";
import { noop } from "$lib/internal/noop.js";
import { getOwnerDocument, isOrContainsTarget } from "$lib/internal/elements.js";
import { isElementOrSVGElement } from "$lib/internal/is.js";
import { isClickTrulyOutside } from "$lib/internal/dom.js";
import {
	CONTEXT_MENU_CONTENT_ATTR,
	CONTEXT_MENU_TRIGGER_ATTR,
} from "$lib/bits/menu/context-menu-attributes.js";

globalThis.bitsDismissableLayers ??= new Map<
	DismissibleLayerState,
	ReadableBox<InteractOutsideBehaviorType>
>();

interface DismissibleLayerStateOpts
	extends ReadableBoxedValues<Required<Omit<DismissibleLayerImplProps, "children" | "ref">>> {
	ref: WritableBox<HTMLElement | null>;
}

export class DismissibleLayerState {
	static create(opts: DismissibleLayerStateOpts) {
		return new DismissibleLayerState(opts);
	}
	readonly opts: DismissibleLayerStateOpts;
	#interactOutsideProp: ReadableBox<EventCallback<PointerEvent>>;
	#behaviorType: ReadableBox<InteractOutsideBehaviorType>;
	#interceptedEvents: Record<string, boolean> = {
		pointerdown: false,
	};
	#isResponsibleLayer = false;
	#capturedPointerDown: PointerEvent | null = null;
	#isFocusInsideDOMTree = false;
	#documentObj = undefined as unknown as Document;
	#onFocusOutside: DismissibleLayerStateOpts["onFocusOutside"];
	#unsubClickListener = noop;
	/**
	 * Set once the layer is torn down. Deferred work scheduled before teardown can
	 * still run afterwards, so every such callback must short-circuit on this
	 * before reading `this.opts.ref.current` — reading a destroyed `$derived`
	 * triggers Svelte's `derived_inert` warning. A class field rather than a
	 * constructor local so the class-field handlers below can see it too.
	 */
	#destroyed = false;

	constructor(opts: DismissibleLayerStateOpts) {
		this.opts = opts;

		this.#behaviorType = opts.interactOutsideBehavior;
		this.#interactOutsideProp = opts.onInteractOutside;
		this.#onFocusOutside = opts.onFocusOutside;

		let unsubEvents = noop;
		let registeredNode: HTMLElement | null = null;

		const cleanup = () => {
			registeredNode = null;
			this.#resetState();
			globalThis.bitsDismissableLayers.delete(this);
			this.#handleInteractOutside.destroy();
			this.#unsubClickListener();
			unsubEvents();
		};

		watch([() => this.opts.enabled.current, () => this.opts.ref.current], ([enabled, node]) => {
			const nextNode = enabled ? node : null;
			// Ref boxes can invalidate without changing the DOM node during opening.
			// Keep an in-flight interaction when this is still the same registration.
			if (registeredNode === nextNode) return;
			cleanup();
			if (!nextNode) return;
			registeredNode = nextNode;
			this.#documentObj = getOwnerDocument(nextNode);
			globalThis.bitsDismissableLayers.set(this, this.#behaviorType);
			unsubEvents = this.#addEventListeners();
		});

		onDestroyEffect(() => {
			this.#destroyed = true;
			cleanup();
		});
	}

	#handleFocus = (event: FocusEvent) => {
		if (event.defaultPrevented) return;
		if (this.#destroyed || !this.opts.ref.current) return;
		afterTick(() => {
			// The layer can be destroyed between the focus event and this tick — a
			// focus change is frequently what closes it. `#destroyed` must
			// short-circuit before any `this.opts.ref.current` read.
			if (this.#destroyed) return;
			if (!this.opts.ref.current || this.#isTargetWithinLayer(event.target as HTMLElement))
				return;

			if (event.target && !this.#isFocusInsideDOMTree) {
				this.#onFocusOutside.current?.(event);
			}
		});
	};

	#addEventListeners() {
		const document = this.#documentObj;
		const onPointerDownCapture = (event: PointerEvent) => {
			untrack(() => {
				this.#markInterceptedEvent(event);
				this.#markResponsibleLayer(event);
			});
		};
		const onPointerDown = (event: PointerEvent) => {
			// Ignore stopped events and bubble-only events such as the opening pointerdown.
			// It can resume bubbling after a nested early outside click has been captured.
			if (event.cancelBubble || event !== this.#capturedPointerDown) return;
			this.#markNonInterceptedEvent(event);
			if (event.pointerType === "touch") {
				// a tap's click can follow its pointerdown within a millisecond (WebKit), so
				// arm the click listener now rather than after the debounce flushes
				this.#handleInteractOutside.destroy();
				this.#interactOutside(event);
			} else {
				this.#handleInteractOutside(event);
			}
		};

		// `svelte/events.on` defers pointer listener attachment to a microtask, leaving
		// a gap even without a registration timer. Document is already connected, so
		// attach immediately. Only layers present at capture can own this interaction;
		// a layer opened by its target/bubble handlers must not dismiss itself.
		document.addEventListener("pointerdown", onPointerDownCapture, true);
		document.addEventListener("pointerdown", onPointerDown);

		return executeCallbacks(
			() => document.removeEventListener("pointerdown", onPointerDownCapture, true),
			() => document.removeEventListener("pointerdown", onPointerDown),
			on(document, "focusin", this.#handleFocus)
		);
	}

	#handleDismiss = (e: MouseEvent) => {
		let event = e;
		if (event.defaultPrevented) {
			event = createWrappedEvent(e);
		}
		this.#interactOutsideProp.current(e as PointerEvent);
	};

	#interactOutside = (e: PointerEvent) => {
		if (!this.opts.ref.current) {
			this.#unsubClickListener();
			return;
		}
		const isEventValid =
			this.opts.isValidEvent.current(e, this.opts.ref.current) ||
			isValidEvent(e, this.opts.ref.current);

		if (!this.#isResponsibleLayer || this.#isAnyEventIntercepted() || !isEventValid) {
			this.#unsubClickListener();
			return;
		}

		let event = e;
		if (event.defaultPrevented) {
			event = createWrappedEvent(event);
		}

		if (
			this.#behaviorType.current !== "close" &&
			this.#behaviorType.current !== "defer-otherwise-close"
		) {
			this.#unsubClickListener();
			return;
		}

		if (e.pointerType === "touch") {
			this.#unsubClickListener();

			// the tap's click dismisses from the bubble phase, as before. A capture-phase
			// listener backs it up with a task, so a target that stops propagation cannot
			// hide the click, while a target that closes this layer still tears it down
			// (and the backup with it) before the task runs.
			let backup: ReturnType<typeof setTimeout> | null = null;
			let unsubClick = noop;
			const dismiss = (event: MouseEvent) => {
				unsubClick();
				this.#handleDismiss(event);
			};
			unsubClick = executeCallbacks(
				on(this.#documentObj, "click", dismiss, { once: true }),
				on(
					this.#documentObj,
					"click",
					(event: MouseEvent) => {
						backup = setTimeout(() => dismiss(event), 0);
					},
					{ once: true, capture: true }
				),
				() => {
					if (backup !== null) clearTimeout(backup);
					backup = null;
				}
			);
			this.#unsubClickListener = unsubClick;
		} else {
			this.#interactOutsideProp.current(event);
		}
	};

	#handleInteractOutside = debounce(this.#interactOutside, 10);

	#markInterceptedEvent = (e: PointerEvent) => {
		this.#interceptedEvents[e.type] = true;
	};

	#markNonInterceptedEvent = (e: PointerEvent) => {
		this.#interceptedEvents[e.type] = false;
	};

	#markResponsibleLayer = (event: PointerEvent) => {
		this.#capturedPointerDown = event;
		if (!this.opts.ref.current) return;
		this.#isResponsibleLayer = isResponsibleLayer(this.opts.ref.current);
	};

	#isTargetWithinLayer = (target: HTMLElement) => {
		if (!this.opts.ref.current) return false;
		return isOrContainsTarget(this.opts.ref.current, target);
	};

	/**
	 * Resets the per-interaction state. Must stay synchronous.
	 *
	 * This was a `debounce(..., 20)` from when it was also wired to a capture-phase
	 * interaction-end listener and had to land after the 10ms `#handleInteractOutside`
	 * debounce. That listener is gone, but the debounce stayed on the `cleanup()` path —
	 * and because `watch` runs `cleanup()` once per open (`ref` goes null -> node), every
	 * layer scheduled a reset 20ms into its own lifetime. An outside `pointerdown` landing
	 * 10-20ms after that cleanup would have its `#isResponsibleLayer` flag cleared by the
	 * stale reset in the gap before the debounced `#handleInteractOutside` ran, which then
	 * bailed and left the layer open. `cleanup()` destroys `#handleInteractOutside` anyway,
	 * so nothing is left in flight that needs to observe the pre-reset state.
	 */
	#resetState = () => {
		for (const eventType in this.#interceptedEvents) {
			this.#interceptedEvents[eventType] = false;
		}
		this.#isResponsibleLayer = false;
		this.#capturedPointerDown = null;
	};

	#isAnyEventIntercepted() {
		const i = Object.values(this.#interceptedEvents).some(Boolean);
		return i;
	}

	#onfocuscapture = () => {
		this.#isFocusInsideDOMTree = true;
	};

	#onblurcapture = () => {
		this.#isFocusInsideDOMTree = false;
	};

	props = {
		onfocuscapture: this.#onfocuscapture,
		onblurcapture: this.#onblurcapture,
	};
}

export function getTopMostDismissableLayer(
	layersArr: [DismissibleLayerState, ReadableBox<InteractOutsideBehaviorType>][] = [
		...globalThis.bitsDismissableLayers,
	]
) {
	return layersArr.findLast(
		([_, { current: behaviorType }]) => behaviorType === "close" || behaviorType === "ignore"
	);
}

function isResponsibleLayer(node: HTMLElement): boolean {
	const layersArr = [...globalThis.bitsDismissableLayers];
	/**
	 * We first check if we can find a top layer with `close` or `ignore`.
	 * If that top layer was found and matches the provided node, then the node is
	 * responsible for the outside interaction. Otherwise, we know that all layers defer so
	 * the first layer is the responsible one.
	 */
	const topMostLayer = getTopMostDismissableLayer(layersArr);
	if (topMostLayer) return topMostLayer[0].opts.ref.current === node;
	const [firstLayerNode] = layersArr[0]!;
	return firstLayerNode.opts.ref.current === node;
}

function isValidEvent(e: PointerEvent, node: HTMLElement): boolean {
	const target = e.target;
	if (!isElementOrSVGElement(target)) return false;

	const targetIsContextMenuTrigger = Boolean(target.closest(`[${CONTEXT_MENU_TRIGGER_ATTR}]`));
	const nodeIsContextMenu = Boolean(node.closest(`[${CONTEXT_MENU_CONTENT_ATTR}]`));

	if ("button" in e && e.button > 0 && !targetIsContextMenuTrigger) return false;
	if ("button" in e && e.button === 0 && targetIsContextMenuTrigger && nodeIsContextMenu) {
		return true;
	}
	if (targetIsContextMenuTrigger && nodeIsContextMenu) return false;

	const ownerDocument = getOwnerDocument(target);
	const isValid =
		ownerDocument.documentElement.contains(target) &&
		!isOrContainsTarget(node, target) &&
		isClickTrulyOutside(e, node);
	return isValid;
}

export type FocusOutsideEvent = CustomEvent<{ originalEvent: FocusEvent }>;

function createWrappedEvent(e: PointerEvent | MouseEvent): PointerEvent {
	const capturedCurrentTarget = e.currentTarget;
	const capturedTarget = e.target;

	let newEvent: PointerEvent;

	if (e instanceof PointerEvent) {
		newEvent = new PointerEvent(e.type, e);
	} else {
		newEvent = new PointerEvent("pointerdown", e);
	}

	// track the prevented state separately
	let isPrevented = false;

	// Create a proxy to intercept property access and method calls
	const wrappedEvent = new Proxy(newEvent, {
		get: (target, prop) => {
			if (prop === "currentTarget") {
				return capturedCurrentTarget;
			}
			if (prop === "target") {
				return capturedTarget;
			}
			if (prop === "preventDefault") {
				return () => {
					isPrevented = true;
					if (typeof target.preventDefault === "function") {
						target.preventDefault();
					}
				};
			}
			if (prop === "defaultPrevented") {
				return isPrevented;
			}
			if (prop in target) {
				// oxlint-disable-next-line no-explicit-any
				return (target as any)[prop];
			}
			// oxlint-disable-next-line no-explicit-any
			return (e as any)[prop];
		},
	});

	return wrappedEvent as PointerEvent;
}

import type { Snippet } from "svelte";
import type { Box } from "svelte-toolbelt";

export type EscapeBehaviorType =
	| "close"
	| "defer-otherwise-close"
	| "defer-otherwise-ignore"
	| "ignore";

export type EscapeLayerProps = {
	/**
	 * Callback fired when escape is pressed.
	 */
	onEscapeKeydown?: (e: KeyboardEvent) => void;

	/**
	 * Escape behavior type.
	 * `close`: Closes the element immediately.
	 * `defer-otherwise-close`: Delegates the action to its parent component that has an
	 * escape keydown handler. If no parent is found, it closes the element.
	 * `defer-otherwise-ignore`: Delegates the action to the parent element. If no parent is found, nothing is done.
	 * `ignore`: Prevents the element from closing and also blocks the parent element from closing in response to an escape key press.
	 *
	 * @defaultValue `close`
	 */
	escapeKeydownBehavior?: EscapeBehaviorType;
};

// internal props not exposed to the user but used in the implementation
export type EscapeLayerImplProps = {
	/**
	 * Whether the layer is enabled. Currently, we determine this with the
	 * `presence` returned from the `presence` layer.
	 */
	enabled: boolean;
	children?: Snippet;
	ref: Box<HTMLElement | null>;
} & EscapeLayerProps;

import { DOMContext, type Box, type ReadableBox, type ReadableBoxedValues } from "svelte-toolbelt";
import { watch } from "runed";
import { on } from "svelte/events";
import type { EscapeBehaviorType, EscapeLayerImplProps } from "./types.js";
import { kbd } from "$lib/internal/kbd.js";
import { noop } from "$lib/internal/noop.js";

globalThis.bitsEscapeLayers ??= new Map<EscapeLayerState, ReadableBox<EscapeBehaviorType>>();

interface EscapeLayerStateOpts
	extends ReadableBoxedValues<Required<Omit<EscapeLayerImplProps, "children" | "ref">>> {
	ref: Box<HTMLElement | null>;
}

export class EscapeLayerState {
	static create(opts: EscapeLayerStateOpts) {
		return new EscapeLayerState(opts);
	}
	readonly opts: EscapeLayerStateOpts;
	readonly domContext: DOMContext;

	constructor(opts: EscapeLayerStateOpts) {
		this.opts = opts;
		this.domContext = new DOMContext(this.opts.ref);

		let unsubEvents = noop;
		watch(
			() => opts.enabled.current,
			(enabled) => {
				if (enabled) {
					globalThis.bitsEscapeLayers.set(this, opts.escapeKeydownBehavior);
					unsubEvents = this.#addEventListener();
				}

				return () => {
					unsubEvents();
					globalThis.bitsEscapeLayers.delete(this);
				};
			}
		);
	}

	#addEventListener = () => {
		return on(this.domContext.getDocument(), "keydown", this.#onkeydown, { passive: false });
	};

	#onkeydown = (e: KeyboardEvent) => {
		if (e.key !== kbd.ESCAPE || !isResponsibleEscapeLayer(this)) return;
		const clonedEvent = new KeyboardEvent(e.type, e);
		e.preventDefault();
		const behaviorType = this.opts.escapeKeydownBehavior.current;
		if (behaviorType !== "close" && behaviorType !== "defer-otherwise-close") return;
		this.opts.onEscapeKeydown.current(clonedEvent);
	};
}

function isResponsibleEscapeLayer(instance: EscapeLayerState) {
	const layersArr = [...globalThis.bitsEscapeLayers];
	/**
	 * We first check if we can find a top layer with `close` or `ignore`.
	 * If that top layer was found and matches the provided node, then the node is
	 * responsible for the escape. Otherwise, we know that all layers defer so
	 * the first layer is the responsible one.
	 */
	const topMostLayer = layersArr.findLast(
		([_, { current: behaviorType }]) => behaviorType === "close" || behaviorType === "ignore"
	);
	if (topMostLayer) return topMostLayer[0] === instance;
	const [firstLayerNode] = layersArr[0]!;
	return firstLayerNode === instance;
}

export { default as Anchor } from "./floating-layer-anchor.svelte";
export { default as Arrow } from "./floating-layer-arrow.svelte";
export { default as Content } from "./floating-layer-content.svelte";
export { default as ContentStatic } from "./floating-layer-content-static.svelte";
export { default as Root } from "./floating-layer.svelte";

export type {
	FloatingLayerContentImplProps as ContentImplProps,
	FloatingLayerContentProps as ContentProps,
	FloatingLayerAnchorProps as AnchorProps,
} from "../types.js";

import { type ReadableBox, type ReadableBoxedValues, boxFrom, simpleBox } from "svelte-toolbelt";
import { Context } from "runed";
import type { Measurable } from "$lib/internal/floating-svelte/types.js";

export const FloatingRootContext = new Context<FloatingRootState>("Floating.Root");
export const FloatingTooltipRootContext = new Context<FloatingRootState>("Floating.Root");

export class FloatingRootState {
	static create(tooltip = false) {
		return tooltip
			? FloatingTooltipRootContext.set(new FloatingRootState())
			: FloatingRootContext.set(new FloatingRootState());
	}
	anchorNode = simpleBox<Measurable | HTMLElement | null>(null);
	customAnchorNode = simpleBox<Measurable | HTMLElement | null | string>(null);
	triggerNode: ReadableBox<Measurable | HTMLElement | null> = simpleBox(null);

	constructor() {
		$effect(() => {
			if (this.customAnchorNode.current) {
				if (typeof this.customAnchorNode.current === "string") {
					this.anchorNode.current = document.querySelector(this.customAnchorNode.current);
				} else {
					this.anchorNode.current = this.customAnchorNode.current;
				}
			} else {
				this.anchorNode.current = this.triggerNode.current;
			}
		});
	}
}

interface FloatingAnchorStateOpts
	extends ReadableBoxedValues<{
		id: string;
		virtualEl?: Measurable | null;
		ref: Measurable | HTMLElement | null;
	}> {}

export class FloatingAnchorState {
	static create(opts: FloatingAnchorStateOpts, tooltip = false) {
		return tooltip
			? new FloatingAnchorState(opts, FloatingTooltipRootContext.get())
			: new FloatingAnchorState(opts, FloatingRootContext.get());
	}
	readonly opts: FloatingAnchorStateOpts;
	readonly root: FloatingRootState;

	constructor(opts: FloatingAnchorStateOpts, root: FloatingRootState) {
		this.opts = opts;
		this.root = root;

		if (opts.virtualEl && opts.virtualEl.current) {
			root.triggerNode = boxFrom(opts.virtualEl.current);
		} else {
			root.triggerNode = opts.ref;
		}
	}
}

import type { Snippet } from "svelte";
import type { ReadableBox } from "svelte-toolbelt";
import type { Align, Boundary, Side } from "./use-floating-layer.svelte.js";
import type { Arrayable } from "$lib/internal/types.js";
import type { Direction, StyleProperties } from "$lib/shared/index.js";
import type { Measurable } from "$lib/internal/floating-svelte/types.js";

export type FloatingLayerContentProps = {
	/**
	 * The preferred side of the anchor to render against when open.
	 * Will be reversed when collisions occur.
	 *
	 * @see https://floating-ui.com/docs/computePosition#placement
	 */
	side?: Side;

	/**
	 * The distance in pixels from the anchor to the floating element.
	 * @see https://floating-ui.com/docs/offset#options
	 */
	sideOffset?: number;

	/**
	 * The preferred alignment of the anchor to render against when open.
	 * This may change when collisions occur.
	 *
	 * @see https://floating-ui.com/docs/computePosition#placement
	 */
	align?: Align;

	/**
	 * An offset in pixels from the "start" or "end" alignment options.
	 * @see https://floating-ui.com/docs/offset#options
	 */
	alignOffset?: number | undefined;

	/**
	 * This describes the padding between the arrow and the edges of the floating element.
	 * If your floating element has border-radius, this will prevent it from overflowing
	 * the corners.
	 */
	arrowPadding?: number;

	/**
	 * When `true`, overrides the `side` and `align` options to prevent collisions
	 * with the boundary edges.
	 *
	 * @default true
	 * @see https://floating-ui.com/docs/flip
	 */
	avoidCollisions?: boolean | undefined;

	/**
	 * A boundary element or array of elements to check for collisions against.
	 *
	 * @see https://floating-ui.com/docs/detectoverflow#boundary
	 */
	collisionBoundary?: Arrayable<Boundary>;

	/**
	 * The amount in pixels of virtual padding around the viewport edges to check
	 * for overflow which will cause a collision.
	 *
	 * @default 8
	 * @see https://floating-ui.com/docs/detectOverflow#padding
	 */
	collisionPadding?: number | Partial<Record<Side, number>>;

	sticky?: "partial" | "always";

	hideWhenDetached?: boolean;

	/**
	 * "optimized" will only update the position when necessary, while "always"
	 * will update the position on each animation frame, which is useful if the floating
	 * content is following something like a mouse cursor.
	 *
	 * @defaultValue "optimized"
	 */
	updatePositionStrategy?: "optimized" | "always";

	content?: Snippet<[{ props: Record<string, unknown>; wrapperProps: Record<string, unknown> }]>;

	/**
	 * The positioning strategy to use for the floating element.
	 * @see https://floating-ui.com/docs/computeposition#strategy
	 */
	strategy?: "absolute" | "fixed" | undefined;

	/**
	 * The text direction of the content.
	 */
	dir?: Direction;

	/**
	 * Whether to prevent scrolling the body when the content is open.
	 */
	preventScroll?: boolean;

	/**
	 * Use an element other than the trigger to anchor the content to. If provided,
	 * the content will be anchored to the provided element instead of the trigger.
	 *
	 * You can pass a selector string or an HTMLElement.
	 */
	customAnchor?: string | HTMLElement | Measurable | null;
};

export type FloatingLayerContentImplProps = {
	id: string;

	/**
	 * The ID of the content wrapper element.
	 */
	wrapperId?: string;

	/**
	 * The style properties to apply to the content.
	 */
	style?: StyleProperties | string | null;

	/**
	 * Callback that is called when the floating element is placed.
	 */
	onPlaced?: () => void;
	enabled: boolean;
	/**
	 * Tooltips are special in that they are commonly composed
	 * with other floating components, where the same trigger is
	 * used for both the tooltip and the popover.
	 *
	 * For situations like this, we need to use a different context
	 * symbol so that conflicts don't occur.
	 */
	tooltip?: boolean;
} & FloatingLayerContentProps;

export type FloatingLayerAnchorProps = {
	id: string;
	children?: Snippet;
	virtualEl?: ReadableBox<Measurable | null>;
	ref: ReadableBox<HTMLElement | null>;
	/**
	 * Tooltips are special in that they are commonly composed
	 * with other floating components, where the same trigger is
	 * used for both the tooltip and the popover.
	 *
	 * For situations like this, we need to use a different context
	 * symbol so that conflicts don't occur.
	 */
	tooltip?: boolean;
};

import {
	type Middleware,
	type Placement,
	arrow,
	autoUpdate,
	flip,
	hide,
	limitShift,
	offset,
	shift,
	size,
} from "@floating-ui/dom";
import {
	attachRef,
	cssToStyleObj,
	getWindow,
	styleToString,
	type ReadableBoxedValues,
	type Box,
	simpleBox,
} from "svelte-toolbelt";
import { Context, ElementSize, watch } from "runed";
import {
	FloatingRootContext,
	FloatingTooltipRootContext,
	type FloatingRootState,
} from "./floating-root.svelte.js";
import type { Arrayable, WithRefOpts } from "$lib/internal/types.js";
import { isNotNull } from "$lib/internal/is.js";
import { useId } from "$lib/internal/use-id.js";
import { useFloating } from "$lib/internal/floating-svelte/use-floating.svelte.js";
import type { Measurable, UseFloatingReturn } from "$lib/internal/floating-svelte/types.js";
import type { Direction, StyleProperties } from "$lib/shared/index.js";

export const SIDE_OPTIONS = ["top", "right", "bottom", "left"] as const;
export const ALIGN_OPTIONS = ["start", "center", "end"] as const;

const OPPOSITE_SIDE: Record<Side, Side> = {
	top: "bottom",
	right: "left",
	bottom: "top",
	left: "right",
};

const FloatingContentContext = new Context<FloatingContentState>("Floating.Content");

export type Side = (typeof SIDE_OPTIONS)[number];
export type Align = (typeof ALIGN_OPTIONS)[number];

export type Boundary = Element | null;

export interface FloatingContentStateOpts
	extends ReadableBoxedValues<{
		id: string;
		wrapperId: string;
		side: Side;
		sideOffset: number;
		align: Align;
		alignOffset: number;
		arrowPadding: number;
		avoidCollisions: boolean;
		collisionBoundary: Arrayable<Boundary>;
		collisionPadding: number | Partial<Record<Side, number>>;
		sticky: "partial" | "always";
		hideWhenDetached: boolean;
		updatePositionStrategy: "optimized" | "always";
		strategy: "fixed" | "absolute";
		onPlaced: () => void;
		dir: Direction;
		style: StyleProperties | null | undefined | string;
		enabled: boolean;
		customAnchor: string | HTMLElement | null | Measurable;
	}> {}

export class FloatingContentState {
	static create(opts: FloatingContentStateOpts, tooltip = false) {
		return tooltip
			? FloatingContentContext.set(
					new FloatingContentState(opts, FloatingTooltipRootContext.get())
				)
			: FloatingContentContext.set(new FloatingContentState(opts, FloatingRootContext.get()));
	}
	readonly opts: FloatingContentStateOpts;
	readonly root: FloatingRootState;

	// nodes
	contentRef = simpleBox<HTMLElement | null>(null);
	wrapperRef = simpleBox<HTMLElement | null>(null);
	arrowRef = simpleBox<HTMLElement | null>(null);
	readonly contentAttachment = attachRef(this.contentRef);
	readonly wrapperAttachment = attachRef(this.wrapperRef);
	readonly arrowAttachment = attachRef(this.arrowRef);

	// ids
	arrowId: Box<string> = simpleBox(useId());

	#transformedStyle = $derived.by(() => {
		if (typeof this.opts.style === "string") return cssToStyleObj(this.opts.style);
		if (!this.opts.style) return {};
	});

	#updatePositionStrategy =
		undefined as unknown as FloatingContentStateOpts["updatePositionStrategy"];
	#arrowSize = new ElementSize(() => this.arrowRef.current ?? undefined);
	#arrowWidth = $derived(this.#arrowSize?.width ?? 0);
	#arrowHeight = $derived(this.#arrowSize?.height ?? 0);
	#desiredPlacement = $derived.by(
		() =>
			(this.opts.side?.current +
				(this.opts.align.current !== "center"
					? `-${this.opts.align.current}`
					: "")) as Placement
	);
	#boundary = $derived.by(() =>
		Array.isArray(this.opts.collisionBoundary.current)
			? this.opts.collisionBoundary.current
			: [this.opts.collisionBoundary.current]
	);
	hasExplicitBoundaries = $derived(this.#boundary.length > 0);
	detectOverflowOptions = $derived.by(() => ({
		padding: this.opts.collisionPadding.current,
		boundary: this.#boundary.filter(isNotNull),
		altBoundary: this.hasExplicitBoundaries,
	}));
	#availableWidth = $state<number | undefined>(undefined);
	#availableHeight = $state<number | undefined>(undefined);
	#anchorWidth = $state<number | undefined>(undefined);
	#anchorHeight = $state<number | undefined>(undefined);
	middleware: Middleware[] = $derived.by(
		() =>
			[
				offset({
					mainAxis: this.opts.sideOffset.current + this.#arrowHeight,
					alignmentAxis: this.opts.alignOffset.current,
				}),
				this.opts.avoidCollisions.current &&
					shift({
						mainAxis: true,
						crossAxis: false,
						limiter: this.opts.sticky.current === "partial" ? limitShift() : undefined,
						...this.detectOverflowOptions,
					}),
				this.opts.avoidCollisions.current && flip({ ...this.detectOverflowOptions }),
				size({
					...this.detectOverflowOptions,
					apply: ({ rects, availableWidth, availableHeight }) => {
						const { width: anchorWidth, height: anchorHeight } = rects.reference;
						this.#availableWidth = availableWidth;
						this.#availableHeight = availableHeight;
						this.#anchorWidth = anchorWidth;
						this.#anchorHeight = anchorHeight;
					},
				}),
				this.arrowRef.current &&
					arrow({
						element: this.arrowRef.current,
						padding: this.opts.arrowPadding.current,
					}),
				transformOrigin({ arrowWidth: this.#arrowWidth, arrowHeight: this.#arrowHeight }),
				this.opts.hideWhenDetached.current &&
					hide({ strategy: "referenceHidden", ...this.detectOverflowOptions }),
			].filter(Boolean) as Middleware[]
	);
	floating: UseFloatingReturn;
	placedSide = $derived.by(() => getSideFromPlacement(this.floating.placement));
	placedAlign = $derived.by(() => getAlignFromPlacement(this.floating.placement));
	arrowX = $derived.by(() => this.floating.middlewareData.arrow?.x ?? 0);
	arrowY = $derived.by(() => this.floating.middlewareData.arrow?.y ?? 0);
	cannotCenterArrow = $derived.by(() => this.floating.middlewareData.arrow?.centerOffset !== 0);
	contentZIndex = $state<string>();
	arrowBaseSide = $derived(OPPOSITE_SIDE[this.placedSide]);
	wrapperProps = $derived.by(
		() =>
			({
				id: this.opts.wrapperId.current,
				"data-bits-floating-content-wrapper": "",
				style: {
					...this.floating.floatingStyles,
					// keep off page when measuring
					transform: this.floating.isPositioned
						? this.floating.floatingStyles.transform
						: "translate(0, -200%)",
					minWidth: "max-content",
					zIndex: this.contentZIndex,
					"--bits-floating-transform-origin": `${this.floating.middlewareData.transformOrigin?.x} ${this.floating.middlewareData.transformOrigin?.y}`,
					"--bits-floating-available-width": `${this.#availableWidth}px`,
					"--bits-floating-available-height": `${this.#availableHeight}px`,
					"--bits-floating-anchor-width": `${this.#anchorWidth}px`,
					"--bits-floating-anchor-height": `${this.#anchorHeight}px`,
					// hide the content if using the hide middleware and should be hidden
					...(this.floating.middlewareData.hide?.referenceHidden && {
						visibility: "hidden",
						"pointer-events": "none",
					}),
					...this.#transformedStyle,
				},
				// Floating UI calculates logical alignment based the `dir` attribute
				dir: this.opts.dir.current,
				...this.wrapperAttachment,
			}) as const
	);
	props = $derived.by(
		() =>
			({
				"data-side": this.placedSide,
				"data-align": this.placedAlign,
				style: styleToString({
					...this.#transformedStyle,
				}),
				...this.contentAttachment,
			}) as const
	);

	arrowStyle = $derived({
		position: "absolute",
		left: this.arrowX ? `${this.arrowX}px` : undefined,
		top: this.arrowY ? `${this.arrowY}px` : undefined,
		[this.arrowBaseSide]: 0,
		"transform-origin": {
			top: "",
			right: "0 0",
			bottom: "center 0",
			left: "100% 0",
		}[this.placedSide],
		transform: {
			top: "translateY(100%)",
			right: "translateY(50%) rotate(90deg) translateX(-50%)",
			bottom: "rotate(180deg)",
			left: "translateY(50%) rotate(-90deg) translateX(50%)",
		}[this.placedSide],
		visibility: this.cannotCenterArrow ? "hidden" : undefined,
	});

	constructor(opts: FloatingContentStateOpts, root: FloatingRootState) {
		this.opts = opts;
		this.root = root;
		this.#updatePositionStrategy = opts.updatePositionStrategy;

		if (opts.customAnchor) {
			this.root.customAnchorNode.current = opts.customAnchor.current;
		}

		watch(
			() => opts.customAnchor.current,
			(customAnchor) => {
				this.root.customAnchorNode.current = customAnchor;
			}
		);

		this.floating = useFloating({
			strategy: () => this.opts.strategy.current,
			placement: () => this.#desiredPlacement,
			middleware: () => this.middleware,
			reference: this.root.anchorNode,
			whileElementsMounted: (...args) => {
				const cleanup = autoUpdate(...args, {
					animationFrame: this.#updatePositionStrategy?.current === "always",
				});
				return cleanup;
			},
			open: () => this.opts.enabled.current,
			sideOffset: () => this.opts.sideOffset.current,
			alignOffset: () => this.opts.alignOffset.current,
		});

		$effect(() => {
			if (!this.floating.isPositioned) return;
			this.opts.onPlaced?.current();
		});

		watch(
			() => this.contentRef.current,
			(contentNode) => {
				if (!contentNode || !this.opts.enabled.current) return;
				const win = getWindow(contentNode);
				const rafId = win.requestAnimationFrame(() => {
					// avoid applying stale values when refs change quickly
					if (this.contentRef.current !== contentNode || !this.opts.enabled.current)
						return;
					const zIndex = win.getComputedStyle(contentNode).zIndex;
					if (zIndex !== this.contentZIndex) {
						this.contentZIndex = zIndex;
					}
				});

				return () => {
					win.cancelAnimationFrame(rafId);
				};
			}
		);

		$effect(() => {
			this.floating.floating.current = this.wrapperRef.current;
		});
	}
}

interface FloatingArrowStateOpts extends WithRefOpts {}

export class FloatingArrowState {
	static create(opts: FloatingArrowStateOpts) {
		return new FloatingArrowState(opts, FloatingContentContext.get());
	}
	readonly opts: FloatingArrowStateOpts;
	readonly content: FloatingContentState;

	constructor(opts: FloatingArrowStateOpts, content: FloatingContentState) {
		this.opts = opts;
		this.content = content;
	}

	readonly props = $derived.by(
		() =>
			({
				id: this.opts.id.current,
				style: this.content.arrowStyle,
				"data-side": this.content.placedSide,
				...this.content.arrowAttachment,
			}) as const
	);
}

//
// HELPERS
//

function transformOrigin(options: { arrowWidth: number; arrowHeight: number }): Middleware {
	return {
		name: "transformOrigin",
		options,
		fn(data) {
			const { placement, rects, middlewareData } = data;

			const cannotCenterArrow = middlewareData.arrow?.centerOffset !== 0;
			const isArrowHidden = cannotCenterArrow;
			const arrowWidth = isArrowHidden ? 0 : options.arrowWidth;
			const arrowHeight = isArrowHidden ? 0 : options.arrowHeight;

			const [placedSide, placedAlign] = getSideAndAlignFromPlacement(placement);
			const noArrowAlign = { start: "0%", center: "50%", end: "100%" }[placedAlign];

			const arrowXCenter = (middlewareData.arrow?.x ?? 0) + arrowWidth / 2;
			const arrowYCenter = (middlewareData.arrow?.y ?? 0) + arrowHeight / 2;

			let x = "";
			let y = "";

			if (placedSide === "bottom") {
				x = isArrowHidden ? noArrowAlign : `${arrowXCenter}px`;
				y = `${-arrowHeight}px`;
			} else if (placedSide === "top") {
				x = isArrowHidden ? noArrowAlign : `${arrowXCenter}px`;
				y = `${rects.floating.height + arrowHeight}px`;
			} else if (placedSide === "right") {
				x = `${-arrowHeight}px`;
				y = isArrowHidden ? noArrowAlign : `${arrowYCenter}px`;
			} else if (placedSide === "left") {
				x = `${rects.floating.width + arrowHeight}px`;
				y = isArrowHidden ? noArrowAlign : `${arrowYCenter}px`;
			}
			return { data: { x, y } };
		},
	};
}

function getSideAndAlignFromPlacement(placement: Placement) {
	const [side, align = "center"] = placement.split("-");
	return [side as Side, align as Align] as const;
}

export function getSideFromPlacement(placement: Placement) {
	return getSideAndAlignFromPlacement(placement)[0];
}

export function getAlignFromPlacement(placement: Placement) {
	return getSideAndAlignFromPlacement(placement)[1];
}

import { getActiveElement, simpleBox } from "svelte-toolbelt";
import { FocusScope } from "./focus-scope.svelte.js";

export class FocusScopeManager {
	static instance: FocusScopeManager;
	#scopeStack = simpleBox<FocusScope[]>([]);
	#focusHistory = new WeakMap<FocusScope, HTMLElement>();
	#preFocusHistory = new WeakMap<FocusScope, HTMLElement>();

	static getInstance() {
		if (!this.instance) {
			this.instance = new FocusScopeManager();
		}
		return this.instance;
	}

	register(scope: FocusScope) {
		const current = this.getActive();
		if (current && current !== scope) {
			current.pause();
		}

		// capture the currently focused element before this scope becomes active
		const activeElement = getActiveElement(document);
		if (activeElement && activeElement !== document.body) {
			this.#preFocusHistory.set(scope, activeElement);
		}

		this.#scopeStack.current = this.#scopeStack.current.filter((s) => s !== scope);
		this.#scopeStack.current.unshift(scope);
	}

	unregister(scope: FocusScope) {
		this.#scopeStack.current = this.#scopeStack.current.filter((s) => s !== scope);
		const next = this.getActive();
		if (next) {
			next.resume();
		}
	}

	getActive(): FocusScope | undefined {
		return this.#scopeStack.current[0];
	}

	setFocusMemory(scope: FocusScope, element: HTMLElement) {
		this.#focusHistory.set(scope, element);
	}

	getFocusMemory(scope: FocusScope): HTMLElement | undefined {
		return this.#focusHistory.get(scope);
	}

	isActiveScope(scope: FocusScope): boolean {
		return this.getActive() === scope;
	}

	setPreFocusMemory(scope: FocusScope, element: HTMLElement) {
		this.#preFocusHistory.set(scope, element);
	}

	getPreFocusMemory(scope: FocusScope): HTMLElement | undefined {
		return this.#preFocusHistory.get(scope);
	}

	clearPreFocusMemory(scope: FocusScope) {
		this.#preFocusHistory.delete(scope);
	}
}

import { getActiveElement, onDestroyEffect, type ReadableBoxedValues } from "svelte-toolbelt";
import { FocusScopeManager } from "./focus-scope-manager.js";
import { focusable, isFocusable, tabbable } from "tabbable";
import { on } from "svelte/events";
import { watch } from "runed";

interface FocusScopeOpts
	extends ReadableBoxedValues<{
		onOpenAutoFocus: (event: Event) => void;
		onCloseAutoFocus: (event: Event) => void;
		trap: boolean;
	}> {
	loop: boolean;
}

interface FocusScopeUseOpts
	extends FocusScopeOpts,
		ReadableBoxedValues<{
			enabled: boolean;
			ref: HTMLElement | null;
		}> {}

export class FocusScope {
	#paused = false;
	#container: HTMLElement | null = null;
	#manager = FocusScopeManager.getInstance();
	#cleanupFns: Array<() => void> = [];
	#opts: FocusScopeOpts;

	constructor(opts: FocusScopeOpts) {
		this.#opts = opts;
	}

	get paused() {
		return this.#paused;
	}

	pause() {
		this.#paused = true;
	}

	resume() {
		this.#paused = false;
	}

	#cleanup() {
		for (const fn of this.#cleanupFns) {
			fn();
		}
		this.#cleanupFns = [];
	}

	mount(container: HTMLElement) {
		if (this.#container) {
			this.unmount();
		}

		this.#container = container;
		this.#manager.register(this);

		this.#setupEventListeners();
		this.#handleOpenAutoFocus();
	}

	unmount() {
		if (!this.#container) return;

		this.#cleanup();

		// handle close auto-focus
		this.#handleCloseAutoFocus();

		this.#manager.unregister(this);
		this.#manager.clearPreFocusMemory(this);
		this.#container = null;
	}

	#handleOpenAutoFocus() {
		if (!this.#container) return;

		const event = new CustomEvent("focusScope.onOpenAutoFocus", {
			bubbles: false,
			cancelable: true,
		});
		this.#opts.onOpenAutoFocus.current(event);

		if (!event.defaultPrevented) {
			requestAnimationFrame(() => {
				if (
					!this.#container ||
					this.#paused ||
					!this.#manager.isActiveScope(this) ||
					this.#container.contains(getActiveElement(this.#container.ownerDocument))
				) {
					return;
				}
				const firstTabbable = this.#getFirstTabbable();
				if (firstTabbable) {
					firstTabbable.focus();
					this.#manager.setFocusMemory(this, firstTabbable);
				} else {
					this.#container.focus();
				}
			});
		}
	}

	#handleCloseAutoFocus() {
		const event = new CustomEvent("focusScope.onCloseAutoFocus", {
			bubbles: false,
			cancelable: true,
		});

		this.#opts.onCloseAutoFocus.current?.(event);

		if (!event.defaultPrevented) {
			// return focus to the element that was focused before this scope opened
			const preFocusedElement = this.#manager.getPreFocusMemory(this);
			if (preFocusedElement && preFocusedElement.isConnected) {
				// ensure the element is still focusable and in the document
				try {
					preFocusedElement.focus();
				} catch {
					// fallback if focus fails
					document.body.focus();
				}
			}
		}
	}

	#setupEventListeners() {
		if (!this.#container || !this.#opts.trap.current) return;

		const container = this.#container;
		const doc = container.ownerDocument;

		const handleFocus = (e: FocusEvent) => {
			if (this.#paused || !this.#manager.isActiveScope(this)) return;

			const target = e.composedPath()[0] as HTMLElement;
			if (!target) return;

			const isInside = container.contains(target);

			if (isInside) {
				// store last focused element
				this.#manager.setFocusMemory(this, target);
			} else {
				// focus escaped - bring it back
				const lastFocused = this.#manager.getFocusMemory(this);
				if (lastFocused && container.contains(lastFocused) && isFocusable(lastFocused)) {
					e.preventDefault();
					lastFocused.focus();
				} else {
					// fallback to first tabbable or first focusable or container
					const firstTabbable = this.#getFirstTabbable();
					const firstFocusable = this.#getAllFocusables()[0];
					(firstTabbable || firstFocusable || container).focus();
				}
			}
		};

		const handleKeydown = (e: KeyboardEvent) => {
			if (!this.#opts.loop || this.#paused || e.key !== "Tab") return;
			if (!this.#manager.isActiveScope(this)) return;

			const tabbables = this.#getTabbables();
			if (tabbables.length === 0) return;

			const first = tabbables[0];
			const last = tabbables[tabbables.length - 1];

			if (!e.shiftKey && getActiveElement(doc) === last) {
				e.preventDefault();
				first!.focus();
			} else if (e.shiftKey && getActiveElement(doc) === first) {
				e.preventDefault();
				last!.focus();
			}
		};

		this.#cleanupFns.push(
			on(doc, "focusin", handleFocus, { capture: true }),
			on(container, "keydown", handleKeydown)
		);

		const observer = new MutationObserver(() => {
			const lastFocused = this.#manager.getFocusMemory(this);
			if (lastFocused && !container.contains(lastFocused)) {
				// last focused element was removed
				const firstTabbable = this.#getFirstTabbable();
				const firstFocusable = this.#getAllFocusables()[0];
				const elementToFocus = firstTabbable || firstFocusable;

				if (elementToFocus) {
					elementToFocus.focus();
					this.#manager.setFocusMemory(this, elementToFocus);
				} else {
					// no focusable elements left, focus container
					container.focus();
				}
			}
		});

		observer.observe(container, {
			childList: true,
			subtree: true,
		});

		this.#cleanupFns.push(() => observer.disconnect());
	}

	#getTabbables(): HTMLElement[] {
		if (!this.#container) return [];

		return tabbable(this.#container, {
			includeContainer: false,
			getShadowRoot: true,
		}) as HTMLElement[];
	}

	#getFirstTabbable(): HTMLElement | null {
		const tabbables = this.#getTabbables();
		return tabbables[0] || null;
	}

	#getAllFocusables(): HTMLElement[] {
		if (!this.#container) return [];

		return focusable(this.#container, {
			includeContainer: false,
			getShadowRoot: true,
		}) as HTMLElement[];
	}

	static use(opts: FocusScopeUseOpts) {
		let scope: FocusScope | null = null;

		watch([() => opts.ref.current, () => opts.enabled.current], ([ref, enabled]) => {
			if (ref && enabled) {
				if (!scope) {
					scope = new FocusScope(opts);
				}
				scope.mount(ref);
			} else if (scope) {
				scope.unmount();
				scope = null;
			}
		});

		onDestroyEffect(() => {
			scope?.unmount();
		});

		return {
			get props() {
				return {
					tabindex: -1,
				};
			},
		};
	}
}

