import {
	DOMContext,
	type ReadableBox,
	type ReadableBoxedValues,
	contains,
	executeCallbacks,
} from "svelte-toolbelt";
import { watch } from "runed";
import { on } from "svelte/events";
import type { PointerHandler, TextSelectionLayerImplProps } from "./types.js";
import { noop } from "$lib/internal/noop.js";
import { isHTMLElement } from "$lib/internal/is.js";

const noopPointer: PointerHandler = () => {};

interface TextSelectionLayerStateOpts
	extends ReadableBoxedValues<
		Required<
			Omit<TextSelectionLayerImplProps, "children" | "preventOverflowTextSelection" | "ref">
		> & {
			ref: HTMLElement | null;
		}
	> {}

globalThis.bitsTextSelectionLayers ??= new Map<TextSelectionLayerState, ReadableBox<boolean>>();

export class TextSelectionLayerState {
	static create(opts: TextSelectionLayerStateOpts) {
		return new TextSelectionLayerState(opts);
	}
	readonly opts: TextSelectionLayerStateOpts;
	readonly domContext: DOMContext;
	#unsubSelectionLock = noop;
	#enabledSnapshot = false;
	#onPointerDownSnapshot: PointerHandler = noopPointer;
	#onPointerUpSnapshot: PointerHandler = noopPointer;

	constructor(opts: TextSelectionLayerStateOpts) {
		this.opts = opts;
		this.domContext = new DOMContext(opts.ref);

		let unsubEvents = noop;

		watch(
			() =>
				[
					this.opts.enabled.current,
					this.opts.onPointerDown.current,
					this.opts.onPointerUp.current,
				] as const,
			([enabled, onPointerDown, onPointerUp]) => {
				this.#enabledSnapshot = enabled;
				this.#onPointerDownSnapshot = onPointerDown;
				this.#onPointerUpSnapshot = onPointerUp;

				if (enabled) {
					globalThis.bitsTextSelectionLayers.set(this, this.opts.enabled);
					unsubEvents();
					unsubEvents = this.#addEventListeners();
				}
				return () => {
					this.#enabledSnapshot = false;
					unsubEvents();
					this.#resetSelectionLock();
					globalThis.bitsTextSelectionLayers.delete(this);
				};
			}
		);
	}

	#addEventListeners() {
		return executeCallbacks(
			on(this.domContext.getDocument(), "pointerdown", this.#pointerdown),
			on(this.domContext.getDocument(), "pointerup", this.#pointerup)
		);
	}

	#pointerup = (e: PointerEvent) => {
		// Releasing the lock is internal cleanup, not a consumer callback, so it must run
		// whatever the event's default-prevented state. Composing it with the user handler
		// meant `composeHandlers` bailed out of the whole chain on a `pointerup` that
		// anything else had cancelled, leaving `user-select: none` on `<body>`.
		this.#resetSelectionLock();
		if (e.defaultPrevented) return;
		this.#onPointerUpSnapshot(e);
	};

	#pointerdown = (e: PointerEvent) => {
		// Check the plain-boolean snapshot BEFORE reading `this.opts.ref.current`.
		// If this document listener outlives its component, that box is a `$derived`
		// owned by a destroyed effect, and reading it emits `derived_inert` on every
		// pointerdown anywhere in the document, forever.
		if (!this.#enabledSnapshot) return;
		// Release any lock still held before arming a new one. Under `forceMount` this
		// handler can run twice for a single event, and `preventTextSelectionOverflow`
		// snapshots the current `user-select` to restore later. Resetting the lock
		// prevents the second arm from re-snapshotting the `none` written the first time.
		this.#resetSelectionLock();
		const node = this.opts.ref.current;
		const target = e.target;
		if (!isHTMLElement(node) || !isHTMLElement(target)) return;
		/**
		 * We only lock user-selection overflow if layer is the top most layer and
		 * pointerdown occurred inside the node. You are still allowed to select text
		 * outside the node provided pointerdown occurs outside the node.
		 */
		if (!isHighestLayer(this) || !contains(node, target)) return;
		this.#onPointerDownSnapshot(e);
		if (e.defaultPrevented) return;
		this.#unsubSelectionLock = preventTextSelectionOverflow(
			node,
			this.domContext.getDocument().body
		);
	};

	#resetSelectionLock = () => {
		this.#unsubSelectionLock();
		this.#unsubSelectionLock = noop;
	};
}

const getUserSelect = (node: HTMLElement) => node.style.userSelect || node.style.webkitUserSelect;

function preventTextSelectionOverflow(node: HTMLElement, body: HTMLElement) {
	const originalBodyUserSelect = getUserSelect(body);
	const originalNodeUserSelect = getUserSelect(node);
	setUserSelect(body, "none");
	setUserSelect(node, "text");
	return () => {
		setUserSelect(body, originalBodyUserSelect);
		setUserSelect(node, originalNodeUserSelect);
	};
}

function setUserSelect(node: HTMLElement, value: string) {
	node.style.userSelect = value;
	node.style.webkitUserSelect = value;
}

function isHighestLayer(instance: TextSelectionLayerState) {
	const layersArr = [...globalThis.bitsTextSelectionLayers];
	if (!layersArr.length) return false;
	const highestLayer = layersArr.at(-1);
	if (!highestLayer) return false;
	return highestLayer[0] === instance;
}

import type { WithChild } from "$lib/internal/types.js";
import type { BitsPrimitiveSpanAttributes } from "$lib/shared/attributes.js";

export type VisuallyHiddenProps = WithChild<BitsPrimitiveSpanAttributes>;

import { afterTick, onDestroyEffect, type ReadableBoxedValues } from "svelte-toolbelt";

interface AnimationsCompleteOpts
	extends ReadableBoxedValues<{
		ref: HTMLElement | null;
		afterTick: boolean;
	}> {}

export class AnimationsComplete {
	#opts: AnimationsCompleteOpts;
	#currentFrame: number | null = null;
	#observer: MutationObserver | null = null;
	#runId = 0;

	constructor(opts: AnimationsCompleteOpts) {
		this.#opts = opts;
		onDestroyEffect(() => this.#cleanup());
	}

	#cleanup(): void {
		if (this.#currentFrame !== null) {
			window.cancelAnimationFrame(this.#currentFrame);
			this.#currentFrame = null;
		}
		this.#observer?.disconnect();
		this.#observer = null;
		this.#runId++;
	}

	run(fn: () => void | Promise<void>): void {
		this.#cleanup();

		const node = this.#opts.ref.current;
		if (!node) return;

		if (typeof node.getAnimations !== "function") {
			this.#executeCallback(fn);
			return;
		}

		const runId = this.#runId;

		const executeIfCurrent = (): void => {
			if (runId !== this.#runId) return;
			this.#executeCallback(fn);
		};

		const waitForAnimations = (): void => {
			if (runId !== this.#runId) return;
			const animations = node.getAnimations();

			if (animations.length === 0) {
				executeIfCurrent();
				return;
			}

			Promise.all(animations.map((animation) => animation.finished))
				.then(() => {
					executeIfCurrent();
				})
				.catch(() => {
					if (runId !== this.#runId) return;
					const currentAnimations = node.getAnimations();
					const hasRunningAnimations = currentAnimations.some(
						(animation) => animation.pending || animation.playState !== "finished"
					);

					if (hasRunningAnimations) {
						waitForAnimations();
						return;
					}

					executeIfCurrent();
				});
		};

		const requestWaitForAnimations = (): void => {
			this.#currentFrame = window.requestAnimationFrame(() => {
				this.#currentFrame = null;
				waitForAnimations();
			});
		};

		if (!this.#opts.afterTick.current) {
			requestWaitForAnimations();
			return;
		}

		this.#currentFrame = window.requestAnimationFrame(() => {
			this.#currentFrame = null;
			const startingStyleAttr = "data-starting-style";

			if (!node.hasAttribute(startingStyleAttr)) {
				requestWaitForAnimations();
				return;
			}

			this.#observer = new MutationObserver(() => {
				if (runId !== this.#runId) return;
				if (node.hasAttribute(startingStyleAttr)) return;

				this.#observer?.disconnect();
				this.#observer = null;
				requestWaitForAnimations();
			});

			this.#observer.observe(node, {
				attributes: true,
				attributeFilter: [startingStyleAttr],
			});
		});
	}

	#executeCallback(fn: () => void | Promise<void>): void {
		const execute = () => {
			fn();
		};

		if (this.#opts.afterTick) {
			afterTick(execute);
		} else {
			execute();
		}
	}
}

