describe("createBitsAttrs", () => {
	it("creates attrs object with component prefix when no variant", () => {
		const config: BitsAttrsConfig<["root", "trigger", "content"]> = {
			component: "dialog",
			parts: ["root", "trigger", "content"],
		};

		const attrs = createBitsAttrs(config);

		expect(attrs.root).toBe("data-dialog-root");
		expect(attrs.trigger).toBe("data-dialog-trigger");
		expect(attrs.content).toBe("data-dialog-content");
	});

	it("creates attrs object with variant prefix when variant is provided", () => {
		const config: BitsAttrsConfig<["root", "trigger"]> = {
			component: "dialog",
			parts: ["root", "trigger"],
			getVariant: () => "mobile",
		};

		const attrs = createBitsAttrs(config);

		expect(attrs.root).toBe("data-mobile-root");
		expect(attrs.trigger).toBe("data-mobile-trigger");
	});

	it("creates attrs object with component prefix when variant returns null", () => {
		const config: BitsAttrsConfig<["root"]> = {
			component: "dialog",
			parts: ["root"],
			getVariant: () => null,
		};

		const attrs = createBitsAttrs(config);

		expect(attrs.root).toBe("data-dialog-root");
	});

	it("provides selector function that wraps attr in brackets", () => {
		const config: BitsAttrsConfig<["root", "trigger"]> = {
			component: "dialog",
			parts: ["root", "trigger"],
		};

		const attrs = createBitsAttrs(config);

		expect(attrs.selector("root")).toBe("[data-dialog-root]");
		expect(attrs.selector("trigger")).toBe("[data-dialog-trigger]");
	});

	it("provides getAttr function that returns the attribute name", () => {
		const config: BitsAttrsConfig<["root", "trigger"]> = {
			component: "dialog",
			parts: ["root", "trigger"],
		};

		const attrs = createBitsAttrs(config);

		expect(attrs.getAttr("root")).toBe("data-dialog-root");
		expect(attrs.getAttr("trigger")).toBe("data-dialog-trigger");
	});

	it("works with single part", () => {
		const config: BitsAttrsConfig<["root"]> = {
			component: "button",
			parts: ["root"],
		};

		const attrs = createBitsAttrs(config);

		expect(attrs.root).toBe("data-button-root");
		expect(attrs.selector("root")).toBe("[data-button-root]");
		expect(attrs.getAttr("root")).toBe("data-button-root");
	});

	it("handles empty parts array", () => {
		const config: BitsAttrsConfig<[]> = {
			component: "empty",
			parts: [],
		};

		const attrs = createBitsAttrs(config);

		expect(typeof attrs.selector).toBe("function");
		expect(typeof attrs.getAttr).toBe("function");
	});
});

export function boolToStr(condition: boolean): "true" | "false" {
	return condition ? "true" : "false";
}

export function boolToStrTrueOrUndef(condition: boolean): "true" | undefined {
	return condition ? "true" : undefined;
}

export function boolToEmptyStrOrUndef(condition: boolean): "" | undefined {
	return condition ? "" : undefined;
}

export function boolToTrueOrUndef(condition: boolean): true | undefined {
	return condition ? true : undefined;
}

export function getDataOpenClosed(condition: boolean): "open" | "closed" {
	return condition ? "open" : "closed";
}

export function getDataChecked(condition: boolean): "checked" | "unchecked" {
	return condition ? "checked" : "unchecked";
}

export type TransitionState = "starting" | "ending" | "idle" | undefined;

export function getDataTransitionAttrs(state: TransitionState): {
	"data-starting-style"?: "";
	"data-ending-style"?: "";
} {
	if (state === "starting") return { "data-starting-style": "" };
	if (state === "ending") return { "data-ending-style": "" };
	return {};
}

export function getAriaChecked(
	checked: boolean,
	indeterminate: boolean
): "true" | "false" | "mixed" {
	if (indeterminate) return "mixed";
	return checked ? "true" : "false";
}

export type BitsAttrsConfig<T extends readonly string[]> = {
	component: string;
	parts: T;
	getVariant?: () => string | null;
};

export type CreateBitsAttrsReturn<T extends readonly string[]> = {
	[K in T[number]]: string;
} & {
	selector: (part: T[number]) => string;
	getAttr: (part: T[number], variant?: string) => string;
};

export class BitsAttrs<T extends readonly string[]> {
	readonly #variant: string | null;
	readonly #prefix: string;
	attrs: Record<T[number], string>;

	constructor(config: BitsAttrsConfig<T>) {
		this.#variant = config.getVariant ? config.getVariant() : null;
		this.#prefix = this.#variant ? `data-${this.#variant}-` : `data-${config.component}-`;

		this.getAttr = this.getAttr.bind(this);
		this.selector = this.selector.bind(this);

		this.attrs = Object.fromEntries(
			config.parts.map((part) => [part, this.getAttr(part)])
		) as Record<T[number], string>;
	}

	getAttr(part: T[number], variantOverride?: string): string {
		if (variantOverride) return `data-${variantOverride}-${part}`;
		return `${this.#prefix}${part}`;
	}

	selector(part: T[number], variantOverride?: string): string {
		return `[${this.getAttr(part, variantOverride)}]`;
	}
}

export function createBitsAttrs<const T extends readonly string[]>(
	config: Omit<BitsAttrsConfig<T>, "parts"> & { parts: T }
): CreateBitsAttrsReturn<T> {
	const bitsAttrs = new BitsAttrs(config);

	return {
		...bitsAttrs.attrs,
		selector: bitsAttrs.selector,
		getAttr: bitsAttrs.getAttr,
	} as CreateBitsAttrsReturn<T>;
}

import { flushSync, tick } from "svelte";
import { describe, expect, it, vi } from "vitest";
import { BodyScrollLock } from "./body-scroll-lock.svelte.js";

describe("BodyScrollLock", () => {
	it.each(["unavailable", "replaced"])(
		"restores the original body when the global document is %s before delayed cleanup",
		async (scenario) => {
			const originalDocument = document;
			const originalStyle = document.body.getAttribute("style");
			const replacementDocument = document.implementation.createHTMLDocument();
			replacementDocument.body.style.color = "blue";
			const replacementStyle = replacementDocument.body.getAttribute("style");
			originalDocument.body.style.cssText = "color: red; overflow: auto;";
			const initialStyle = originalDocument.body.getAttribute("style");
			let destroy: (() => void) | undefined;

			try {
				destroy = $effect.root(() => {
					new BodyScrollLock(true);
				});
				flushSync();
				await tick();
				expect(originalDocument.body.style.overflow).toBe("hidden");

				vi.useFakeTimers();
				const setTimeout = vi.spyOn(window, "setTimeout");
				destroy();
				destroy = undefined;
				const cleanup = setTimeout.mock.calls.find(([, delay]) => delay === 24)?.[0];
				expect(cleanup).toBeTypeOf("function");
				if (typeof cleanup !== "function") throw new Error("Missing delayed cleanup");
				vi.clearAllTimers();
				vi.stubGlobal(
					"document",
					scenario === "unavailable" ? undefined : replacementDocument
				);

				expect(() => cleanup()).not.toThrow();
				expect(originalDocument.body.getAttribute("style")).toBe(initialStyle);
				expect(originalDocument.body.style.getPropertyValue("--scrollbar-width")).toBe("");
				expect(replacementDocument.body.getAttribute("style")).toBe(replacementStyle);
			} finally {
				vi.unstubAllGlobals();
				destroy?.();
				vi.clearAllTimers();
				vi.restoreAllMocks();
				vi.useRealTimers();
				if (originalStyle === null) originalDocument.body.removeAttribute("style");
				else originalDocument.body.setAttribute("style", originalStyle);
			}
		}
	);

	async function withScrollLock(
		testFn: (helpers: { unlock: () => void }) => void | Promise<void>,
		options?: { setup?: () => void }
	) {
		const originalStyle = document.body.getAttribute("style");
		let destroy: (() => void) | undefined;

		try {
			options?.setup?.();

			vi.useFakeTimers();
			const setTimeout = vi.spyOn(window, "setTimeout");

			destroy = $effect.root(() => {
				new BodyScrollLock(true);
			});
			flushSync();
			await tick();

			const unlock = () => {
				if (!destroy) return;

				destroy();
				destroy = undefined;

				const cleanup = setTimeout.mock.calls.find(([, delay]) => delay === 24)?.[0];
				expect(cleanup).toBeTypeOf("function");
				cleanup?.();
			};

			await testFn({ unlock });
		} finally {
			destroy?.();
			vi.clearAllTimers();
			vi.restoreAllMocks();
			vi.useRealTimers();
			if (originalStyle === null) document.body.removeAttribute("style");
			else document.body.setAttribute("style", originalStyle);
		}
	}

	it("preserves unrelated body styles added while the scroll lock is active", async () => {
		await withScrollLock(({ unlock }) => {
			expect(document.body.style.overflow).toBe("hidden");

			// An external component (e.g. toast, theme, modal) mutates body styles while lock is active:
			document.body.style.setProperty("--app-toast-offset", "48px");
			document.body.style.backgroundColor = "blue";

			unlock();

			expect(document.body.style.overflow).toBe("");
			expect(document.body.style.getPropertyValue("--app-toast-offset")).toBe("48px");
			expect(document.body.style.backgroundColor).toBe("blue");
		});
	});

	it("restores body styles without relying on setAttribute('style')", async () => {
		const originalSetAttribute = document.body.setAttribute.bind(document.body);
		vi.spyOn(document.body, "setAttribute").mockImplementation((name, value) => {
			// Simulates environments where style attribute mutation is blocked,
			// such as Chromium with a restrictive style-src-attr CSP.
			if (name === "style") return;
			originalSetAttribute(name, value);
		});

		await withScrollLock(({ unlock }) => {
			expect(document.body.style.overflow).toBe("hidden");

			unlock();

			// If cleanup relies solely on setAttribute("style"), this will fail because setAttribute was blocked
			expect(document.body.style.overflow).toBe("");
			expect(document.body.style.pointerEvents).toBe("");
		});
	});

	it("does not restore lock properties that were not modified by the lock", async () => {
		// Simulate an environment with no scrollbar to compensate (verticalScrollbarWidth === 0)
		vi.spyOn(window, "innerWidth", "get").mockReturnValue(document.documentElement.clientWidth);

		await withScrollLock(({ unlock }) => {
			expect(document.body.style.overflow).toBe("hidden");

			// When scrollbar compensation is not active (e.g. verticalScrollbarWidth === 0),
			// Bits UI does not modify padding-right or margin-right.
			// An external component mutates padding-right while the lock is active:
			document.body.style.paddingRight = "24px";

			unlock();

			// Overflow should be reset:
			expect(document.body.style.overflow).toBe("");
			// But paddingRight was never modified by the lock, so it must not be rolled back:
			expect(document.body.style.paddingRight).toBe("24px");
		});
	});

	it("preserves style priority (!important) when restoring", async () => {
		await withScrollLock(
			({ unlock }) => {
				expect(document.body.style.overflow).toBe("hidden");

				unlock();

				expect(document.body.style.getPropertyValue("overflow")).toBe("auto");
				expect(document.body.style.getPropertyPriority("overflow")).toBe("important");
			},
			{
				setup: () => {
					document.body.style.setProperty("overflow", "auto", "important");
					expect(document.body.style.getPropertyPriority("overflow")).toBe("important");
				},
			}
		);
	});
});

