	],
});

type GetDefaultYearsProps = {
	placeholderYear: number;
	minValue: DateValue | undefined;
	maxValue: DateValue | undefined;
};

export function getDefaultYears(opts: GetDefaultYearsProps) {
	const currentYear = new Date().getFullYear();
	const latestYear = Math.max(opts.placeholderYear, currentYear);

	// use minValue/maxValue as boundaries if provided, otherwise calculate default range
	let minYear: number;
	let maxYear: number;

	if (opts.minValue) {
		minYear = opts.minValue.year;
	} else {
		// (111 years: latestYear - 100 to latestYear + 10)
		const initialMinYear = latestYear - 100;
		minYear =
			opts.placeholderYear < initialMinYear ? opts.placeholderYear - 10 : initialMinYear;
	}

	if (opts.maxValue) {
		maxYear = opts.maxValue.year;
	} else {
		maxYear = latestYear + 10;
	}

	// ensure we have at least one year and minYear <= maxYear
	if (minYear > maxYear) {
		minYear = maxYear;
	}

	const totalYears = maxYear - minYear + 1;
	return Array.from({ length: totalYears }, (_, i) => minYear + i);
}

import { describe, expect, it } from "vitest";
import { CalendarDate, CalendarDateTime } from "@internationalized/date";
import { getValueFromSegments } from "./helpers.js";
import type { SegmentValueObj } from "./types.js";

/**
 * Builds a field node whose segments appear in the given order, mimicking the
 * order the segments are rendered in for a given locale.
 */
function createFieldNode(parts: string[]) {
	const field = document.createElement("div");
	for (const part of parts) {
		const segment = document.createElement("div");
		segment.dataset.segment = part;
		field.appendChild(segment);
	}
	return field;
}

describe("getValueFromSegments", () => {
	it("applies the day-first (en-GB) segment order without clamping the day to the dateRef's month", () => {
		const fieldNode = createFieldNode(["day", "literal", "month", "literal", "year"]);
		const segmentObj = { day: "31", month: "08", year: "2026" } as SegmentValueObj;

		// the placeholder/dateRef sits in a 30-day month (November)
		const value = getValueFromSegments({
			segmentObj,
			fieldNode,
			dateRef: new CalendarDate(2024, 11, 1),
		});

		expect(value.toString()).toBe("2026-08-31");
	});

	it("applies the month-first (en-US) segment order", () => {
		const fieldNode = createFieldNode(["month", "literal", "day", "literal", "year"]);
		const segmentObj = { day: "31", month: "08", year: "2026" } as SegmentValueObj;

		const value = getValueFromSegments({
			segmentObj,
			fieldNode,
			dateRef: new CalendarDate(2024, 11, 1),
		});

		expect(value.toString()).toBe("2026-08-31");
	});

	it("resolves february 29th against the entered year and not the dateRef's year", () => {
		const fieldNode = createFieldNode(["day", "literal", "month", "literal", "year"]);
		const segmentObj = { day: "29", month: "02", year: "2024" } as SegmentValueObj;

		const value = getValueFromSegments({
			segmentObj,
			fieldNode,
			dateRef: new CalendarDate(2025, 2, 1),
		});

		expect(value.toString()).toBe("2024-02-29");
	});

	it("keeps the time segments when the field has a time granularity", () => {
		const fieldNode = createFieldNode([
			"day",
			"literal",
			"month",
			"literal",
			"year",
			"hour",
			"literal",
			"minute",
			"dayPeriod",
		]);
		const segmentObj = {
			day: "31",
			month: "08",
			year: "2026",
			hour: "13",
			minute: "45",
			second: null,
			dayPeriod: "PM",
		} as unknown as SegmentValueObj;

		const value = getValueFromSegments({
			segmentObj,
			fieldNode,
			dateRef: new CalendarDateTime(2024, 11, 1, 0, 0),
		});

		expect(value.toString()).toBe("2026-08-31T13:45:00");
	});

	it("ignores segments that have not been filled in yet", () => {
		const fieldNode = createFieldNode(["day", "literal", "month", "literal", "year"]);
		const segmentObj = { day: "15", month: null, year: null } as unknown as SegmentValueObj;

		const value = getValueFromSegments({
			segmentObj,
			fieldNode,
			dateRef: new CalendarDate(2024, 11, 1),
		});

		expect(value.toString()).toBe("2024-11-15");
	});
});

import type { DateValue } from "@internationalized/date";
import { styleToString } from "svelte-toolbelt";
import type { Formatter } from "../formatter.js";
import { getPlaceholder } from "../placeholders.js";
import { hasTime, isZonedDateTime } from "../utils.js";
import type {
	DateAndTimeSegmentObj,
	DateSegmentPart,
	EditableSegmentPart,
	SegmentContentObj,
	SegmentPart,
	SegmentStateMap,
	SegmentValueObj,
	TimeSegmentPart,
} from "./types.js";
import {
	ALL_SEGMENT_PARTS,
	DATE_SEGMENT_PARTS,
	EDITABLE_SEGMENT_PARTS,
	EDITABLE_TIME_SEGMENT_PARTS,
} from "./parts.js";
import { getSegments } from "./segments.js";
import { isBrowser, isNull, isNumberString } from "$lib/internal/is.js";
import { useId } from "$lib/internal/use-id.js";
import { kbd } from "$lib/internal/kbd.js";
import type { Granularity, HourCycle } from "$lib/shared/date/types.js";

export function initializeSegmentValues(granularity: Granularity) {
	const calendarDateTimeGranularities = ["hour", "minute", "second"];
	const initialParts = EDITABLE_SEGMENT_PARTS.map((part) => {
		if (part === "dayPeriod") {
			return [part, "AM"];
		}
		return [part, null];
	}).filter(([key]) => {
		if (key === "literal" || key === null) return false;
		if (granularity === "day") {
			return !calendarDateTimeGranularities.includes(key!);
		} else {
			return true;
		}
	});
	return Object.fromEntries(initialParts) as SegmentValueObj;
}

type SharedContentProps = {
	granularity: Granularity;
	dateRef: DateValue;
	formatter: Formatter;
	hideTimeZone: boolean;
	hourCycle: HourCycle | undefined;
};

type CreateContentObjProps = SharedContentProps & {
	segmentValues: SegmentValueObj;
	locale: string;
};

type CreateContentArrProps = SharedContentProps & {
	contentObj: SegmentContentObj;
};

function createContentObj(props: CreateContentObjProps) {
	const { segmentValues, formatter, locale, dateRef } = props;

	const content = Object.keys(segmentValues).reduce((obj, part) => {
		if (!isSegmentPart(part)) return obj;
		if ("hour" in segmentValues && part === "dayPeriod") {
			const value = segmentValues[part];
			if (!isNull(value)) {
				obj[part] = value;
			} else {
				obj[part] = getPlaceholder(part, "AM", locale);
			}
		} else {
			obj[part] = getPartContent(part);
		}

		return obj;
	}, {} as SegmentContentObj);

	function getPartContent(part: DateSegmentPart | TimeSegmentPart) {
		if ("hour" in segmentValues) {
			const value = segmentValues[part];
			const leadingZero = typeof value === "string" && value?.startsWith("0");
			const intValue = value !== null ? Number.parseInt(value) : null;

			if (value === "0" && part !== "year") {
				return "0";
			} else if (!isNull(value) && !isNull(intValue)) {
				const formatted = formatter.part(dateRef.set({ [part]: value }), part, {
					hourCycle: props.hourCycle === 24 ? "h23" : undefined,
				});

				/**
				 * If we're operating in a 12 hour clock and the part is an hour, we handle
				 * the conversion to 12 hour format with 2 digit hours and leading zeros here.
				 */
				const is12HourMode =
					props.hourCycle === 12 ||
					(props.hourCycle === undefined && getDefaultHourCycle(locale) === 12);
				if (part === "hour" && is12HourMode) {
					/**
					 * If the value is over 12, we convert to 12 hour format and add leading
					 * zeroes if the value is less than 10.
					 */
					if (intValue > 12) {
						const hour = intValue - 12;
						if (hour === 0) {
							return "12";
						} else if (hour < 10) {
							return `0${hour}`;
						} else {
							return `${hour}`;
						}
					}

					/**
					 * If the value is 0, we convert to 12, since 0 is not a valid 12 hour time.
					 */
					if (intValue === 0) {
						return "12";
					}

					/**
					 * If the value is less than 10, we add a leading zero to the value.
					 */
					if (intValue < 10) {
						return `0${intValue}`;
					}

					/**
					 * Otherwise, we don't need to do anything to the value.
					 */
					return `${intValue}`;
				}

				if (part === "year") {
					return `${value}`;
				}

				if (leadingZero && formatted.length === 1) {
					return `0${formatted}`;
				}
				return formatted;
			} else {
				return getPlaceholder(part, "", locale);
			}
		} else {
			if (isDateSegmentPart(part)) {
				const value = segmentValues[part];
				const leadingZero = typeof value === "string" && value?.startsWith("0");
				if (value === "0") {
					return "0";
				} else if (!isNull(value)) {
					const formatted = formatter.part(dateRef.set({ [part]: value }), part);
					if (part === "year") {
						return `${value}`;
					}
					if (leadingZero && formatted.length === 1) {
						return `0${formatted}`;
					}
					return formatted;
				} else {
					return getPlaceholder(part, "", locale);
				}
			}
			return "";
		}
	}

	return content;
}

function createContentArr(props: CreateContentArrProps) {
	const { granularity, dateRef, formatter, contentObj, hideTimeZone, hourCycle } = props;
	const parts = formatter.toParts(dateRef, getOptsByGranularity(granularity, hourCycle));
	const segmentContentArr = parts
		.map((part) => {
			const defaultParts = ["literal", "dayPeriod", "timeZoneName", null];

			if (defaultParts.includes(part.type) || !isSegmentPart(part.type)) {
				return {
					part: part.type,
					value: part.value,
				};
			}
			return {
				part: part.type,
				value: contentObj[part.type],
			};
		})
		.filter((segment): segment is { part: SegmentPart; value: string } => {
			if (isNull(segment.part) || isNull(segment.value)) return false;
			if (segment.part === "timeZoneName" && (!isZonedDateTime(dateRef) || hideTimeZone)) {
				return false;
			}
			return true;
		});
	return segmentContentArr;
}

type CreateContentProps = CreateContentObjProps;

export function createContent(props: CreateContentProps) {
	const contentObj = createContentObj(props);
	const contentArr = createContentArr({
		contentObj,
		...props,
	});
	return {
		obj: contentObj,
		arr: contentArr,
	};
}

function getOptsByGranularity(granularity: Granularity, hourCycle: HourCycle | undefined) {
	const opts: Intl.DateTimeFormatOptions = {
		year: "numeric",
		month: "2-digit",
		day: "2-digit",
		hour: "2-digit",
		minute: "2-digit",
		second: "2-digit",
		timeZoneName: "short",
		hourCycle: hourCycle === 24 ? "h23" : undefined,
		hour12: hourCycle === 24 ? false : undefined,
	};

	if (granularity === "day") {
		delete opts.second;
		delete opts.hour;
		delete opts.minute;
		delete opts.timeZoneName;
	}
	if (granularity === "hour") {
		delete opts.minute;
	}
	if (granularity === "minute") {
		delete opts.second;
	}

	return opts;
}

export function initSegmentStates() {
	return EDITABLE_SEGMENT_PARTS.reduce((acc, key) => {
		acc[key] = {
			lastKeyZero: false,
			hasLeftFocus: true,
			updating: null,
		};
		return acc;
	}, {} as SegmentStateMap);
}

export function initSegmentIds() {
	return Object.fromEntries(
		ALL_SEGMENT_PARTS.map((part) => {
			return [part, useId()];
		}).filter(([key]) => key !== "literal")
	);
}

export function isDateSegmentPart(part: unknown): part is DateSegmentPart {
	return DATE_SEGMENT_PARTS.includes(part as DateSegmentPart);
}

export function isSegmentPart(part: string): part is EditableSegmentPart {
	return EDITABLE_SEGMENT_PARTS.includes(part as EditableSegmentPart);
}

export function isAnySegmentPart(part: unknown): part is SegmentPart {
	return ALL_SEGMENT_PARTS.includes(part as EditableSegmentPart);
}

/**
 * Get the segments being used/ are rendered in the DOM.
 * We're using this to determine when to set the value of
 * the date picker, which is when all the segments have
 * been filled.
 */
function getUsedSegments(fieldNode: HTMLElement | null) {
	if (!isBrowser || !fieldNode) return [];
	const usedSegments = getSegments(fieldNode)
		.map((el) => el.dataset.segment)
		.filter((part): part is EditableSegmentPart => {
			return EDITABLE_SEGMENT_PARTS.includes(part as EditableSegmentPart);
		});
	return usedSegments;
}

type GetValueFromSegments = {
	segmentObj: SegmentValueObj;
	fieldNode: HTMLElement | null;
	dateRef: DateValue;
};

/**
 * The order the segments are applied in when building a date from them.
 *
 * Setting a part on a `DateValue` constrains the result immediately, so the day
 * has to be applied after the year and month it belongs to. Applying it in the
 * order the segments are displayed clamps the day to the number of days in the
 * `dateRef`'s month in day-first locales (e.g. `31/08` entered in `en-GB` with a
 * `dateRef` in November would resolve to the 30th).
 */
const SEGMENT_APPLY_ORDER = ["year", "month", "day", "hour", "minute", "second", "dayPeriod"];

function getSegmentApplyOrder(part: EditableSegmentPart) {
	const index = SEGMENT_APPLY_ORDER.indexOf(part);
	return index === -1 ? SEGMENT_APPLY_ORDER.length : index;
}

export function getValueFromSegments(props: GetValueFromSegments) {
	const { segmentObj, fieldNode, dateRef } = props;
	const usedSegments = getUsedSegments(fieldNode).sort(
		(a, b) => getSegmentApplyOrder(a) - getSegmentApplyOrder(b)
	);
	let date = dateRef;

	for (const part of usedSegments) {
		if ("hour" in segmentObj) {
			const value = segmentObj[part];
			if (isNull(value)) continue;
			date = date.set({ [part]: segmentObj[part] });
		} else if (isDateSegmentPart(part)) {
			const value = segmentObj[part];
			if (isNull(value)) continue;
			date = date.set({ [part]: segmentObj[part] });
		}
	}

	return date;
}

/**
 * Check if all the segments being used have been filled.
 * We use this to determine when we should set the value
 * store of the date field(s).
 *
 * @param segmentValues - The current `SegmentValueObj`
 * @param fieldNode  - The id of the date field
 */
export function areAllSegmentsFilled(
	segmentValues: SegmentValueObj,
	fieldNode: HTMLElement | null
) {
	const usedSegments = getUsedSegments(fieldNode);
	for (const part of usedSegments) {
		if ("hour" in segmentValues) {
			if (segmentValues[part] === null) {
				return false;
			}
		} else if (isDateSegmentPart(part)) {
			if (segmentValues[part] === null) {
				return false;
			}
		}
	}
	return true;
}

/**
 * Determines if the provided object is a valid `DateAndTimeSegmentObj`
 * by checking if it has the correct keys and values for each key.
 */
export function isDateAndTimeSegmentObj(obj: unknown): obj is DateAndTimeSegmentObj {
	if (typeof obj !== "object" || obj === null) {
		return false;
	}
	return Object.entries(obj).every(([key, value]) => {
		const validKey =
			EDITABLE_TIME_SEGMENT_PARTS.includes(key as TimeSegmentPart) ||
			DATE_SEGMENT_PARTS.includes(key as DateSegmentPart);

		const validValue =
			key === "dayPeriod"
				? value === "AM" || value === "PM" || value === null
				: typeof value === "string" || typeof value === "number" || value === null;

		return validKey && validValue;
	});
}

/**
 * Infer the granularity to use based on the
 * value and granularity props.
 */
export function inferGranularity(
	value: DateValue,
	granularity: Granularity | undefined
): Granularity {
	if (granularity) return granularity;
	if (hasTime(value)) return "minute";
	return "day";
}

export function isAcceptableSegmentKey(key: string) {
	const acceptableSegmentKeys = [
		kbd.ENTER,
		kbd.ARROW_UP,
		kbd.ARROW_DOWN,
		kbd.ARROW_LEFT,
		kbd.ARROW_RIGHT,
		kbd.BACKSPACE,
		kbd.SPACE,
	];
	if (acceptableSegmentKeys.includes(key)) return true;
	if (isNumberString(key)) return true;
	return false;
}

/**
 * Determines if the element with the provided id is the first focusable
 * segment in the date field with the provided fieldId.
 *
 * @param id - The id of the element to check if it's the first segment
 * @param fieldNode - The id of the date field associated with the segment
 */
export function isFirstSegment(id: string, fieldNode: HTMLElement | null) {
	if (!isBrowser) return false;
	const segments = getSegments(fieldNode);
	return segments.length ? segments[0]!.id === id : false;
}

type SetDescriptionProps = {
	id: string;
	formatter: Formatter;
	value: DateValue;
	doc: Document;
};
/**
 * Creates or updates a description element for a date field
 * which enables screen readers to read the date field's value.
 *
 * This element is hidden from view, and is portalled to the body
 * so it can be associated via `aria-describedby` and read by
 * screen readers as the user interacts with the date field.
 */
export function setDescription(props: SetDescriptionProps) {
	const { id, formatter, value, doc } = props;
	if (!isBrowser) return;
	const valueString = formatter.selectedDate(value);
	const el = doc.getElementById(id);
	if (!el) {
		const div = doc.createElement("div");
		div.style.cssText = styleToString({
			display: "none",
		});
		div.id = id;
		div.innerText = `Selected Date: ${valueString}`;
		doc.body.appendChild(div);
	} else {
		el.innerText = `Selected Date: ${valueString}`;
	}
}

/**
 * Removes the description element for the date field with
 * the provided ID. This function should be called when the
 * date field is unmounted.
 */
export function removeDescriptionElement(id: string, doc: Document) {
	if (!isBrowser) return;
	const el = doc.getElementById(id);
	if (!el) return;
	doc.body.removeChild(el);
}

export function getDefaultHourCycle(locale: string): 12 | 24 {
	const formatter = new Intl.DateTimeFormat(locale, { hour: "numeric" });
	const parts = formatter.formatToParts(new Date("2023-01-01T13:00:00"));
	const hourPart = parts.find((part) => part.type === "hour");

	return hourPart?.value === "1" ? 12 : 24;
}

export const DATE_SEGMENT_PARTS = ["day", "month", "year"] as const;
export const EDITABLE_TIME_SEGMENT_PARTS = ["hour", "minute", "second", "dayPeriod"] as const;
export const NON_EDITABLE_SEGMENT_PARTS = ["literal", "timeZoneName"] as const;
export const EDITABLE_SEGMENT_PARTS = [
	...DATE_SEGMENT_PARTS,
	...EDITABLE_TIME_SEGMENT_PARTS,
] as const;
export const ALL_SEGMENT_PARTS = [
	...EDITABLE_SEGMENT_PARTS,
	...NON_EDITABLE_SEGMENT_PARTS,
] as const;
export const ALL_TIME_SEGMENT_PARTS = [
	...EDITABLE_TIME_SEGMENT_PARTS,
	...NON_EDITABLE_SEGMENT_PARTS,
] as const;

export const ALL_EXCEPT_LITERAL_PARTS = ALL_SEGMENT_PARTS.filter((part) => part !== "literal");
export const ALL_TIME_EXCEPT_LITERAL_PARTS = ALL_TIME_SEGMENT_PARTS.filter(
	(part) => part !== "literal"
);

import { isAnySegmentPart } from "./helpers.js";
import { isHTMLElement } from "$lib/internal/is.js";
import { kbd } from "$lib/internal/kbd.js";

/**
 * Handles segment navigation based on the provided keyboard event and field ID.
 *
 * @param e - The keyboard event
 * @param fieldNode - The ID of the field we're navigating within
 */
export function handleSegmentNavigation(e: KeyboardEvent, fieldNode: HTMLElement | null) {
	const currentTarget = e.currentTarget;
	if (!isHTMLElement(currentTarget)) return;

	const { prev, next } = getPrevNextSegments(currentTarget, fieldNode);

	if (e.key === kbd.ARROW_LEFT) {
		if (!prev) return;
		prev.focus();
	} else if (e.key === kbd.ARROW_RIGHT) {
		if (!next) return;
		next.focus();
	}
}

export function handleTimeSegmentNavigation(e: KeyboardEvent, fieldNode: HTMLElement | null) {
	const currentTarget = e.currentTarget;
	if (!isHTMLElement(currentTarget)) return;

	const { prev, next } = getPrevNextTimeSegments(currentTarget, fieldNode);

	if (e.key === kbd.ARROW_LEFT) {
		if (!prev) return;
		prev.focus();
	} else if (e.key === kbd.ARROW_RIGHT) {
		if (!next) return;
		next.focus();
	}
}

/**
 * Retrieves the next segment in the list of segments relative to the provided node.
 *
 * @param node - The node we're starting from
 * @param segments - The list of candidate segments to navigate through
 */
export function getNextSegment(node: HTMLElement, segments: HTMLElement[]) {
	const index = segments.indexOf(node);
	if (index === segments.length - 1 || index === -1) return null;
	const nextIndex = index + 1;
	const nextSegment = segments[nextIndex];
	return nextSegment;
}

/**
 * Retrieves the previous segment in the list of segments relative to the provided node.
 *
 * @param node - The node we're starting from
 * @param segments - The list of candidate segments to navigate through
 */
export function getPrevSegment(node: HTMLElement, segments: HTMLElement[]) {
	const index = segments.indexOf(node);
	if (index === 0 || index === -1) return null;
	const prevIndex = index - 1;
	const prevSegment = segments[prevIndex];
	return prevSegment;
}

/**
 * Retrieves an object containing the next and previous segments relative to the current node.
 *
 * @param startingNode - The node we're starting from
 * @param fieldNode - The ID of the field we're navigating within
 */
export function getPrevNextSegments(startingNode: HTMLElement, fieldNode: HTMLElement | null) {
	const segments = getSegments(fieldNode);
	if (!segments.length) {
		return {
			next: null,
			prev: null,
		};
	}
	return {
		next: getNextSegment(startingNode, segments),
		prev: getPrevSegment(startingNode, segments),
	};
}

export function getPrevNextTimeSegments(startingNode: HTMLElement, fieldNode: HTMLElement | null) {
	const segments = getTimeSegments(fieldNode);
	if (!segments.length) {
		return {
			next: null,
			prev: null,
		};
	}
	return {
		next: getNextSegment(startingNode, segments),
		prev: getPrevSegment(startingNode, segments),
	};
}

/**
 * Shifts the focus to the next segment in the list of segments
 * within the field identified by the provided ID.
 */
export function moveToNextSegment(e: KeyboardEvent, fieldNode: HTMLElement | null) {
	const node = e.currentTarget;
	if (!isHTMLElement(node)) return;
	const { next } = getPrevNextSegments(node, fieldNode);
	if (!next) return;
	next.focus();
}

export function moveToNextTimeSegment(e: KeyboardEvent, fieldNode: HTMLElement | null) {
	const node = e.currentTarget;
	if (!isHTMLElement(node)) return;
	const { next } = getPrevNextTimeSegments(node, fieldNode);
	if (!next) return;
	next.focus();
}

export function moveToPrevTimeSegment(e: KeyboardEvent, fieldNode: HTMLElement | null) {
	const node = e.currentTarget;
	if (!isHTMLElement(node)) return;
	const { prev } = getPrevNextTimeSegments(node, fieldNode);
	if (!prev) return;
	prev.focus();
}

/**
 * Shifts the focus to the previous segment in the list of segments
 * within the field identified by the provided ID. If this is the first
 * segment, focus will not be shifted.
 */
export function moveToPrevSegment(e: KeyboardEvent, fieldNode: HTMLElement | null) {
	const node = e.currentTarget;
	if (!isHTMLElement(node)) return;
	const { prev } = getPrevNextSegments(node, fieldNode);
	if (!prev) return;
	prev.focus();
}

export function isSegmentNavigationKey(key: string) {
	if (key === kbd.ARROW_RIGHT || key === kbd.ARROW_LEFT) return true;
	return false;
}

/**
 * Retrieves all the interactive segments within the field identified by the provided ID.
 */
export function getSegments(fieldNode: HTMLElement | null) {
	if (!fieldNode) return [];
	const segments = Array.from(fieldNode.querySelectorAll("[data-segment]")).filter(
		(el): el is HTMLElement => {
			if (!isHTMLElement(el)) return false;
			const segment = el.dataset.segment;
			if (segment === "trigger") return true;
			if (!isAnySegmentPart(segment) || segment === "literal") return false;
			return true;
		}
	);
	return segments;
}

export function getTimeSegments(fieldNode: HTMLElement | null) {
	if (!fieldNode) return [];
	const segments = Array.from(fieldNode.querySelectorAll("[data-segment]")).filter(
		(el): el is HTMLElement => {
			if (!isHTMLElement(el)) return false;
			const segment = el.dataset.segment;
			if (segment === "trigger") return true;
			if (segment === "literal") return false;
			return true;
		}
	);
	return segments;
}

export function getFirstTimeSegment(fieldNode: HTMLElement | null) {
	return getTimeSegments(fieldNode)[0];
}

/**
 * Get the first interactive segment within the field identified by the provided ID.
 */
export function getFirstSegment(fieldNode: HTMLElement | null) {
	return getSegments(fieldNode)[0];
}

import { isBrowser, isNull } from "$lib/internal/is.js";
