	scn: { year: "aaaa", month: "mm", day: "jj" },
	sk: { year: "rrrr", month: "mm", day: "dd" },
	sl: { year: "llll", month: "mm", day: "dd" },
	sr: { year: "гггг", month: "мм", day: "дд" },
	sv: { year: "åååå", month: "mm", day: "dd" },
	szl: { year: "rrrr", month: "mm", day: "dd" },
	tg: { year: "сссс", month: "мм", day: "рр" },
	th: { year: "ปปปป", month: "ดด", day: "วว" },
	tr: { year: "yyyy", month: "aa", day: "gg" },
	uk: { year: "рррр", month: "мм", day: "дд" },
	"zh-CN": { year: "年", month: "月", day: "日" },
	"zh-TW": { year: "年", month: "月", day: "日" },
};

function getPlaceholderObj(locale: SupportedLocale | (string & {})) {
	if (!isSupportedLocale(locale)) {
		const localeLanguage = getLocaleLanguage(locale);
		if (!isSupportedLocale(localeLanguage)) {
			return placeholders.en;
		} else {
			return placeholders[localeLanguage];
		}
	} else {
		return placeholders[locale];
	}
}

type Field = "era" | "year" | "month" | "day" | "hour" | "minute" | "second" | "dayPeriod";

export function getPlaceholder(
	field: Field,
	value: string,
	locale: SupportedLocale | (string & {})
) {
	if (isPlaceholderField(field)) return getPlaceholderObj(locale)[field];
	if (isDefaultField(field)) return value;
	if (isTimeField(field)) return "––";
	return "";
}

function isSupportedLocale(locale: string): locale is SupportedLocale {
	return supportedLocales.includes(locale as SupportedLocale);
}

function isPlaceholderField(field: unknown): field is PlaceholderField {
	return placeholderFields.includes(field as PlaceholderField);
}

function isTimeField(field: unknown): field is "hour" | "minute" | "second" {
	return field === "hour" || field === "minute" || field === "second";
}

function isDefaultField(field: unknown): field is "era" | "dayPeriod" {
	return field === "era" || field === "dayPeriod";
}

function getLocaleLanguage(locale: string) {
	if (Intl.Locale) {
		return new Intl.Locale(locale).language;
	}
	return locale.split("-")[0]!;
}

import {
	CalendarDate,
	CalendarDateTime,
	type DateValue,
	Time,
	ZonedDateTime,
	getDayOfWeek,
	getLocalTimeZone,
	parseDate,
	parseDateTime,
	parseZonedDateTime,
	toCalendar,
} from "@internationalized/date";
import type {
	DateMatcher,
	Granularity,
	TimeGranularity,
	TimeValue,
} from "$lib/shared/date/types.js";

type GetDefaultDateProps = {
	defaultValue?: DateValue | DateValue[] | undefined;
	minValue?: DateValue;
	maxValue?: DateValue;
	granularity?: Granularity;
};

type GetDefaultTimeProps = {
	defaultValue?: TimeValue | undefined;
	granularity?: TimeGranularity;
};

const defaultDateDefaults = {
	defaultValue: undefined,
	granularity: "day",
};

const defaultTimeDefaults = {
	defaultValue: undefined,
	granularity: "minute",
};

/**
 * A helper function used throughout the various date builders
 * to generate a default `DateValue` using the `defaultValue`,
 * `defaultPlaceholder`, `minValue`, `maxValue`, and `granularity` props.
 *
 * It's important to match the `DateValue` type being used
 * elsewhere in the builder, so they behave according to the
 * behavior the user expects based on the props they've provided.
 *
 */
export function getDefaultDate(opts: GetDefaultDateProps): DateValue {
	const withDefaults = { ...defaultDateDefaults, ...opts };
	const { defaultValue, granularity, minValue, maxValue } = withDefaults;

	if (Array.isArray(defaultValue) && defaultValue.length) {
		return defaultValue[defaultValue.length - 1]!;
	}

	if (defaultValue && !Array.isArray(defaultValue)) {
		return defaultValue;
	} else {
		let date = new Date();
		if (minValue && date < minValue.toDate(getLocalTimeZone())) {
			date = minValue.toDate(getLocalTimeZone());
		} else if (maxValue && date > maxValue.toDate(getLocalTimeZone())) {
			date = maxValue.toDate(getLocalTimeZone());
		}
		const year = date.getFullYear();
		const month = date.getMonth() + 1;
		const day = date.getDate();
		const calendarDateTimeGranularities = ["hour", "minute", "second"];

		if (calendarDateTimeGranularities.includes(granularity ?? "day")) {
			return new CalendarDateTime(year, month, day, 0, 0, 0);
		}

		return new CalendarDate(year, month, day);
	}
}

export function getDefaultTime(opts: GetDefaultTimeProps): TimeValue {
	const withDefaults = { ...defaultTimeDefaults, ...opts };
	const { defaultValue } = withDefaults;

	if (defaultValue) {
		return defaultValue;
	} else {
		return new Time(0, 0, 0);
	}
}

/**
 * Given a date string and a reference `DateValue` object, parse the
 * string to the same type as the reference object.
 *
 * Useful for parsing strings from data attributes, which are always
 * strings, to the same type being used by the date component.
 */
export function parseStringToDateValue(dateStr: string, referenceVal: DateValue): DateValue {
	let dateValue: DateValue;
	if (referenceVal instanceof ZonedDateTime) {
		dateValue = parseZonedDateTime(dateStr);
	} else if (referenceVal instanceof CalendarDateTime) {
		dateValue = parseDateTime(dateStr);
	} else {
		dateValue = parseDate(dateStr);
	}

	// ensure the parsed date is in the same calendar as the reference date set by the user.
	return dateValue.calendar !== referenceVal.calendar
		? toCalendar(dateValue, referenceVal.calendar)
		: dateValue;
}

/**
 * Given a `DateValue` object, convert it to a native `Date` object.
 * If a timezone is provided, the date will be converted to that timezone.
 * If no timezone is provided, the date will be converted to the local timezone.
 */
export function toDate(dateValue: DateValue, tz: string = getLocalTimeZone()) {
	if (dateValue instanceof ZonedDateTime) {
		return dateValue.toDate();
	} else {
		return dateValue.toDate(tz);
	}
}

export function getDateValueType(date: DateValue): string {
	if (date instanceof CalendarDate) return "date";
	if (date instanceof CalendarDateTime) return "datetime";
	if (date instanceof ZonedDateTime) return "zoneddatetime";
	throw new Error("Unknown date type");
}

export function parseAnyDateValue(value: string, type: string): DateValue {
	switch (type) {
		case "date":
			return parseDate(value);
		case "datetime":
			return parseDateTime(value);
		case "zoneddatetime":
			return parseZonedDateTime(value);
		default:
			throw new Error(`Unknown date type: ${type}`);
	}
}

function isCalendarDateTime(dateValue: DateValue): dateValue is CalendarDateTime {
	return dateValue instanceof CalendarDateTime;
}

export function isZonedDateTime(dateValue: DateValue | TimeValue): dateValue is ZonedDateTime {
	return dateValue instanceof ZonedDateTime;
}

export function hasTime(dateValue: DateValue): dateValue is CalendarDateTime | ZonedDateTime {
	return isCalendarDateTime(dateValue) || isZonedDateTime(dateValue);
}

/**
 * Given a date, return the number of days in the month.
 */
export function getDaysInMonth(date: Date | DateValue) {
	if (date instanceof Date) {
		const year = date.getFullYear();
		const month = date.getMonth() + 1;
		/**
		 * By using zero as the day, we get the
		 * last day of the previous month, which
		 * is the month we originally passed in.
		 */
		return new Date(year, month, 0).getDate();
	} else {
		return date.set({ day: 100 }).day;
	}
}

/**
 * Determine if a date is before the reference date.
 * @param dateToCompare - is this date before the `referenceDate`
 * @param referenceDate - is the `dateToCompare` before this date
 *
 * @see {@link isBeforeOrSame} for inclusive
 */
export function isBefore(dateToCompare: DateValue, referenceDate: DateValue) {
	return dateToCompare.compare(referenceDate) < 0;
}

/**
 * Determine if a date is after the reference date.
 * @param dateToCompare - is this date after the `referenceDate`
 * @param referenceDate - is the `dateToCompare` after this date
 *
 * @see {@link isAfterOrSame} for inclusive
 */
export function isAfter(dateToCompare: DateValue, referenceDate: DateValue) {
	return dateToCompare.compare(referenceDate) > 0;
}

/**
 * Determine if a date is before or the same as the reference date.
 *
 * @param dateToCompare - the date to compare
 * @param referenceDate - the reference date to make the comparison against
 *
 * @see {@link isBefore} for non-inclusive
 */
function isBeforeOrSame(dateToCompare: DateValue, referenceDate: DateValue) {
	return dateToCompare.compare(referenceDate) <= 0;
}

/**
 * Determine if a date is after or the same as the reference date.
 *
 * @param dateToCompare - is this date after or the same as the `referenceDate`
 * @param referenceDate - is the `dateToCompare` after or the same as this date
 *
 * @see {@link isAfter} for non-inclusive
 */
function isAfterOrSame(dateToCompare: DateValue, referenceDate: DateValue) {
	return dateToCompare.compare(referenceDate) >= 0;
}

/**
 * Determine if a date is inclusively between a start and end reference date.
 *
 * @param date - is this date inclusively between the `start` and `end` dates
 * @param start - the start reference date to make the comparison against
 * @param end - the end reference date to make the comparison against
 *
 * @see {@link isBetween} for non-inclusive
 */
export function isBetweenInclusive(date: DateValue, start: DateValue, end: DateValue) {
	return isAfterOrSame(date, start) && isBeforeOrSame(date, end);
}

export function getLastFirstDayOfWeek<T extends DateValue = DateValue>(
	date: T,
	firstDayOfWeek: number,
	locale: string
): T {
	const day = getDayOfWeek(date, locale);

	if (firstDayOfWeek > day) {
		return date.subtract({ days: day + 7 - firstDayOfWeek }) as T;
	}
	if (firstDayOfWeek === day) {
		return date as T;
	}
	return date.subtract({ days: day - firstDayOfWeek }) as T;
}

export function getNextLastDayOfWeek<T extends DateValue = DateValue>(
	date: T,
	firstDayOfWeek: number,
	locale: string
): T {
	const day = getDayOfWeek(date, locale);
	const lastDayOfWeek = firstDayOfWeek === 0 ? 6 : firstDayOfWeek - 1;

	if (day === lastDayOfWeek) {
		return date as T;
	}

	if (day > lastDayOfWeek) {
		return date.add({ days: 7 - day + lastDayOfWeek }) as T;
	}

	return date.add({ days: lastDayOfWeek - day }) as T;
}

export function areAllDaysBetweenValid(
	start: DateValue,
	end: DateValue,
	isUnavailable: DateMatcher | undefined,
	isDisabled: DateMatcher | undefined
) {
	if (isUnavailable === undefined && isDisabled === undefined) {
		return true;
	}
	let dCurrent = start.add({ days: 1 });
	if (isDisabled?.(dCurrent) || isUnavailable?.(dCurrent)) {
		return false;
	}
	const dEnd = end;
	while (dCurrent.compare(dEnd) < 0) {
		dCurrent = dCurrent.add({ days: 1 });
		if (isDisabled?.(dCurrent) || isUnavailable?.(dCurrent)) {
			return false;
		}
	}
	return true;
}

import { describe, expect, it, vi } from "vitest";
import { debounce } from "./debounce.js";

describe("debounce", () => {
	it("should execute the function after the specified wait time", async () => {
		const mockFn = vi.fn();
		const debouncedFn = debounce(mockFn, 100);

		debouncedFn();
		expect(mockFn).not.toHaveBeenCalled();

		await new Promise((resolve) => setTimeout(resolve, 200));
		expect(mockFn).toHaveBeenCalledOnce();
	});

	it("should debounce multiple calls within the wait time", async () => {
		const mockFn = vi.fn();
		const debouncedFn = debounce(mockFn, 100);

		debouncedFn();
		debouncedFn();
		debouncedFn();

		await new Promise((resolve) => setTimeout(resolve, 50));
		expect(mockFn).not.toHaveBeenCalled();

		await new Promise((resolve) => setTimeout(resolve, 100));
		expect(mockFn).toHaveBeenCalledOnce();
	});

	it("should handle arguments correctly", async () => {
		const mockFn = vi.fn();
		const debouncedFn = debounce(mockFn, 100);

		debouncedFn(1, "hello", true);

		await new Promise((resolve) => setTimeout(resolve, 200));
		expect(mockFn).toHaveBeenCalledWith(1, "hello", true);
	});

	it("should reset the timer on subsequent calls", async () => {
		const mockFn = vi.fn();
		const debouncedFn = debounce(mockFn, 100);

		debouncedFn();
		await new Promise((resolve) => setTimeout(resolve, 50));
		debouncedFn();

		await new Promise((resolve) => setTimeout(resolve, 150));
		expect(mockFn).toHaveBeenCalledTimes(1);

		debouncedFn();
		await new Promise((resolve) => setTimeout(resolve, 150));
		expect(mockFn).toHaveBeenCalledTimes(2);
	});

	it("should cancel the debounced function when destroy is called", async () => {
		const mockFn = vi.fn();
		const debouncedFn = debounce(mockFn, 100);

		debouncedFn();
		debouncedFn.destroy();

		await new Promise((resolve) => setTimeout(resolve, 200));
		expect(mockFn).not.toHaveBeenCalled();
	});
});

// oxlint-disable-next-line no-explicit-any
export function debounce<T extends (...args: any[]) => any>(fn: T, wait = 500) {
	let timeout: NodeJS.Timeout | null = null;

	const debounced = (...args: Parameters<T>) => {
		if (timeout !== null) {
			clearTimeout(timeout);
		}
		timeout = setTimeout(() => {
			fn(...args);
		}, wait);
	};

	debounced.destroy = () => {
		if (timeout !== null) {
			clearTimeout(timeout);
			timeout = null;
		}
	};

	return debounced;
}

import type { WritableBox } from "svelte-toolbelt";
import { getNextMatch } from "./arrays.js";
import { boxAutoReset } from "./box-auto-reset.svelte.js";

type DOMTypeaheadOptions = {
	onMatch?: (item: HTMLElement) => void;
	getCurrentItem?: () => HTMLElement | null;
	getActiveElement: () => HTMLElement | null;
	getWindow: () => Window & typeof globalThis;
};

export class DOMTypeahead {
	readonly #opts: DOMTypeaheadOptions;
	readonly #search: WritableBox<string>;
	#onMatch: (item: HTMLElement) => void = $derived.by(() => {
		if (this.#opts.onMatch) return this.#opts.onMatch;
		return (node) => node.focus();
	});
	#getCurrentItem: () => HTMLElement | null = $derived.by(() => {
		if (this.#opts.getCurrentItem) return this.#opts.getCurrentItem;
		return this.#opts.getActiveElement;
	});

	constructor(opts: DOMTypeaheadOptions) {
		this.#opts = opts;
		this.#search = boxAutoReset("", {
			afterMs: 1000,
			getWindow: opts.getWindow,
		});

		this.handleTypeaheadSearch = this.handleTypeaheadSearch.bind(this);
		this.resetTypeahead = this.resetTypeahead.bind(this);
	}

	handleTypeaheadSearch(key: string, candidates: HTMLElement[]) {
		if (!candidates.length) return;

		this.#search.current = this.#search.current + key;
		const currentItem = this.#getCurrentItem();

		const currentMatch =
			candidates.find((item) => item === currentItem)?.textContent?.trim() ?? "";

		const values = candidates.map((item) => item.textContent?.trim() ?? "");
		const nextMatch = getNextMatch(values, this.#search.current, currentMatch);
		const newItem = candidates.find((item) => item.textContent?.trim() === nextMatch);
		if (newItem) this.#onMatch(newItem);
		return newItem;
	}

	resetTypeahead() {
		this.#search.current = "";
	}

	get search() {
		return this.#search.current;
	}
}

export function getFirstNonCommentChild(element: HTMLElement | null) {
	if (!element) return null;
	for (const child of element.childNodes) {
		if (child.nodeType !== Node.COMMENT_NODE) {
			return child;
		}
	}
	return null;
}

/**
 * Determines if the click event truly occurred outside the content node.
 * This was added to handle password managers and other elements that may be injected
 * into the DOM but visually appear inside the content.
 */
export function isClickTrulyOutside(event: PointerEvent, contentNode: HTMLElement): boolean {
	const { clientX, clientY } = event;
	const rect = contentNode.getBoundingClientRect();

	return (
		clientX < rect.left || clientX > rect.right || clientY < rect.top || clientY > rect.bottom
	);
}

export function isOrContainsTarget(node: HTMLElement, target: Element) {
	return node === target || node.contains(target);
}

export function getOwnerDocument(el: Element | null | undefined) {
	return el?.ownerDocument ?? document;
}

import { on } from "svelte/events";

export type EventCallback<E extends Event = Event> = (event: E) => void;

/**
 * Creates a typed event dispatcher and listener pair for custom events
 * @template T - The type of data that will be passed in the event detail
 * @param eventName - The name of the custom event
 * @param options - CustomEvent options (bubbles, cancelable, etc.)
 */
export class CustomEventDispatcher<T = unknown> {
	readonly eventName: string;
	readonly options: Omit<CustomEventInit<T>, "detail">;

	constructor(
		eventName: string,
		options: Omit<CustomEventInit<T>, "detail"> = { bubbles: true, cancelable: true }
	) {
		this.eventName = eventName;
		this.options = options;
	}

	createEvent(detail?: T): CustomEvent<T> {
		return new CustomEvent<T>(this.eventName, {
			...this.options,
			detail,
		});
	}

	dispatch(element: EventTarget, detail?: T): CustomEvent<T> {
		const event = this.createEvent(detail);
		element.dispatchEvent(event);
		return event;
	}

	listen(
		element: EventTarget,
		callback: (event: CustomEvent<T>) => void,
		options?: AddEventListenerOptions
	) {
		const handler = (event: Event) => {
			callback(event as CustomEvent<T>);
		};

		return on(element, this.eventName, handler, options);
	}
}

import type { Getter, MaybeGetter } from "svelte-toolbelt";

export function get<T>(valueOrGetValue: MaybeGetter<T>): T {
	return typeof valueOrGetValue === "function"
		? (valueOrGetValue as Getter<T>)()
		: valueOrGetValue;
}

export function getDPR(element: Element): number {
	if (typeof window === "undefined") return 1;
	const win = element.ownerDocument.defaultView || window;
	return win.devicePixelRatio || 1;
}

export function roundByDPR(element: Element, value: number) {
	const dpr = getDPR(element);
	return Math.round(value * dpr) / dpr;
}

export function getFloatingContentCSSVars(name: string) {
	return {
		[`--bits-${name}-content-transform-origin`]: `var(--bits-floating-transform-origin)`,
		[`--bits-${name}-content-available-width`]: `var(--bits-floating-available-width)`,
		[`--bits-${name}-content-available-height`]: `var(--bits-floating-available-height)`,
		[`--bits-${name}-anchor-width`]: `var(--bits-floating-anchor-width)`,
		[`--bits-${name}-anchor-height`]: `var(--bits-floating-anchor-height)`,
	};
}

import type {
	FloatingElement,
	Middleware,
	MiddlewareData,
	Placement,
	ReferenceElement,
	Strategy,
} from "@floating-ui/dom";
import type { ReadableBox, WritableBox } from "svelte-toolbelt";

type ValueOrGetValue<T> = T | (() => T);

export type Measurable = {
	getBoundingClientRect: () => DOMRect;
};

export type UseFloatingOptions = {
	/**
	 * Represents the open/close state of the floating element.
	 * @default true
	 */
	open?: ValueOrGetValue<boolean | undefined>;
	/**
	 * Where to place the floating element relative to its reference element.
	 * @default 'bottom'
	 */
	placement?: ValueOrGetValue<Placement | undefined>;
	/**
	 * The type of CSS position property to use.
	 * @default 'absolute'
	 */
	strategy?: ValueOrGetValue<Strategy | undefined>;
	/**
	 * These are plain objects that modify the positioning coordinates in some fashion,
	 * or provide useful data for the consumer to use.
	 * @default undefined
	 */
	middleware?: ValueOrGetValue<Middleware[] | undefined>;
	/**
	 * Whether to use `transform` instead of `top` and `left` styles to
	 * position the floating element (`floatingStyles`).
	 * @default true
	 */
	transform?: ValueOrGetValue<boolean | undefined>;

	/**
	 * Reference / Anchor element to position the floating element relative to
	 */
	reference: ReadableBox<Measurable | HTMLElement | null>;

	/**
	 * Callback to handle mounting/unmounting of the elements.
	 * @default undefined
	 */
	whileElementsMounted?: (
		reference: ReferenceElement,
		floating: FloatingElement,
		update: () => void
	) => () => void;

	/**
	 * The offset from the reference element along the side axis.
	 * Used to detect bad coordinates during transitions.
	 * @default undefined
	 */
	sideOffset?: ValueOrGetValue<number | undefined>;

	/**
	 * The offset from the reference element along the alignment axis.
	 * Used to detect bad coordinates during transitions.
	 * @default undefined
	 */
	alignOffset?: ValueOrGetValue<number | undefined>;
};

export type UseFloatingReturn = {
	/**
	 * The reference element to position the floating element relative to.
	 */
	reference: ReadableBox<Measurable | HTMLElement | null>;

	/**
	 * The floating element to position.
	 */
	floating: WritableBox<HTMLElement | null>;

	/**
	 * The stateful placement, which can be different from the initial `placement` passed as options.
	 */
	placement: Readonly<Placement>;

	/**
	 * The type of CSS position property to use.
	 */
	strategy: Readonly<Strategy>;

	/**
	 * Additional data from middleware.
	 */
	middlewareData: Readonly<MiddlewareData>;

	/**
	 * The boolean that let you know if the floating element has been positioned.
	 */
	isPositioned: Readonly<boolean>;

	/**
	 * CSS styles to apply to the floating element to position it.
	 */
	floatingStyles: Readonly<{
		position: Strategy;
		top: string;
		left: string;
		transform?: string;
		willChange?: string;
	}>;

	/**
	 * The function to update floating position manually.
	 */
	update: () => void;
};

import { flushSync } from "svelte";
import { box } from "svelte-toolbelt";
import { describe, expect, it, vi } from "vitest";
import { useFloating } from "./use-floating.svelte.js";
import type { UseFloatingReturn } from "./types.js";

describe("useFloating", () => {
	it("ignores an update scheduled by whileElementsMounted after the owning effect is destroyed", () => {
		const referenceNode = document.createElement("button");
		const floatingNode = document.createElement("div");
		document.body.append(referenceNode, floatingNode);
		let placement = $state<"top" | "bottom">("bottom");
		// Every read of the `placement` option — the `$derived` in `useFloating`
		// only calls this while it is dirty and being re-run.
		const readPlacement = vi.fn(() => placement);
		let scheduledUpdate: (() => void) | undefined;
		let floating: UseFloatingReturn | undefined;

		const destroy = $effect.root(() => {
			floating = useFloating({
				reference: box.with(() => referenceNode),
				placement: readPlacement,
				// Stands in for floating-ui's `autoUpdate`, which hands `update` to
				// observers of its own.
				whileElementsMounted: (_reference, _floating, update) => {
					scheduledUpdate = update;
					return () => {};
				},
			});
			floating.floating.current = floatingNode;
		});

		try {
			flushSync();
			expect(scheduledUpdate).toBeTypeOf("function");

			destroy();
			// An option changes after teardown, as a prop does while the parent
			// re-renders, then an observer fires — floating-ui's
			// IntersectionObserver still can after `disconnect()`.
			placement = "top";
			flushSync();
			readPlacement.mockClear();
			expect(() => scheduledUpdate?.()).not.toThrow();

			expect(readPlacement).not.toHaveBeenCalled();
		} finally {
			referenceNode.remove();
			floatingNode.remove();
		}
	});
});

import { computePosition } from "@floating-ui/dom";
import { simpleBox } from "svelte-toolbelt";
import type { UseFloatingOptions, UseFloatingReturn } from "./types.js";
import { get, getDPR, roundByDPR } from "./floating-utils.svelte.js";

export function useFloating(options: UseFloatingOptions): UseFloatingReturn {
	/** Options */
	const whileElementsMountedOption = options.whileElementsMounted;
	const openOption = $derived(get(options.open) ?? true);
	const middlewareOption = $derived(get(options.middleware));
	const transformOption = $derived(get(options.transform) ?? true);
	const placementOption = $derived(get(options.placement) ?? "bottom");
	const strategyOption = $derived(get(options.strategy) ?? "absolute");
	const sideOffsetOption = $derived(get(options.sideOffset) ?? 0);
	const alignOffsetOption = $derived(get(options.alignOffset) ?? 0);
	const reference = options.reference;

	/** State */
	let x = $state(0);
	let y = $state(0);

	const floating = simpleBox<HTMLElement | null>(null);

	// svelte-ignore state_referenced_locally
	let strategy = $state(strategyOption);
	// svelte-ignore state_referenced_locally
	let placement = $state(placementOption);
	let middlewareData = $state({});
	let isPositioned = $state(false);
	let hasWhileMountedPosition = false;
	let updateRequestId = 0;
	// `update` is handed to `whileElementsMounted` (floating-ui's `autoUpdate`),
	// whose observers can still fire after the effect owning the option
	// `$derived`s above is destroyed. Reading them then warns `derived_inert`.
	let destroyed = false;
	const floatingStyles = $derived.by(() => {
		// preserve last known position when floating ref is null (during transitions)
		const xVal = floating.current ? roundByDPR(floating.current, x) : x;
		const yVal = floating.current ? roundByDPR(floating.current, y) : y;

		if (transformOption) {
			return {
				position: strategy,
				left: "0",
				top: "0",
				transform: `translate(${xVal}px, ${yVal}px)`,
				...(floating.current &&
					getDPR(floating.current) >= 1.5 && {
						willChange: "transform",
					}),
			};
		}

		return {
			position: strategy,
			left: `${xVal}px`,
			top: `${yVal}px`,
		};
	});

	/** Effects */
	let whileElementsMountedCleanup: (() => void) | undefined;

	function update() {
		if (destroyed) return;
		if (reference.current === null || floating.current === null) return;

		const referenceNode = reference.current;
		const floatingNode = floating.current;
		const requestId = ++updateRequestId;

		computePosition(referenceNode, floatingNode, {
			middleware: middlewareOption,
			placement: placementOption,
			strategy: strategyOption,
		}).then((position) => {
			// ignore stale async resolutions when newer updates were requested.
			if (requestId !== updateRequestId) return;
			// ignore stale resolutions after ref replacement.
			if (reference.current !== referenceNode || floating.current !== floatingNode) return;

			const referenceHidden = isReferenceHidden(referenceNode);
			if (referenceHidden) {
				// keep last good coordinates when the anchor disappears to avoid
				// a transient jump to viewport origin before close propagates.
				middlewareData = {
					...middlewareData,
					hide: {
						// oxlint-disable-next-line no-explicit-any
						...(middlewareData as any).hide,
						referenceHidden: true,
					},
				};
				return;
			}

			// ignore bad coordinates that cause jumping during close transitions
			if (!openOption && x !== 0 && y !== 0) {
				// if we had a good position and now getting coordinates near
				// the expected offset bounds during close, ignore it
				const maxExpectedOffset = Math.max(
					Math.abs(sideOffsetOption),
					Math.abs(alignOffsetOption),
					15
				);
				if (position.x <= maxExpectedOffset && position.y <= maxExpectedOffset) return;
			}

			x = position.x;
			y = position.y;
			strategy = position.strategy;
			placement = position.placement;
			middlewareData = position.middlewareData;
			isPositioned = true;
		});
	}

	function cleanup() {
		if (typeof whileElementsMountedCleanup === "function") {
			whileElementsMountedCleanup();
			whileElementsMountedCleanup = undefined;
		}
		updateRequestId++;
	}

	function attach() {
		cleanup();

		if (whileElementsMountedOption === undefined) {
			update();
			return;
		}

		if (!openOption) return;

		if (reference.current === null || floating.current === null) return;

		whileElementsMountedCleanup = whileElementsMountedOption(
			reference.current,
			floating.current,
			update
		);
	}

	function reset() {
		if (!openOption && floating.current === null) {
			isPositioned = false;
		}
	}

	function trackWhileMountedDeps() {
		return [
			middlewareOption,
			placementOption,
			strategyOption,
			sideOffsetOption,
			alignOffsetOption,
			openOption,
		] as const;
	}

	$effect(() => {
		if (whileElementsMountedOption !== undefined) return;
		if (!openOption) return;
		update();
	});
	$effect(attach);
	$effect(() => {
		if (whileElementsMountedOption === undefined) return;

		trackWhileMountedDeps();
		if (!openOption) {
			hasWhileMountedPosition = false;
			return;
		}

		if (!isPositioned) {
			hasWhileMountedPosition = false;
			return;
		}

		// skip the first post-position run, since autoUpdate already computed it
		if (!hasWhileMountedPosition) {
			hasWhileMountedPosition = true;
			return;
		}

		update();
	});
	$effect(reset);
	$effect(() => () => {
		destroyed = true;
		cleanup();
	});

	return {
		floating,
		reference,
		get strategy() {
			return strategy;
		},
		get placement() {
			return placement;
		},
		get middlewareData() {
			return middlewareData;
		},
		get isPositioned() {
			return isPositioned;
		},
		get floatingStyles() {
			return floatingStyles;
		},
		get update() {
			return update;
		},
	};
}

function isReferenceHidden(node: unknown): boolean {
	if (!(node instanceof Element)) return false;
	if (!node.isConnected) return true;
	if (node instanceof HTMLElement && node.hidden) return true;
	return node.getClientRects().length === 0;
}

import { getDocument, getWindow } from "svelte-toolbelt";
import { isBrowser, isElementHidden, isSelectableInput } from "./is.js";

export type FocusableTarget = HTMLElement | { focus: () => void };

/**
 * Handles `initialFocus` prop behavior for the
 * Calendar & RangeCalendar components.
 */
export function handleCalendarInitialFocus(calendar: HTMLElement) {
	if (!isBrowser) return;
	const selectedDay = calendar.querySelector<HTMLElement>("[data-selected]");
	if (selectedDay) return focusWithoutScroll(selectedDay);

	const today = calendar.querySelector<HTMLElement>("[data-today]");
	if (today) return focusWithoutScroll(today);

	const firstDay = calendar.querySelector<HTMLElement>("[data-calendar-date]");
	if (firstDay) return focusWithoutScroll(firstDay);
}

/**
 * A utility function that focuses an element without scrolling.
 */
export function focusWithoutScroll(element: HTMLElement) {
	const doc = getDocument(element);
	const win = getWindow(element);
	const scrollPosition = {
		x: win.pageXOffset || doc.documentElement.scrollLeft,
		y: win.pageYOffset || doc.documentElement.scrollTop,
	};
	element.focus();
	win.scrollTo(scrollPosition.x, scrollPosition.y);
}

/**
 * A utility function that focuses an element.
 */
export function focus(element?: FocusableTarget | null, { select = false } = {}) {
	if (!element || !element.focus) return;
	const doc = getDocument(element as HTMLElement);
	if (doc.activeElement === element) return;
	const previouslyFocusedElement = doc.activeElement;
	// prevent scroll on focus
	element.focus({ preventScroll: true });
	// only elect if its not the same element, it supports selection, and we need to select it
	if (element !== previouslyFocusedElement && isSelectableInput(element) && select) {
		element.select();
	}
}

/**
 * Attempts to focus the first element in a list of candidates.
 * Stops when focus is successful.
 */
export function focusFirst(
	candidates: HTMLElement[],
	{ select = false } = {},
	getActiveElement: () => HTMLElement | null
) {
	const previouslyFocusedElement = getActiveElement();
	for (const candidate of candidates) {
		focus(candidate, { select });
		if (getActiveElement() !== previouslyFocusedElement) return true;
	}
}

/**
 * Returns the first visible element in a list.
 * NOTE: Only checks visibility up to the `container`.
 */
export function findVisible(elements: HTMLElement[], container: HTMLElement) {
	for (const element of elements) {
		// we stop checking if it's hidden at the `container` level (excluding)
		if (!isElementHidden(element, container)) return element;
	}
}

/**
 * Returns a list of potential tabbable candidates.
 *
 * NOTE: This is only a close approximation. For example it doesn't take into account cases like when
 * elements are not visible. This cannot be worked out easily by just reading a property, but rather
 * necessitate runtime knowledge (computed styles, etc). We deal with these cases separately.
 *
 * See: https://developer.mozilla.org/en-US/docs/Web/API/TreeWalker
 * Credit: https://github.com/discord/focus-layers/blob/master/src/util/wrapFocus.tsx#L1
 */
export function getTabbableCandidates(container: HTMLElement) {
	const nodes: HTMLElement[] = [];
	const doc = getDocument(container);
	const walker = doc.createTreeWalker(container, NodeFilter.SHOW_ELEMENT, {
		// oxlint-disable-next-line no-explicit-any
		acceptNode: (node: any) => {
			const isHiddenInput = node.tagName === "INPUT" && node.type === "hidden";
			if (node.disabled || node.hidden || isHiddenInput) return NodeFilter.FILTER_SKIP;
			// `.tabIndex` is not the same as the `tabindex` attribute. It works on the
			// runtime's understanding of tabbability, so this automatically accounts
			// for any kind of element that could be tabbed to.
			return node.tabIndex >= 0 ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP;
		},
	});
	while (walker.nextNode()) nodes.push(walker.currentNode as HTMLElement);
	// we do not take into account the order of nodes with positive `tabIndex` as it
	// hinders accessibility to have tab order different from visual order.
	return nodes;
}

/**
 * A utility function that returns the first and last elements within a container that are
 * visible and focusable.
 */
export function getTabbableEdges(container: HTMLElement) {
	const candidates = getTabbableCandidates(container);
	const first = findVisible(candidates, container);
	const last = findVisible(candidates.reverse(), container);
	return [first, last] as const;
}

