import { watch } from "runed";
import { onDestroyEffect, type ReadableBoxedValues } from "svelte-toolbelt";
import { AnimationsComplete } from "./animations-complete.js";
import type { TransitionState } from "./attrs.js";

interface PresenceManagerOpts
	extends ReadableBoxedValues<{
		open: boolean;
		ref: HTMLElement | null;
	}> {
	onComplete?: () => void;
	enabled?: boolean;
	shouldSkipExitAnimation?: () => boolean;
}

export class PresenceManager {
	#opts: PresenceManagerOpts;
	#enabled: boolean;
	#afterAnimations: AnimationsComplete;
	#shouldRender = $state(false);
	#transitionStatus = $state<TransitionState>(undefined);
	#hasMounted = false;
	#transitionFrame: number | null = null;

	constructor(opts: PresenceManagerOpts) {
		this.#opts = opts;
		this.#shouldRender = opts.open.current;
		this.#enabled = opts.enabled ?? true;
		this.#afterAnimations = new AnimationsComplete({
			ref: this.#opts.ref,
			afterTick: this.#opts.open,
		});
		onDestroyEffect(() => this.#clearTransitionFrame());

		watch(
			() => this.#opts.open.current,
			(isOpen) => {
				if (!this.#hasMounted) {
					this.#hasMounted = true;
					return;
				}

				this.#clearTransitionFrame();

				if (!isOpen && this.#opts.shouldSkipExitAnimation?.()) {
					this.#shouldRender = false;
					this.#transitionStatus = undefined;
					this.#opts.onComplete?.();
					return;
				}

				if (isOpen) this.#shouldRender = true;
				this.#transitionStatus = isOpen ? "starting" : "ending";
				if (isOpen) {
					this.#transitionFrame = window.requestAnimationFrame(() => {
						this.#transitionFrame = null;
						if (this.#opts.open.current) {
							this.#transitionStatus = undefined;
						}
					});
				}

				if (!this.#enabled) {
					if (!isOpen) {
						this.#shouldRender = false;
					}
					this.#transitionStatus = undefined;
					this.#opts.onComplete?.();
					return;
				}

				this.#afterAnimations.run(() => {
					if (isOpen === this.#opts.open.current) {
						if (!this.#opts.open.current) {
							this.#shouldRender = false;
						}
						this.#transitionStatus = undefined;
						this.#opts.onComplete?.();
					}
				});
			}
		);
	}

	get shouldRender() {
		return this.#shouldRender;
	}

	get transitionStatus(): TransitionState {
		return this.#transitionStatus;
	}

	#clearTransitionFrame(): void {
		if (this.#transitionFrame === null) return;
		window.cancelAnimationFrame(this.#transitionFrame);
		this.#transitionFrame = null;
	}
}

import { type Box, type ReadableBox, box } from "svelte-toolbelt";
import { getElemDirection } from "./locale.js";
import { getDirectionalKeys } from "./get-directional-keys.js";
import { kbd } from "./kbd.js";
import type { Orientation } from "$lib/shared/index.js";
import { BROWSER } from "esm-env";
import { isHTMLElement } from "./is.js";

type RovingFocusGroupOptions = (
	| {
			/**
			 * The selector used to find the focusable candidates.
			 */
			candidateAttr: string;
			candidateSelector?: undefined;
	  }
	| {
			/**
			 * Custom candidate selector
			 */
			candidateSelector: string;
			candidateAttr?: undefined;
	  }
) & {
	/**
	 * The id of the root node
	 */
	rootNode: Box<HTMLElement | null>;

	/**
	 * Whether to loop through the candidates when reaching the end.
	 */
	loop: ReadableBox<boolean>;

	/**
	 * The orientation of the roving focus group. Used
	 * to determine how keyboard navigation should work.
	 */
	orientation: ReadableBox<Orientation>;

	/**
	 * A callback function called when a candidate is focused.
	 */
	onCandidateFocus?: (node: HTMLElement) => void;
};

export class RovingFocusGroup {
	readonly #opts: RovingFocusGroupOptions;
	readonly #currentTabStopId = box<string | null>(null);

	constructor(opts: RovingFocusGroupOptions) {
		this.#opts = opts;
	}

	getCandidateNodes() {
		if (!BROWSER || !this.#opts.rootNode.current) return [];

		if (this.#opts.candidateSelector) {
			const candidates = Array.from(
				this.#opts.rootNode.current.querySelectorAll<HTMLElement>(
					this.#opts.candidateSelector
				)
			);
			return candidates;
		} else if (this.#opts.candidateAttr) {
			const candidates = Array.from(
				this.#opts.rootNode.current.querySelectorAll<HTMLElement>(
					`[${this.#opts.candidateAttr}]:not([data-disabled])`
				)
			);
			return candidates;
		}

		return [];
	}

	focusFirstCandidate() {
		const items = this.getCandidateNodes();
		if (!items.length) return;
		items[0]?.focus();
	}

	handleKeydown(node: HTMLElement | null | undefined, e: KeyboardEvent, both: boolean = false) {
		const rootNode = this.#opts.rootNode.current;
		if (!rootNode || !node) return;

		const items = this.getCandidateNodes();
		if (!items.length) return;

		const currentIndex = items.indexOf(node);
		const dir = getElemDirection(rootNode);
		const { nextKey, prevKey } = getDirectionalKeys(dir, this.#opts.orientation.current);
		const loop = this.#opts.loop.current;

		const keyToIndex = {
			[nextKey]: currentIndex + 1,
			[prevKey]: currentIndex - 1,
			[kbd.HOME]: 0,
			[kbd.END]: items.length - 1,
		};

		if (both) {
			const altNextKey = nextKey === kbd.ARROW_DOWN ? kbd.ARROW_RIGHT : kbd.ARROW_DOWN;
			const altPrevKey = prevKey === kbd.ARROW_UP ? kbd.ARROW_LEFT : kbd.ARROW_UP;
			keyToIndex[altNextKey] = currentIndex + 1;
			keyToIndex[altPrevKey] = currentIndex - 1;
		}

		let itemIndex = keyToIndex[e.key];
		if (itemIndex === undefined) return;
		e.preventDefault();

		if (itemIndex < 0 && loop) {
			itemIndex = items.length - 1;
		} else if (itemIndex === items.length && loop) {
			itemIndex = 0;
		}

		const itemToFocus = items[itemIndex];
		if (!itemToFocus) return;
		itemToFocus.focus();
		this.#currentTabStopId.current = itemToFocus.id;
		this.#opts.onCandidateFocus?.(itemToFocus);
		return itemToFocus;
	}

	getTabIndex(node: HTMLElement | null | undefined) {
		const items = this.getCandidateNodes();
		const anyActive = this.#currentTabStopId.current !== null;

		if (node && !anyActive && items[0] === node) {
			this.#currentTabStopId.current = node.id;
			return 0;
		} else if (node?.id === this.#currentTabStopId.current) {
			return 0;
		}

		return -1;
	}

	setCurrentTabStopId(id: string) {
		this.#currentTabStopId.current = id;
	}

	focusCurrentTabStop() {
		const currentTabStopId = this.#currentTabStopId.current;
		if (!currentTabStopId) return;
		const currentTabStop = this.#opts.rootNode.current?.querySelector(`#${currentTabStopId}`);
		if (!currentTabStop || !isHTMLElement(currentTabStop)) return;
		currentTabStop.focus();
	}
}

import { type Getter, getDocument } from "svelte-toolbelt";
import { on } from "svelte/events";
import { watch } from "runed";
import { isElement } from "./is.js";
import type { Side } from "$lib/bits/utilities/floating-layer/use-floating-layer.svelte.js";

type Point = [number, number];

function isPointInPolygon(point: Point, polygon: Point[]): boolean {
	const [x, y] = point;
	let isInside = false;
	const length = polygon.length;
	for (let i = 0, j = length - 1; i < length; j = i++) {
		const [xi, yi] = polygon[i] ?? [0, 0];
		const [xj, yj] = polygon[j] ?? [0, 0];
		const intersect = yi >= y !== yj >= y && x <= ((xj - xi) * (y - yi)) / (yj - yi) + xi;
		if (intersect) {
			isInside = !isInside;
		}
	}
	return isInside;
}

function isInsideRect(point: Point, rect: DOMRect): boolean {
	return (
		point[0] >= rect.left &&
		point[0] <= rect.right &&
		point[1] >= rect.top &&
		point[1] <= rect.bottom
	);
}

function getSide(triggerRect: DOMRect, contentRect: DOMRect): Side {
	// determine which side the content is on relative to trigger
	const triggerCenterX = triggerRect.left + triggerRect.width / 2;
	const triggerCenterY = triggerRect.top + triggerRect.height / 2;
	const contentCenterX = contentRect.left + contentRect.width / 2;
	const contentCenterY = contentRect.top + contentRect.height / 2;

	const deltaX = contentCenterX - triggerCenterX;
	const deltaY = contentCenterY - triggerCenterY;

	if (Math.abs(deltaX) > Math.abs(deltaY)) {
		return deltaX > 0 ? "right" : "left";
	}
	return deltaY > 0 ? "bottom" : "top";
}

export interface SafePolygonOptions {
	enabled: Getter<boolean>;
	triggerNode: Getter<HTMLElement | null>;
	contentNode: Getter<HTMLElement | null>;
	onPointerExit: () => void;
	buffer?: number;
	transitIntentTimeout?: number;
	/** nodes that should not trigger a close when they become the relatedTarget on trigger leave (e.g. sibling triggers in singleton mode) */
	ignoredTargets?: Getter<HTMLElement[]>;
}

/**
 * Creates a safe polygon area that allows users to move their cursor between
 * the trigger and floating content without closing it.
 */
export class SafePolygon {
	readonly #opts: SafePolygonOptions;
	readonly #buffer: number;
	readonly #transitIntentTimeout: number | null;

	// tracks the cursor position when leaving trigger or content
	#exitPoint: Point | null = null;
	// tracks what we're moving toward: "content" when leaving trigger, "trigger" when leaving content
	#exitTarget: "trigger" | "content" | null = null;
	#transitTargets: HTMLElement[] = [];
	#trackedTriggerNode: HTMLElement | null = null;
	#leaveFallbackRafId: number | null = null;
	#transitIntentTimeoutId: number | null = null;

	#cancelLeaveFallback() {
		if (this.#leaveFallbackRafId !== null) {
			cancelAnimationFrame(this.#leaveFallbackRafId);
			this.#leaveFallbackRafId = null;
		}
	}

	#scheduleLeaveFallback() {
		this.#cancelLeaveFallback();
		this.#leaveFallbackRafId = requestAnimationFrame(() => {
			this.#leaveFallbackRafId = null;
			if (!this.#exitPoint || !this.#exitTarget) return;
			this.#clearTracking();
			this.#opts.onPointerExit();
		});
	}

	#cancelTransitIntentTimeout() {
		if (this.#transitIntentTimeoutId !== null) {
			clearTimeout(this.#transitIntentTimeoutId);
			this.#transitIntentTimeoutId = null;
		}
	}

	#scheduleTransitIntentTimeout() {
		if (this.#transitIntentTimeout === null) return;
		this.#cancelTransitIntentTimeout();
		this.#transitIntentTimeoutId = window.setTimeout(() => {
			this.#transitIntentTimeoutId = null;
			if (!this.#exitPoint || !this.#exitTarget) return;
			this.#clearTracking();
			this.#opts.onPointerExit();
		}, this.#transitIntentTimeout);
	}

	constructor(opts: SafePolygonOptions) {
		this.#opts = opts;
		this.#buffer = opts.buffer ?? 1;
		const transitIntentTimeout = opts.transitIntentTimeout;
		this.#transitIntentTimeout =
			typeof transitIntentTimeout === "number" && transitIntentTimeout > 0
				? transitIntentTimeout
				: null;

		watch(
			[opts.triggerNode, opts.contentNode, opts.enabled],
			([triggerNode, contentNode, enabled]) => {
				if (!triggerNode || !contentNode || !enabled) {
					this.#trackedTriggerNode = null;
					this.#clearTracking();
					return;
				}
				if (this.#trackedTriggerNode && this.#trackedTriggerNode !== triggerNode) {
					this.#clearTracking();
				}
				this.#trackedTriggerNode = triggerNode;

				const doc = getDocument(triggerNode);

				const handlePointerMove = (e: PointerEvent) => {
					this.#onPointerMove([e.clientX, e.clientY], triggerNode, contentNode);
				};

				const handleTriggerLeave = (e: PointerEvent) => {
					// when leaving trigger toward content, record exit point
					const target = e.relatedTarget;
					// if going directly to content, no need for polygon tracking
					if (isElement(target) && contentNode.contains(target)) {
						return;
					}
					// if moving to an ignored target (e.g. a sibling trigger), don't close —
					// the sibling's enter handler will take over
					const ignoredTargets = this.#opts.ignoredTargets?.() ?? [];
					if (
						isElement(target) &&
						ignoredTargets.some((n) => n === target || n.contains(target))
					) {
						return;
					}
					this.#transitTargets =
						isElement(target) && ignoredTargets.length > 0
							? ignoredTargets.filter((n) => target.contains(n))
							: [];
					// for unrelated elements, defer close decisions to pointer geometry checks.
					// this allows the cursor to pass through intermediate elements on the way
					// to content without immediately closing.
					this.#exitPoint = [e.clientX, e.clientY];
					this.#exitTarget = "content";
					this.#scheduleLeaveFallback();
				};

				const handleTriggerEnter = () => {
					// reached trigger, clear tracking
					this.#clearTracking();
				};

				const handleContentEnter = () => {
					// reached content, clear tracking
					this.#clearTracking();
				};

				const handleContentLeave = (e: PointerEvent) => {
					// when leaving content, check if going directly back to trigger
					const target = e.relatedTarget;
					if (isElement(target) && triggerNode.contains(target)) {
						// going directly to trigger, no polygon tracking needed
						return;
					}
					// set up polygon tracking toward trigger — pointermove decides whether to close
					this.#exitPoint = [e.clientX, e.clientY];
					this.#exitTarget = "trigger";
					this.#scheduleLeaveFallback();
				};

				return [
					on(doc, "pointermove", handlePointerMove),
					on(triggerNode, "pointerleave", handleTriggerLeave),
					on(triggerNode, "pointerenter", handleTriggerEnter),
					on(contentNode, "pointerenter", handleContentEnter),
					on(contentNode, "pointerleave", handleContentLeave),
				].reduce(
					(acc, cleanup) => () => {
						acc();
						cleanup();
					},
					() => {}
				);
			}
		);
	}

	#onPointerMove(clientPoint: Point, triggerNode: HTMLElement, contentNode: HTMLElement): void {
		// if no exit point recorded, nothing to check
		if (!this.#exitPoint || !this.#exitTarget) return;
		this.#cancelLeaveFallback();
		this.#scheduleTransitIntentTimeout();

		const triggerRect = triggerNode.getBoundingClientRect();
		const contentRect = contentNode.getBoundingClientRect();

		// check if pointer reached the target
		if (this.#exitTarget === "content" && isInsideRect(clientPoint, contentRect)) {
			this.#clearTracking();
			return;
		}
		if (this.#exitTarget === "trigger" && isInsideRect(clientPoint, triggerRect)) {
			this.#clearTracking();
			return;
		}

		if (this.#exitTarget === "content" && this.#transitTargets.length > 0) {
			for (const transitTarget of this.#transitTargets) {
				const transitRect = transitTarget.getBoundingClientRect();
				if (isInsideRect(clientPoint, transitRect)) return;
				const transitSide = getSide(triggerRect, transitRect);
				const transitCorridor = this.#getCorridorPolygon(
					triggerRect,
					transitRect,
					transitSide
				);
				if (transitCorridor && isPointInPolygon(clientPoint, transitCorridor)) return;
			}
		}

		// check if pointer is in the rectangular corridor between trigger and content
		const side = getSide(triggerRect, contentRect);
		const corridorPoly = this.#getCorridorPolygon(triggerRect, contentRect, side);
		if (corridorPoly && isPointInPolygon(clientPoint, corridorPoly)) {
			return;
		}

		// check if pointer is within the safe polygon from exit point to target
		const targetRect = this.#exitTarget === "content" ? contentRect : triggerRect;
		const safePoly = this.#getSafePolygon(this.#exitPoint, targetRect, side, this.#exitTarget);
		if (isPointInPolygon(clientPoint, safePoly)) {
			return;
		}

		// pointer is outside all safe zones - close
		this.#clearTracking();
		this.#opts.onPointerExit();
	}

	#clearTracking() {
		this.#exitPoint = null;
		this.#exitTarget = null;
		this.#transitTargets = [];
		this.#cancelLeaveFallback();
		this.#cancelTransitIntentTimeout();
	}

	/**
	 * Creates a rectangular corridor between trigger and content
	 * This prevents closing when cursor is in the gap between them
	 */
	#getCorridorPolygon(triggerRect: DOMRect, contentRect: DOMRect, side: Side): Point[] | null {
		const buffer = this.#buffer;

		switch (side) {
			case "top":
				return [
					[Math.min(triggerRect.left, contentRect.left) - buffer, triggerRect.top],
					[Math.min(triggerRect.left, contentRect.left) - buffer, contentRect.bottom],
					[Math.max(triggerRect.right, contentRect.right) + buffer, contentRect.bottom],
					[Math.max(triggerRect.right, contentRect.right) + buffer, triggerRect.top],
				];
			case "bottom":
				return [
					[Math.min(triggerRect.left, contentRect.left) - buffer, triggerRect.bottom],
					[Math.min(triggerRect.left, contentRect.left) - buffer, contentRect.top],
					[Math.max(triggerRect.right, contentRect.right) + buffer, contentRect.top],
					[Math.max(triggerRect.right, contentRect.right) + buffer, triggerRect.bottom],
				];
			case "left":
				return [
					[triggerRect.left, Math.min(triggerRect.top, contentRect.top) - buffer],
					[contentRect.right, Math.min(triggerRect.top, contentRect.top) - buffer],
					[contentRect.right, Math.max(triggerRect.bottom, contentRect.bottom) + buffer],
					[triggerRect.left, Math.max(triggerRect.bottom, contentRect.bottom) + buffer],
				];
			case "right":
				return [
					[triggerRect.right, Math.min(triggerRect.top, contentRect.top) - buffer],
					[contentRect.left, Math.min(triggerRect.top, contentRect.top) - buffer],
					[contentRect.left, Math.max(triggerRect.bottom, contentRect.bottom) + buffer],
					[triggerRect.right, Math.max(triggerRect.bottom, contentRect.bottom) + buffer],
				];
		}
	}

	/**
	 * Creates a triangular/trapezoidal safe zone from the exit point to the target
	 */
	#getSafePolygon(
		exitPoint: Point,
		targetRect: DOMRect,
		side: Side,
		exitTarget: "trigger" | "content"
	): Point[] {
		const buffer = this.#buffer * 4;
		const [x, y] = exitPoint;

		// when going back to trigger, we need to flip the side
		const effectiveSide = exitTarget === "trigger" ? this.#flipSide(side) : side;

		// create polygon points from cursor to target edges
		switch (effectiveSide) {
			case "top":
				return [
					[x - buffer, y + buffer],
					[x + buffer, y + buffer],
					[targetRect.right + buffer, targetRect.bottom],
					[targetRect.right + buffer, targetRect.top],
					[targetRect.left - buffer, targetRect.top],
					[targetRect.left - buffer, targetRect.bottom],
				];
			case "bottom":
				return [
					[x - buffer, y - buffer],
					[x + buffer, y - buffer],
					[targetRect.right + buffer, targetRect.top],
					[targetRect.right + buffer, targetRect.bottom],
					[targetRect.left - buffer, targetRect.bottom],
					[targetRect.left - buffer, targetRect.top],
				];
			case "left":
				return [
					[x + buffer, y - buffer],
					[x + buffer, y + buffer],
					[targetRect.right, targetRect.bottom + buffer],
					[targetRect.left, targetRect.bottom + buffer],
					[targetRect.left, targetRect.top - buffer],
					[targetRect.right, targetRect.top - buffer],
				];
			case "right":
				return [
					[x - buffer, y - buffer],
					[x - buffer, y + buffer],
					[targetRect.left, targetRect.bottom + buffer],
					[targetRect.right, targetRect.bottom + buffer],
					[targetRect.right, targetRect.top - buffer],
					[targetRect.left, targetRect.top - buffer],
				];
		}
	}

	#flipSide(side: Side): Side {
		switch (side) {
			case "top":
				return "bottom";
			case "bottom":
				return "top";
			case "left":
				return "right";
			case "right":
				return "left";
		}
	}
}

import type { AnyFn } from "./types.js";

export class SharedState<T extends AnyFn> {
	#factory: T;
	#subscribers = 0;
	#state: ReturnType<T> | undefined = $state();
	#scope: (() => void) | undefined;

	constructor(factory: T) {
		this.#factory = factory;
	}

	#dispose() {
		this.#subscribers -= 1;
		if (this.#scope && this.#subscribers <= 0) {
			this.#scope();
			this.#state = undefined;
			this.#scope = undefined;
		}
	}

	get(...args: Parameters<T>): ReturnType<T> {
		this.#subscribers += 1;
		if (this.#state === undefined) {
			this.#scope = $effect.root(() => {
				this.#state = this.#factory(...args);
			});
		}

		$effect(() => {
			return () => {
				this.#dispose();
			};
		});

		return this.#state!;
	}
}

export function shouldEnableFocusTrap({
