import { simpleBox, type WritableBox } from "svelte-toolbelt";

interface Machine<S> {
	[k: string]: { [k: string]: S };
}
type MachineState<T> = keyof T;
type MachineEvent<T> = keyof UnionToIntersection<T[keyof T]>;

// 🤯 https://fettblog.eu/typescript-union-to-intersection/
// oxlint-disable-next-line no-explicit-any
type UnionToIntersection<T> = (T extends any ? (x: T) => any : never) extends (x: infer R) => any
	? R
	: never;

export class StateMachine<M> {
	readonly state: WritableBox<MachineState<M>>;
	readonly #machine: M & Machine<MachineState<M>>;

	constructor(initialState: MachineState<M>, machine: M & Machine<MachineState<M>>) {
		this.state = simpleBox(initialState);
		this.#machine = machine;
		this.dispatch = this.dispatch.bind(this);
	}

	#reducer(event: MachineEvent<M>) {
		// @ts-expect-error  state.current is keyof M
		const nextState = this.#machine[this.state.current][event];
		return nextState ?? this.state.current;
	}

	dispatch(event: MachineEvent<M>) {
		this.state.current = this.#reducer(event);
	}
}

import type { Getter } from "svelte-toolbelt";

type ResizeCallback = () => void;

/**
 * A single `ResizeObserver` shared by every observed element in the app. Components like
 * `ScrollArea` create a handful of observers each, and multiple of them frequently watch the
 * same node, so allocating one observer per call site adds up quickly on pages with many
 * instances.
 */
let sharedObserver: ResizeObserver | null = null;
const observedNodes = new WeakMap<Element, Set<ResizeCallback>>();

function getSharedObserver(): ResizeObserver {
	sharedObserver ??= new ResizeObserver((entries) => {
		for (const entry of entries) {
			const callbacks = observedNodes.get(entry.target);
			if (!callbacks) continue;
			// copy so a callback that unsubscribes doesn't mutate the set mid-iteration
			for (const callback of [...callbacks]) callback();
		}
	});
	return sharedObserver;
}

/**
 * Observes `node` for size changes, returning a function that stops observing.
 *
 * Like a dedicated `ResizeObserver`, the callback fires once shortly after subscribing.
 */
function observeResize(node: Element, callback: ResizeCallback): () => void {
	let callbacks = observedNodes.get(node);

	if (callbacks === undefined) {
		callbacks = new Set();
		observedNodes.set(node, callbacks);
		callbacks.add(callback);
		getSharedObserver().observe(node);
	} else {
		callbacks.add(callback);
		// `observe` only delivers its initial entry for newly observed targets, so a second
		// subscriber to an already-observed node has to be kicked off manually.
		callback();
	}

	return () => {
		const current = observedNodes.get(node);
		if (!current) return;
		current.delete(callback);
		if (current.size) return;
		observedNodes.delete(node);
		sharedObserver?.unobserve(node);
	};
}

export class SvelteResizeObserver {
	#node: Getter<HTMLElement | null>;
	#onResize: () => void;
	constructor(node: Getter<HTMLElement | null>, onResize: () => void) {
		this.#node = node;
		this.#onResize = onResize;
		this.handler = this.handler.bind(this);
		$effect(this.handler);
	}

	handler() {
		let rAF = 0;
		const _node = this.#node();
		if (!_node) return;
		const unobserve = observeResize(_node, () => {
			cancelAnimationFrame(rAF);
			rAF = window.requestAnimationFrame(this.#onResize);
		});

		return () => {
			window.cancelAnimationFrame(rAF);
			unobserve();
		};
	}
}

import { focusable, isFocusable, isTabbable, tabbable } from "tabbable";
import { getDocument } from "svelte-toolbelt";

function getTabbableOptions() {
	return {
		getShadowRoot: true,
		displayCheck:
			// JSDOM does not support the `tabbable` library. To solve this we can
			// check if `ResizeObserver` is a real function (not polyfilled), which
			// determines if the current environment is JSDOM-like.
			typeof ResizeObserver === "function" &&
			ResizeObserver.toString().includes("[native code]")
				? "full"
				: "none",
	} as const;
}

/**
 * Gets all tabbable elements in the body and finds the next/previous tabbable element
 * from the `currentNode` based on the `direction` provided.
 * @param currentNode - the node we want to get the next/previous tabbable from
 */
export function getTabbableFrom(currentNode: HTMLElement, direction: "next" | "prev") {
	if (!isTabbable(currentNode, getTabbableOptions())) {
		return getTabbableFromFocusable(currentNode, direction);
	}
	const doc = getDocument(currentNode);
	const allTabbable = tabbable(doc.body, getTabbableOptions());
	if (direction === "prev") allTabbable.reverse();
	const activeIndex = allTabbable.indexOf(currentNode);
	if (activeIndex === -1) return doc.body;
	const nextTabbableElements = allTabbable.slice(activeIndex + 1);
	return nextTabbableElements[0];
}

export function getTabbableFromFocusable(currentNode: HTMLElement, direction: "next" | "prev") {
	const doc = getDocument(currentNode);
	if (!isFocusable(currentNode, getTabbableOptions())) return doc.body;

	// find all focusable nodes, since some elements may be focusable but not tabbable
	// such as context menu triggers
	const allFocusable = focusable(doc.body, getTabbableOptions());

	// find index of current node among focusable siblings
	if (direction === "prev") allFocusable.reverse();
	const activeIndex = allFocusable.indexOf(currentNode);
	if (activeIndex === -1) return doc.body;

	const nextFocusableElements = allFocusable.slice(activeIndex + 1);

	// find the next focusable node that is also tabbable
	return nextFocusableElements.find((node) => isTabbable(node, getTabbableOptions())) ?? doc.body;
}

import { onDestroyEffect } from "svelte-toolbelt";
import type { AnyFn } from "./types.js";

export class TimeoutFn<T extends AnyFn> {
	readonly #interval: number;
	readonly #cb: T;
	#timer: number | null = null;

	constructor(cb: T, interval: number) {
		this.#cb = cb;
		this.#interval = interval;

		this.stop = this.stop.bind(this);
		this.start = this.start.bind(this);

		onDestroyEffect(this.stop);
	}

	#clear() {
		if (this.#timer !== null) {
			window.clearTimeout(this.#timer);
			this.#timer = null;
		}
	}

	stop() {
		this.#clear();
	}

	start(...args: Parameters<T> | []) {
		this.#clear();
		this.#timer = window.setTimeout(() => {
			this.#timer = null;

			this.#cb(...args);
		}, this.#interval);
	}
}

